/* 文学常识（4 板块） */
window.YUWEN_DATA.sections = [{"key":"A","name":"中国文学·古代","desc":"先秦 → 秦汉 → 魏晋南北朝 → 唐 → 宋 → 元 → 明 → 清","count":280,"items":[{"id":"lp001","item":"儒家：先秦孔子创立、孟子发展的学派，核心主张“仁”“礼”“仁政”，为历代正统思想。","dynasty":"先秦","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp002","item":"道家：先秦以老子、庄子为代表的学派，主张“道法自然”“无为而治”，并称“老庄”。","dynasty":"先秦","cat":"文学流派","source":"https://m.baike.com/"},{"id":"wt001","item":"编年体：按年月日顺序记述史事的史书体例，代表作《春秋》《左传》《资治通鉴》。","dynasty":"先秦","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt002","item":"国别体：分国记事的史书体例，代表作《国语》《战国策》。","dynasty":"先秦","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt011","item":"语录体：记录人物言论的散文体，短小凝练，如《论语》。","dynasty":"先秦","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt013","item":"论：议论文体，以议论说理为主，如贾谊《过秦论》、苏洵《六国论》。","dynasty":"先秦","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt025","item":"古体诗（古风）：与近体诗相对，格律自由、篇幅不拘的诗体，四言、五言、七言、杂言皆可，如李白《蜀道难》；四言、五言、祁阳、杂言古诗；乐府诗（歌、行、吟、引...）；句数、字数、格律要求不严格；与近体诗相对，格律自由、篇幅不拘，四言、五言、七言、杂言皆可，不要求对仗","dynasty":"先秦","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"lp007","item":"《诗经》：我国第一部诗歌总集，收西周至春秋诗歌305篇，分风、雅、颂，赋、比、兴手法，是现实主义诗歌源头；我国最早的诗歌总集，收录西周初至春秋中叶诗歌305篇，又称\"诗三百\"。分风（160篇，民歌）、雅（105篇，正声）、颂（40篇，祭祀乐歌）三部分，主要表现手法为赋（铺陈）、比（比喻）、兴（起兴）意义：编成于公元前六世纪，共305篇，故又称作“诗三百”；《诗经》是我国最早的诗歌总集，相传为孔子编定；反映了西周初期到春秋中叶500年间的社会生活；《诗经》开创了我国现实主义的文学创作道路；《诗经》在章法结构上多采用重章叠句的形式；《采薇》即是一例。在语言上多采用双声叠韵连绵词、叠字来状物、拟声、穷貌","dynasty":"先秦","cat":"文学流派","source":"https://m.baike.com/"},{"id":"wt012","item":"诸子散文：春秋战国时期诸子百家阐述自家学说的散文，如《论语》《孟子》《庄子》《荀子》。","dynasty":"先秦","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"lp113","item":"《山海经》：我国古代保存神话最多的古籍，记山川地理、异物奇闻，含夸父逐日、精卫填海、鲧禹治水、刑天舞干戚等神话。","dynasty":"先秦","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp114","item":"甲骨卜辞：刻在龟甲兽骨上的占卜记录，是我国现存最早的成体系的文字，也是散文的萌芽。","dynasty":"先秦","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp115","item":"《尚书》：我国最早的记言历史散文集，所收为虞、夏、商、周之书，语言古奥，有\"佶屈聱牙\"之称；中国古代最早的一部历史文献汇编","dynasty":"先秦","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp116","item":"先秦散文分两类：历史散文（《尚书》《春秋》《左传》《国语》《战国策》）与诸子散文（《论语》《老子》《孟子》《庄子》《荀子》《韩非子》《墨子》）。","dynasty":"先秦","cat":"文体知识","source":"考纲文学常识扩展"},{"id":"lp117","item":"六经：即《诗》《书》《礼》《乐》《易》《春秋》，其中《乐》已亡佚，故后称\"五经\"。","dynasty":"先秦","cat":"文体知识","source":"考纲文学常识扩展"},{"id":"lp118","item":"\"关关雎鸠，在河之洲。窈窕淑女，君子好逑。\"——出自《诗经·周南·关雎》，为《诗经》首篇，写君子对淑女的思慕。","dynasty":"先秦","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp119","item":"\"路漫漫其修远兮，吾将上下而求索。\"——屈原《离骚》，表现诗人不懈追求理想的精神。","dynasty":"先秦","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"mj008","item":"“学而不思则罔，思而不学则殆。”——《论语·为政》。","dynasty":"春秋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj009","item":"“学而时习之，不亦说乎？有朋自远方来，不亦乐乎？”——《论语·学而》。","dynasty":"春秋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj010","item":"“三人行，必有我师焉。”——《论语·述而》。","dynasty":"春秋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj011","item":"“岁寒，然后知松柏之后凋也。”——《论语·子罕》。","dynasty":"春秋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj080","item":"“己所不欲，勿施于人。”——《论语·卫灵公》。","dynasty":"春秋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj081","item":"“君子坦荡荡，小人长戚戚。”——《论语·述而》。","dynasty":"春秋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj001","item":"左丘明：相传为春秋末期鲁国史官，为《左传》《国语》的作者。《左传》是我国第一部叙事详备的编年体史书，《国语》是我国最早的国别体史书；《左氏春秋》、《春秋左氏传》；先秦散文叙事之最，标志我国叙事散文的成熟；“多行不义必自毙”；郑庄公：阴险狡诈、老谋深算、胸有城府、工于心计、伪孝伪悌、善于应变；公叔段：贪婪狂妄、得寸进尺、愚昧无知；姜氏：褊狭昏聩","dynasty":"春秋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj002","item":"孔子（孔丘）：名丘，字仲尼，春秋末期鲁国人，儒家学派创始人，伟大的思想家、教育家。《论语》是记录孔子及其弟子言行的语录体散文集；名丘，字仲尼，春秋鲁国人，儒家学派创始人，思想家、教育家，被尊为\"至圣先师\"，思想核心为\"仁\"与\"礼\"。其言行由弟子辑为《论语》；五经（晚年修订）——《诗经》、《尚书》、《礼记》、《周易》、《春秋》","dynasty":"春秋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp121","item":"《论语》：儒家经典，语录体散文，由孔子弟子及再传弟子记录孔子及其弟子言行而成，共二十篇。南宋时与《大学》《中庸》《孟子》合称\"四书\"；《论语》（先秦时期的一部语录体散文集，主要记载孔子及弟子的言行，以记言为主）语录体议论性散文；比较忠实地记述了孔子的言行，也比较集中地反映了孔子的思想体系；是由孔子的弟子和再传弟子共同著录完成的","dynasty":"春秋","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp122","item":"老子（约前571—471）：姓李名耳，字聃，春秋楚国人，道家学派创始人，著《道德经》（《老子》）五千言，主张\"道法自然\"\"无为而治\"；字伯阳，谥号聃，又称李耳；思想主张：无为、道法自然为核心；《道德经》又称《老子》；《上善若水》老子学说的精髓，是辩证法思想；老子的语录；成书于战国前期，晚于《论语》；《老子》共八十一章，约五千言；上篇三十七章，称《道经》；下篇四十四章，称《德经》；故《老子》又称《道德经》","dynasty":"春秋","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp123","item":"《春秋》：我国第一部编年体史书，相传为孔子据鲁史修订而成，记事极简，寓褒贬于一字，后世称\"春秋笔法\"\"微言大义\"；第一部编年体史书，编年体史书之祖；孔子整理修订；纲目式记载；“春秋笔法”：寓褒贬于记事；“微言大义”：含蓄微妙的言语，精深切要的义理；“春秋三传”：《左传》《公羊传》《谷梁传》（编年体）","dynasty":"春秋","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp125","item":"\"三人行，必有我师焉；择其善者而从之，其不善者而改之。\"——出自《论语·述而》，讲虚心向他人学习。","dynasty":"春秋","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp126","item":"\"学而不思则罔，思而不学则殆。\"——出自《论语·为政》，论学与思的关系。","dynasty":"春秋","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp127","item":"\"上善若水，水善利万物而不争。\"——出自《老子》第八章，以水喻最高的善。","dynasty":"春秋","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp005","item":"纵横家：战国从事政治外交游说的学派，代表人物苏秦、张仪，《战国策》多记其事。","dynasty":"战国","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp006","item":"楚辞：战国后期屈原在楚地民歌基础上创立的新诗体，句式灵活、多用“兮”字，代表作《离骚》，又称“骚体”；与诗经并称风骚；由西汉刘向编纂成书；其本义即指楚地的歌辞；清人章学诚；“盖至战国而文章之变尽，至战国而著述之事专，至战国而后世之文体备。故论文于战国，而升降盛衰之故可知也。”；《文史通义》内篇《诗教上》","dynasty":"战国","cat":"文学流派","source":"https://m.baike.com/"},{"id":"mj005","item":"“路漫漫其修远兮，吾将上下而求索。”——屈原《离骚》。","dynasty":"战国","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj006","item":"“长太息以掩涕兮，哀民生之多艰。”——屈原《离骚》。","dynasty":"战国","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj007","item":"“尺有所短，寸有所长。”——屈原《卜居》。","dynasty":"战国","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj012","item":"“富贵不能淫，贫贱不能移，威武不能屈，此之谓大丈夫。”——《孟子·滕文公下》。","dynasty":"战国","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj013","item":"“得道者多助，失道者寡助。”——《孟子·公孙丑下》。","dynasty":"战国","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj014","item":"“生于忧患，死于安乐。”——《孟子·告子下》。","dynasty":"战国","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj015","item":"“吾生也有涯，而知也无涯。”——《庄子·养生主》。","dynasty":"战国","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj016","item":"“君子博学而日参省乎己，则知明而行无过矣。”——荀子《劝学》。","dynasty":"战国","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj017","item":"“青，取之于蓝，而青于蓝。”——荀子《劝学》。","dynasty":"战国","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj018","item":"“不积跬步，无以至千里；不积小流，无以成江海。”——荀子《劝学》。","dynasty":"战国","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj019","item":"“锲而舍之，朽木不折；锲而不舍，金石可镂。”——荀子《劝学》。","dynasty":"战国","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj082","item":"“民为贵，社稷次之，君为轻。”——《孟子·尽心下》。","dynasty":"战国","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj003","item":"孟子（孟轲）：名轲，字子舆，战国中期邹国人，儒家重要代表，被尊为“亚圣”。主张“性善论”“仁政”“民贵君轻”，著有《孟子》；名轲，字子舆，战国邹人，儒家代表人物，被尊为\"亚圣\"，主张\"仁政\"\"民贵君轻\"\"性善论\"，善用比喻与排比，气势磅礴。与弟子著《孟子》；名轲，字子舆——亚圣；孔孟：孔子和孟子；《孟子》（排比句式）；思想主张；仁政；宣扬王道、民本；民贵君轻；性善论；得天下英才而教育之；孟子：得天下英才而教育之；主要记录了孟子的谈话：孟子和其弟子共同所著；性善论；民本论；人格论","dynasty":"战国","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj004","item":"庄子（庄周）：名周，战国中期宋国人，道家学派代表人物，与老子并称“老庄”。其文汪洋恣肆，想象奇特，代表作《逍遥游》《秋水》，著有《庄子》（《南华经》）；名周，战国宋人，道家代表人物，与老子并称\"老庄\"，主张\"逍遥\"\"齐物\"，文风汪洋恣肆、想象奇特，著《庄子》（又称《南华经》），名篇有《逍遥游》《秋水》《齐物论》；名周，字子休，战国时期宋国人，世称南华真人；思想主张无为、天人合一、清静无为，与老子并称“老庄”；《庄子》又称《南华经》——最富浪漫色彩的先秦散文；艺术成就高：浪漫主义风格；\"汪洋辟阖，仪态万方，晚周诸子之作，莫能先也\"-鲁迅；8章《内篇》为庄子写；15章《外篇》；11章《杂篇》；《逍遥游》；“晚周诸子之作，莫能先也。”；鲁迅——《汉文学史纲要》","dynasty":"战国","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj005","item":"荀子（荀况）：名况，战国末期赵国人，先秦儒家集大成者，主张“性恶论”“天行有常”。代表作《劝学》，著有《荀子》；名况，字卿，战国赵人，儒家集大成者，主张\"性恶论\"\"制天命而用之\"，著《荀子》，名篇有《劝学》《天论》，文风质朴说理绵密；名况，字卿，战国时期赵国人；《荀子》（长篇专题性论说文）；《劝学》；思想主张：性恶论、天行有常、人定胜天","dynasty":"战国","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj019","item":"屈原：名平，字原，战国末期楚国贵族，我国第一位伟大的爱国诗人，开创楚辞体，代表作《离骚》《九歌》《九章》；名平，字原，战国楚人，我国第一位伟大的爱国诗人，楚辞体创立者。作《离骚》《九歌》《九章》《天问》，开创浪漫主义诗风，后世称\"骚体\"，与《诗经》并称\"风骚\"；名平，字原；“楚辞”文体，开创“香草美人”的传统；是中国最伟大、已知最早的的浪漫主义诗人；标志着中国诗歌进入了一个由集体歌唱到个人独唱的新时代；《橘颂》(中国诗歌史上第一首咏物诗）选自《九章》；主要作品；《离骚》（是中国古代诗歌史上最长的一首浪漫主义的政治抒情诗）；《九章》《九歌》《天问》；主要活动于楚怀王时期","dynasty":"战国","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj020","item":"宋玉：战国后期楚国人，屈原之后楚辞代表作家，与屈原并称“屈宋”，代表作《九辩》；主要活动于顷襄王时期；《九辨》；是一首政治抒情诗","dynasty":"战国","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp131","item":"韩非（约前280—前233）：战国末韩国人，法家集大成者，主张法术势结合、中央集权，著《韩非子》，名篇有《说难》《孤愤》《五蠹》，文风峻峭犀利，善用寓言（守株待兔、自相矛盾、滥竽充数）。","dynasty":"战国","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp132","item":"墨子（约前468—前376）：名翟，战国鲁人，墨家创始人，主张\"兼爱\"\"非攻\"\"尚贤\"\"节用\"，著《墨子》，文章质朴、逻辑性强；《墨子》；思想主张：兼爱、非攻、节用、尚贤","dynasty":"战国","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp134","item":"《左传》：我国第一部叙事详备的编年体史书，相传为左丘明所作，记事起于鲁隐公元年（前722），迄于鲁哀公二十七年（前468），长于战争描写与外交辞令；伯、仲、叔、季；左传：伯、仲、叔、季","dynasty":"战国","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp135","item":"《国语》：我国第一部国别体史书，分记周、鲁、齐、晋、郑、楚、吴、越八国史事，以记言为主，旧传左丘明作；《国语》（第一部国别体史书，以记载言论为主）记言为主，记事为辅；语言平实自然，明白流畅；《邵公谏弭谤》","dynasty":"战国","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp136","item":"《战国策》：国别体史书，西汉刘向编订，记战国游说之士的策谋与辞令，长于铺陈夸饰，名篇有《邹忌讽齐王纳谏》《触龙说赵太后》《荆轲刺秦王》刘向编纂；主要记录战国时期策士游说各国诸侯时陈谋献策或互相辩论的言辞；是一部有关记言的史料汇编；反映了民本思想；《苏秦始将连横》；守株待兔不是出自战國策","dynasty":"战国","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp137","item":"\"富贵不能淫，贫贱不能移，威武不能屈，此之谓大丈夫。\"——出自《孟子·滕文公下》，论大丈夫的品格。","dynasty":"战国","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp138","item":"\"生于忧患，死于安乐。\"——出自《孟子·告子下》，论忧患与安乐对人的影响。","dynasty":"战国","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp139","item":"\"吾生也有涯，而知也无涯。\"——出自《庄子·养生主》，言生命有限而知识无穷。","dynasty":"战国","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp140","item":"\"锲而不舍，金石可镂。\"——出自《荀子·劝学》，喻坚持不懈。","dynasty":"战国","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"wt015","item":"疏：臣下向皇帝分条陈述意见的奏章，又称“奏疏”，如李斯《谏逐客书》、晁错《论贵粟疏》。","dynasty":"秦","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"mj020","item":"“泰山不让土壤，故能成其大；河海不择细流，故能就其深。”——李斯《谏逐客书》。","dynasty":"秦","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj006","item":"李斯：秦代政治家，楚国上蔡人。代表作《谏逐客书》是秦代散文的代表，为秦国统一天下起了重要作用；秦代政治家、文学家，楚国上蔡人，助秦始皇统一六国，任丞相，著《谏逐客书》，为秦代散文代表作，铺陈排比、气势雄辩。","dynasty":"秦","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp142","item":"秦代文学成就有限，主要有吕不韦门客编《吕氏春秋》（杂家，含寓言\"刻舟求剑\"\"循表夜涉\"）与李斯《谏逐客书》。秦始皇焚书坑儒，文学凋敝。","dynasty":"秦","cat":"文体知识","source":"考纲文学常识扩展"},{"id":"lp143","item":"\"焚书坑儒\"：秦始皇三十四年（前213）采纳李斯建议焚毁民间所藏《诗》《书》百家语，次年坑杀方士儒生四百六十余人，是中国文化史上的重大损失。","dynasty":"秦","cat":"文化常识","source":"考纲文学常识扩展"},{"id":"lp008","item":"汉赋：汉代兴盛的铺陈辞赋，分骚赋、大赋（新体赋）、小赋，代表作家司马相如、扬雄、班固、张衡；汉代代表性文体，铺陈排比、辞采华美、规模宏大，分骚赋（贾谊）、大赋（司马相如、扬雄、班固、张衡）、小赋（抒情咏物）。","dynasty":"汉代","cat":"文学流派","source":"https://m.baike.com/"},{"id":"wt003","item":"纪传体：以人物传记为中心的史书体例，由司马迁《史记》创立，分本纪、世家、列传、表、书五体。","dynasty":"汉代","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt004","item":"通史：贯通各代、记叙自古及今史事的史书，如《史记》。","dynasty":"汉代","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt005","item":"断代史：只记某一朝代历史的史书，创始于班固《汉书》汉书；我国第一部断代体通史","dynasty":"汉代","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt006","item":"本纪：纪传体史书中记叙帝王事迹、提纲挈领的部分。","dynasty":"汉代","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt007","item":"世家：纪传体史书中记叙诸侯王及显赫家族历史的部分，如《陈涉世家》。","dynasty":"汉代","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt008","item":"列传：纪传体史书中记叙重要人物、民族及邻国事迹的传记。","dynasty":"汉代","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt009","item":"表：以表格形式谱列世系、人物和史事发展线索的部分；臣下向帝王陈情言事的一种文体，如诸葛亮《出师表》、李密《陈情表》。","dynasty":"汉代","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt010","item":"书（志）：纪传体中记载典章制度、天文地理等专史的部分，《史记》称“书”，《汉书》改称“志”；古代书信体散文，如司马迁《报任安书》、王安石《答司马谏议书》《尚书》；内容；《尚书》所录，为虞、夏、商、周各代典、谟、训、诰、誓、命等文献；意义；是我国现存最早的散文总集；原为夏商周原始历史文献，主要记载帝王的命令和言论；后来成为儒家的主要经典之一","dynasty":"汉代","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt021","item":"赋：汉代兴盛的文体，讲究铺陈排比、文采华丽，介于诗与散文之间，如司马相如《子虚赋》、苏轼《赤壁赋》（文赋）介于诗与散文之间的文体，讲究铺陈排比、辞采华美。汉赋（大赋）、魏晋骈赋、唐宋律赋、宋代文赋（如《赤壁赋》）","dynasty":"汉代","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt024","item":"乐府：本指汉代朝廷设立的音乐机构，后指其采集配乐的民歌及后人拟作的诗体，如《孔雀东南飞》《木兰诗》；汉代设立的音乐机构，负责采集民间歌谣配乐，后指其所采集及后人拟作的诗歌。代表作《孔雀东南飞》（我国古代最长的叙事诗）《陌上桑》《十五从军征》。","dynasty":"汉代","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"lp144","item":"司马迁（约前145—约前87）：字子长，西汉夏阳人，伟大的史学家、文学家，著《史记》，被鲁迅誉为\"史家之绝唱，无韵之离骚\"；字子长，西汉史学家、文学家，任太史令。历经十余年撰成我国第一部纪传体通史《史记》，被誉为“史家之绝唱，无韵之离骚”；与司马光并称“史界两司马”，与班固并称“班马”；两汉时期成就最高，影响最大，通过人物描写来反映历史面貌；内容：八书；十表；十二本纪；《项羽本纪》；三十世家；《孔子世家》；七十列传；《太史公自传》；《报任安书》","dynasty":"汉代","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp145","item":"《史记》：我国第一部纪传体通史，原名《太史公书》（又称《太史公记》《太史记》），西汉司马迁撰，位列\"二十四史\"之首。记述上自黄帝、下至汉武帝太初四年共三千余年史事，全书一百三十篇、五十二万六千五百余字，含十二本纪（记历代帝王政绩，《项羽本纪》为特例）、十表（大事年表）、八书（记典章制度，包括礼、乐、音律、历法、天文、封禅、水利、财用）、三十世家（记诸侯勋贵兴亡，《孔子世家》为特例）、七十列传（记重要人物言行，末篇为自序）。为纪传体史学奠基之作、我国传记文学的开端，标志古代史传文学发展达到高峰；与司马光《资治通鉴》并称\"史学双璧\"，与《汉书》《后汉书》《三国志》合称\"前四史\"。鲁迅誉为\"史家之绝唱，无韵之离骚\"；刘向称其\"善序事理，辩而不华，质而不俚\"。另有《报任安书》。","dynasty":"汉代","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp146","item":"班固（32—92）：字孟坚，东汉人，著《汉书》，我国第一部纪传体断代史，记西汉一朝史事，与《史记》《后汉书》《三国志》合称\"前四史\"；字孟坚，东汉史学家、文学家，撰成我国第一部纪传体断代史《汉书》；又善赋，作《两都赋》，其《咏史诗》是早期五言诗；《汉书》（第一部纪传体断代史)；《两都赋》（洛阳和长安）","dynasty":"汉代","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp147","item":"贾谊（前200—前168）：西汉政论家、文学家，著《过秦论》《陈政事疏》《吊屈原赋》《鵩鸟赋》，开汉赋先声；现今有作品传世的第一位汉赋作家；骚体赋代表《吊屈原赋》《鵩鸟赋》；贾长沙；西汉鸿文；鲁迅；《过秦论》；既是政论散文也是史论散文","dynasty":"汉代","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp148","item":"司马相如（约前179—前118）：西汉辞赋家，代表作《子虚赋》《上林赋》，为汉大赋代表，与卓文君爱情故事流传；《子虚赋》（汉大赋）《上林赋》（汉大赋）《长门赋》（骚体赋）；《上林赋》；《子虚赋》；子虚乌有；和卓文君的故事—《凤求凰》","dynasty":"汉代","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp151","item":"《古诗十九首》：东汉末年文人五言诗，收录于《文选》，语言朴素自然，长于抒情，被誉为\"五言之冠冕\"，标志五言诗的成熟。","dynasty":"汉代","cat":"文体知识","source":"考纲文学常识扩展"},{"id":"lp152","item":"\"人固有一死，或重于泰山，或轻于鸿毛。\"——出自司马迁《报任安书》，论死的价值。","dynasty":"汉代","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp153","item":"\"桃李不言，下自成蹊。\"——出自《史记·李将军列传》，喻品德高尚自然受人敬仰。","dynasty":"汉代","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"mj021","item":"“人固有一死，或重于泰山，或轻于鸿毛。”——司马迁《报任安书》。","dynasty":"西汉","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj022","item":"“桃李不言，下自成蹊。”——司马迁《史记·李将军列传》。","dynasty":"西汉","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj023","item":"“究天人之际，通古今之变，成一家之言。”——司马迁《报任安书》。","dynasty":"西汉","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj007","item":"晁错：西汉政论家，代表作《论贵粟疏》，主张重农贵粟，文风切实深刻。","dynasty":"西汉","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj009","item":"刘向：西汉经学家、目录学家、文学家，整理宫廷藏书，编订《战国策》，撰《说苑》《新序》，为目录学之祖；《战国策》一部国别体史书；《冯谖孟尝君》选自《战国策》；弹铗而歌、焚券市义、营造三窟、狡兔三窟、高枕无忧","dynasty":"西汉","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj021","item":"曹操：字孟德，沛国谯人，政治家、军事家、诗人。开建安文学新风，代表作《短歌行》《观沧海》《龟虽寿》；字孟德，东汉末政治家、军事家、诗人，建安文学开创者，诗风慷慨悲凉，代表作《观沧海》《龟虽寿》《短歌行》《蒿里行》；风格：气魄雄健、慷慨悲凉；《短歌行》（乐府旧题）；用朝露比喻人生短暂；用明月比喻自己的忧愁连绵不绝；以鹿鸣求伴象征对贤才的渴望，以山海能容引出自己怀虚若谷的表白；“青青子衿,悠悠我心。”用《诗经·郑风·子衿》；“呦呦鹿鸣”四句采用了《诗经·小雅·鹿鸣》；“越陌度迁”化用应邵《风俗通》；“周公吐哺”用周公旦（周文王之子）厚士的典故","dynasty":"东汉末","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp009","item":"建安文学：汉末建安时期以“三曹”“建安七子”为代表的文学，风格刚健梗概，称“建安风骨”（汉魏风骨）。","dynasty":"汉末三国","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp010","item":"三曹：汉魏间曹操、曹丕、曹植父子三人的并称，建安文学领袖；曹操、曹丕、曹植父子。建安七子：孔融、陈琳、王粲、徐幹、阮瑀、应玚、刘桢","dynasty":"汉末三国","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp011","item":"建安七子：建安时期七位文学家——孔融、陈琳、王粲、徐干、阮瑀、应玚、刘桢的并称；王粲（七子成就最高）、孔融、陈琳、徐干、阮瑀、应玚、刘桢；王粲；七子之冠冕；陈琳","dynasty":"汉末三国","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp012","item":"竹林七贤：三国魏正始年间嵇康、阮籍、山涛、向秀、刘伶、阮咸、王戎七位名士，崇尚老庄、纵酒放达；嵇康（诗歌多四言诗）、阮籍（诗歌多五言诗）、山涛、向秀、刘伶、王戎、阮咸；继承了建安风骨；嵇康；山涛；魏晋之际的嵇康、阮籍、山涛、向秀、刘伶、王戎、阮咸七人，好老庄、尚清谈","dynasty":"三国","cat":"文学流派","source":"https://m.baike.com/"},{"id":"zj022","item":"曹丕：字子桓，曹操次子，即魏文帝。代表作《燕歌行》是现存最早的完整七言诗，所著《典论·论文》是我国最早的文学批评专论；《燕歌行》；最早，最完整的七言诗；《典论·论文》；文学批评史上最早的一部专论性的文章；三国时期第一位伟大诗人；《燕歌行》是我国现存最早的文人七言诗；《典论·论文》我国文学批评史上第一部专题论文","dynasty":"三国魏","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj023","item":"曹植：字子建，曹操第三子，封陈王，谥思，世称陈思王。才高八斗，代表作《洛神赋》《白马篇》《七步诗》；我国第一位大力写作五言诗的人；建安成就最高；代表作：《七步诗》《洛神赋》《白马篇》《曹子建集》；《洛神赋》；《白马篇》；《增白马王彪》；字子建，曹操之子，建安文学代表，钟嵘《诗品》誉其\"骨气奇高，词采华茂\"，代表作《洛神赋》《白马篇》《七哀诗》。","dynasty":"三国魏","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj024","item":"诸葛亮：字孔明，蜀汉丞相。代表作《出师表》（《前出师表》），忠心耿耿，传诵千古；《前/后出师表》；《诫子书》","dynasty":"三国蜀","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp013","item":"太康诗风：西晋太康年间以陆机、潘岳为代表的诗风，讲求雕饰繁缛。","dynasty":"西晋","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp014","item":"左思风力：西晋左思诗风，继承建安风骨、精神豪迈，代表作《咏史》八首。","dynasty":"西晋","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp015","item":"田园诗派：东晋陶渊明开创，以描写田园隐居生活为主的诗派，为我国第一位田园诗人。","dynasty":"东晋","cat":"文学流派","source":"https://m.baike.com/"},{"id":"mj024","item":"“采菊东篱下，悠然见南山。”——陶渊明《饮酒》。","dynasty":"东晋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj025","item":"“久在樊笼里，复得返自然。”——陶渊明《归园田居》。","dynasty":"东晋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj025","item":"陶渊明：一名潜，字元亮，自号五柳先生，私谥靖节，东晋诗人。我国第一位田园诗人，代表作《桃花源记》《归去来兮辞》《饮酒》《归园田居》；《归园田居》（田园诗）；《饮酒》《拟古》《杂诗》（咏怀诗）；《五柳先生传》《桃花源记》（散文）；《归去来兮辞》（抒情小赋）；名潜，字元亮，世称靖节先生，东晋田园诗派开创者，中国第一位田园诗人。代表作《归园田居》《饮酒》《桃花源记》《归去来兮辞》，诗风平淡自然；名潜，字元亮，自号“五柳先生”，世称“靖节先生”","dynasty":"东晋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"wt038","item":"志怪小说：魏晋南北朝记录鬼神怪异故事的小说，如干宝《搜神记》。","dynasty":"魏晋南北朝","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt039","item":"志人小说：魏晋南北朝记录人物轶事言谈的小说，如刘义庆《世说新语》。","dynasty":"魏晋南北朝","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"lp157","item":"谢灵运（385—433）：南朝宋诗人，山水诗派开创者，善写自然山水，有\"池塘生春草，园柳变鸣禽\"名句；袭封康乐公，世称谢康乐，我国山水诗派开创者，与陶渊明并称“陶谢”。","dynasty":"魏晋南北朝","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp158","item":"刘勰（约465—约532）：南朝梁文学理论家，著《文心雕龙》，我国第一部体系完整的文学理论专著，提出\"原道\"\"征圣\"\"宗经\"；《文心雕龙》我国古代第一部文学评论专著","dynasty":"魏晋南北朝","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp159","item":"钟嵘（约468—约518）：南朝梁文学批评家，著《诗品》，我国第一部诗歌评论专著，品评汉至梁五言诗人一百二十余家，分上中下三品。","dynasty":"魏晋南北朝","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp160","item":"刘义庆（403—444）：南朝宋人，编《世说新语》，我国第一部笔记小说集，记汉末至东晋名士轶事，分德行、言语、政事、文学等三十六门。","dynasty":"魏晋南北朝","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp161","item":"干宝：东晋史学家、文学家，著《搜神记》，志怪小说代表作，含\"干将莫邪\"\"董永\"\"韩凭夫妇\"等故事。","dynasty":"魏晋南北朝","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp162","item":"骈文：盛行于南北朝，讲究对偶、声律、用典、辞藻，以四六句为主，代表作有庾信《哀江南赋》、王勃《滕王阁序》（唐）；全篇以双句（四六句）为主、讲究对仗和声律辞藻的文体，兴盛于南北朝，如王勃《滕王阁序》；垃圾；又称骈体文，讲究对偶、声律、用典、辞藻，多以四字六字相间成句，故称『四六文』。盛行于南北朝","dynasty":"魏晋南北朝","cat":"文体知识","source":"考纲文学常识扩展"},{"id":"lp163","item":"志怪小说与志人小说：志怪记鬼神怪异（干宝《搜神记》），志人记人物轶事（刘义庆《世说新语》），是唐传奇的源头。","dynasty":"魏晋南北朝","cat":"文体知识","source":"考纲文学常识扩展"},{"id":"lp164","item":"\"采菊东篱下，悠然见南山。\"——出自陶渊明《饮酒》其五，写归隐田园的自得心境。","dynasty":"魏晋南北朝","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp165","item":"\"老骥伏枥，志在千里；烈士暮年，壮心不已。\"——出自曹操《龟虽寿》，抒发老当益壮的豪情。","dynasty":"魏晋南北朝","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp016","item":"山水诗派：南朝宋谢灵运开创，以刻画自然山水景物为特色的诗派。","dynasty":"南朝宋","cat":"文学流派","source":"https://m.baike.com/"},{"id":"zj027","item":"鲍照：字明远，世称鲍参军，长于乐府歌行，代表作《拟行路难》十八首。","dynasty":"南朝宋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp017","item":"永明体：南朝齐永明年间形成、讲究声律对偶的新诗体，为格律诗先河，代表沈约、谢朓。","dynasty":"南朝齐","cat":"文学流派","source":"https://m.baike.com/"},{"id":"zj011","item":"郦道元：字善长，北魏地理学家、散文家。为《水经》作注，撰成《水经注》，是山水游记散文的先声。","dynasty":"北魏","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp018","item":"初唐四杰：初唐王勃、杨炯、卢照邻、骆宾王四位诗人的并称，开拓诗歌题材；王勃、杨炯、卢照邻、骆宾王。他们扭转齐梁浮艳诗风，扩大诗歌题材，为唐诗繁荣奠定基础；王勃、杨炯、卢照邻、骆宾王，扭转齐梁浮艳诗风，扩大诗歌题材","dynasty":"初唐","cat":"文学流派","source":"https://m.baike.com/"},{"id":"mj003","item":"“落霞与孤鹜齐飞，秋水共长天一色。”——王勃《滕王阁序》。","dynasty":"初唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj026","item":"“海内存知己，天涯若比邻。”——王勃《送杜少府之任蜀州》。","dynasty":"初唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj028","item":"王勃：字子安，初唐四杰之首，少年才俊，代表作《滕王阁序》《送杜少府之任蜀州》；字子安，“诗杰”；擅长五律和五绝；《送杜少府之任蜀州》《滕王阁序》；“海内存知己，天涯若比邻。”；字子安，初唐四杰之首，代表作《滕王阁序》《送杜少府之任蜀州》，\"海内存知己，天涯若比邻\"传诵千古。","dynasty":"初唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj101","item":"杨炯：初唐四杰之一，以边塞征战诗见长，代表作《从军行》；边塞诗五律；《从军行》","dynasty":"初唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj102","item":"卢照邻：初唐四杰之一，代表作《长安古意》；字升之，号幽忧子，以七言歌行为擅长；《长安古意》","dynasty":"初唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj103","item":"骆宾王：初唐四杰之一，七岁能诗，代表作《咏鹅》《讨武曌檄》；字观光，擅长七言歌行；《在狱咏蝉》《帝京集》《骆宾王文集》；初唐四杰之一，代表作《咏鹅》《在狱咏蝉》《讨武曌檄》，檄文气势磅礴。","dynasty":"初唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp169","item":"陈子昂（661—702）：唐代诗歌革新先驱，主张\"汉魏风骨\"，代表作《登幽州台歌》，\"前不见古人，后不见来者\"苍凉悲壮；字伯玉，初唐诗文革新运动倡导者之一；主张“兴寄”，“风骨”，被后人称为\"诗骨\"；《感遇》38首和《登幽州台歌》","dynasty":"初唐","cat":"文体知识","source":"考纲文学常识扩展"},{"id":"lp170","item":"\"海内存知己，天涯若比邻。\"——出自王勃《送杜少府之任蜀州》，写送别而不作悲语。","dynasty":"初唐","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp019","item":"王孟诗派（山水田园诗派）：唐代以王维、孟浩然为代表的山水田园诗派，并称“王孟”。","dynasty":"唐","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp020","item":"边塞诗派：唐代以高适、岑参为代表，以写边塞风光与征战生活为特色的诗派，并称“高岑”。","dynasty":"唐","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp021","item":"韩孟诗派：唐代以韩愈、孟郊为代表，追求奇险瘦硬的诗派。","dynasty":"唐","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp022","item":"郊寒岛瘦：对孟郊、贾岛诗风清苦寒涩的概括。","dynasty":"唐","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp023","item":"元白诗派（新乐府运动）：唐代以元稹、白居易为代表，主张“文章合为时而著，歌诗合为事而作”，提倡新乐府。","dynasty":"唐","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp024","item":"大历十才子：唐代大历时期以钱起、卢纶等为代表的十位诗人，风格清雅工整。","dynasty":"唐","cat":"文学流派","source":"https://m.baike.com/"},{"id":"wt020","item":"传：记叙人物生平事迹的传记文体，如《张中丞传后叙》。","dynasty":"唐","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt023","item":"古文：与魏晋以来骈俪文风相对，指先秦两汉式散行单句的散文，唐代韩愈、柳宗元倡导古文运动加以复兴。","dynasty":"唐","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt026","item":"近体诗：唐代形成的格律诗体，讲究平仄、对仗、押韵，分律诗和绝句；唐代定型的诗体，分律诗（八句）与绝句（四句），有五言、七言之别，讲究平仄、对仗、押韵，与古体诗（古风）相对；唐代定型的诗体，分律诗与绝句。律诗八句四联（首联、颔联、颈联、尾联），中间两联须对仗；绝句四句。有五言、七言之分，讲究平仄、押韵、对仗","dynasty":"唐","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt027","item":"律诗：八句、讲究平仄对仗押韵的近体诗，分五律、七律，如杜甫《登高》。","dynasty":"唐","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt028","item":"绝句：四句的短小近体诗，分五绝、七绝，如王昌龄《出塞》。","dynasty":"唐","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt014","item":"说：古代用以陈述见解、叙议结合的文体，如韩愈《师说》、周敦颐《爱莲说》。","dynasty":"唐","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt029","item":"词：起于唐、盛于宋的配乐诗体，又称“长短句”“诗余”，分小令、中调、长调，有词牌；起于唐、盛于宋，句子长短不齐，故称『长短句』。有词牌（曲调名）与词题。按字数分小令（58字以内）、中调（59—90字）、长调（91字以上）；按风格分婉约、豪放","dynasty":"唐","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt037","item":"传奇：唐宋时期的文言短篇小说，情节曲折、结构完整，如白行简《李娃传》、元稹《莺莺传》。","dynasty":"唐","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"mj001","item":"“业精于勤，荒于嬉；行成于思，毁于随。”——韩愈《进学解》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj027","item":"“欲穷千里目，更上一层楼。”——王之涣《登鹳雀楼》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj028","item":"“莫愁前路无知己，天下谁人不识君。”——高适《别董大》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj029","item":"“忽如一夜春风来，千树万树梨花开。”——岑参《白雪歌送武判官归京》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj030","item":"“洛阳亲友如相问，一片冰心在玉壶。”——王昌龄《芙蓉楼送辛渐》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj031","item":"“劝君更尽一杯酒，西出阳关无故人。”——王维《送元二使安西》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj032","item":"“独在异乡为异客，每逢佳节倍思亲。”——王维《九月九日忆山东兄弟》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj033","item":"“大漠孤烟直，长河落日圆。”——王维《使至塞上》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj034","item":"“明月松间照，清泉石上流。”——王维《山居秋暝》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj035","item":"“天生我材必有用，千金散尽还复来。”——李白《将进酒》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj036","item":"“长风破浪会有时，直挂云帆济沧海。”——李白《行路难》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj037","item":"“飞流直下三千尺，疑是银河落九天。”——李白《望庐山瀑布》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj038","item":"“安能摧眉折腰事权贵，使我不得开心颜。”——李白《梦游天姥吟留别》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj039","item":"“会当凌绝顶，一览众山小。”——杜甫《望岳》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj040","item":"“读书破万卷，下笔如有神。”——杜甫《奉赠韦左丞丈二十二韵》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj041","item":"“朱门酒肉臭，路有冻死骨。”——杜甫《自京赴奉先县咏怀五百字》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj042","item":"“无边落木萧萧下，不尽长江滚滚来。”——杜甫《登高》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj043","item":"“春蚕到死丝方尽，蜡炬成灰泪始干。”——李商隐《无题》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj044","item":"“身无彩凤双飞翼，心有灵犀一点通。”——李商隐《无题》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj045","item":"“此情可待成追忆，只是当时已惘然。”——李商隐《锦瑟》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj046","item":"“沉舟侧畔千帆过，病树前头万木春。”——刘禹锡《酬乐天扬州初逢席上见赠》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj047","item":"“山不在高，有仙则名；水不在深，有龙则灵。”——刘禹锡《陋室铭》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj048","item":"“同是天涯沦落人，相逢何必曾相识。”——白居易《琵琶行》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj049","item":"“野火烧不尽，春风吹又生。”——白居易《赋得古原草送别》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj050","item":"“回眸一笑百媚生，六宫粉黛无颜色。”——白居易《长恨歌》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj051","item":"“曾经沧海难为水，除却巫山不是云。”——元稹《离思》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj052","item":"“商女不知亡国恨，隔江犹唱后庭花。”——杜牧《泊秦淮》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj053","item":"“东风不与周郎便，铜雀春深锁二乔。”——杜牧《赤壁》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj054","item":"“二十四桥明月夜，玉人何处教吹箫。”——杜牧《寄扬州韩绰判官》。","dynasty":"唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj012","item":"韩愈：字退之，自谓郡望昌黎，世称韩昌黎，唐代古文运动领袖，“唐宋八大家”之首，与柳宗元并称“韩柳”。主张“文以载道”“文道合一”，代表作《师说》《进学解》《张中丞传后叙》；字退之，世称韩昌黎，唐代文学家、思想家，古文运动领袖，被列为\"唐宋八大家\"之首，倡导\"文以载道\"。代表作《师说》《马说》《进学解》《祭十二郎文》；大力倡导古文，多长篇古体诗，主张用散文体创作；以气势雄放和意象诡奇见长，带有“以文为诗”的特点；提出\"唯陈言之务去\"、“辞必已出”；苏轼评：“文起八代之衰。”；《早春呈水部张十八员外》张十八：张籍（中唐）字退之，世称“韩昌黎”毛泽东认为，文学作品，包括诗，不要把话说尽了，而韩愈的文章和诗就是把话讲完了；黄庭坚：老杜作诗，退之作文，无一字无来处。盖后人读书少，故谓韩、杜自作此语耳。[70]","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj013","item":"柳宗元：字子厚，河东人，世称柳河东，唐代古文运动代表，与韩愈并称“韩柳”。作《永州八记》开创山水游记，代表作《捕蛇者说》《小石潭记》；字子厚，世称“柳柳州”，“柳河东”，反对骈文；中唐古文运动倡导者，唐宋八大家之一，强调文以载道，文道合一，以道为主；与韩愈并称“韩柳”；《柳河东集》《永州八记》；寓言文《黔之驴》，传记文与抒情文《捕蛇者说》，山水游记《永州八记》；《种树郭橐驼传》；带有寓言性质的传记散文，兼有传记文和寓言的特点；类比，对比，文章大量运用对话，选材上以小见大；字子厚，世称柳河东，唐代文学家，与韩愈并称\"韩柳\"，古文运动领袖。代表作《永州八记》（含《小石潭记》《钴鉧潭西小丘记》）《捕蛇者说》《三戒》。","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj029","item":"贺知章：字季真，自号四明狂客，唐代诗人，代表作《回乡偶书》《咏柳》。","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj030","item":"王之涣：唐代边塞诗人，代表作《登鹳雀楼》《凉州词》；边塞诗人，擅长五言诗，以描写边塞风光为主；《登鹳雀楼》、《凉州词》“黄河远上白云间，一片孤城万仞山。羌笛何须怨杨柳，春风不度玉门关。”","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj031","item":"孟浩然：襄州襄阳人，世称孟襄阳，唐代山水田园诗派代表，与王维并称“王孟”，代表作《过故人庄》《春晓》；以田园诗歌为主，山水田园派，与王维合称“王孟”；《过故人庄》《宿建德江》《春晓》《望洞庭湖赠张丞相》；名浩，字浩然，号孟山人；清幽淡雅；《临洞庭湖赠张丞相》；《过故人庄》；唐代山水田园诗人，与王维并称\"王孟\"，代表作《过故人庄》《春晓》。","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj032","item":"王维：字摩诘，号摩诘居士，世称王右丞。唐代山水田园诗派代表，诗中有画、画中有诗，被尊为“诗佛”，代表作《山居秋暝》《使至塞上》；字摩诘，号“诗佛”，世称“右丞相”、“右拾遗”；诗歌风格：清新淡雅；盛唐田园山水派代表人物；苏轼赞曰“诗中有画，画中有诗，诗中有禅”；早起思想较为积极，希冀在政治上有所作为，在四十岁以后，是半官半隐的生活；《使之塞上》“大漠孤烟直，长河落日圆。”；《山居秋暝》（五言律诗，山水诗，采用以动写静的手法）；“随意春方歇，王孙自可留。”选自《楚辞·招隐士》反用其意（用典）；诗佛；人才；字摩诘，号摩诘居士；前期有政治热情；《使至塞上》、《观猎》；后期则多禅趣；《山居秋暝》；苏轼《书摩诘蓝田烟雨图》更明确地指出：“味摩诘之诗，诗中有画；观摩诘之画，画中有诗。”；字摩诘，唐代山水田园诗派代表，与孟浩然并称\"王孟\"，苏轼评其\"诗中有画，画中有诗\"。代表作《山居秋暝》《使至塞上》。","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj033","item":"李白：字太白，号青莲居士，浪漫主义大诗人，被尊为“诗仙”，与杜甫并称“李杜”，代表作《蜀道难》《将进酒》《行路难》；字太白，号青莲居士，又号“谪仙人”；诗仙；天才；盛唐之音的杰出代表，诗风豪放飘逸；字太白，号青莲居士，唐代伟大的浪漫主义诗人，被誉为\"诗仙\"。诗风豪放飘逸、想象奇特，代表作《将进酒》《蜀道难》《梦游天姥吟留别》《静夜思》；字太白，号青莲居士，世称“诗仙”；是我国古代继屈原之后的又一位伟大的浪漫主义诗人；酒入豪肠，七分酿成了月光，余下三分，啸成剑气，绣口一吐，就半个盛唐。——余光中；创造古代积极浪漫主义文学高峰，为唐诗的繁荣与发展打开了新局面，开创了中国古典诗歌的黄金时代","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj034","item":"杜甫：字子美，自号少陵野老，被尊为“诗圣”，其诗多反映民生疾苦，称“诗史”，代表作“三吏”“三别”《登高》《春望》；字子美，自号少陵野老；诗圣；地才；集大成的诗人，且有继往开来之功，诗风沉郁顿挫；“三吏”；《石壕吏》、《新安吏》、《潼关吏》；“三别”；《新婚别》、《无家别》、《垂老别》；字子美，自号少陵野老，唐代伟大的现实主义诗人，被誉为\"诗圣\"，其诗被称为\"诗史\"。诗风沉郁顿挫，代表作\"三吏\"\"三别\"《春望》《登高》《茅屋为秋风所破歌》；字子美，自称“少陵野老”，世称“杜拾遗”、“杜工部”；是中国诗歌史上的集大成者；唐代伟大的现实主义诗人，与李白并称“李杜”；被称为“诗圣”，其诗被称为“诗史”；诗歌风格多样，但以沉郁顿挫为主，忧国忧民，寄世情怀；三吏（《新安吏》《石壕吏》《潼关吏》）三别（《新婚别》《垂老别》《无家别》）；《蜀相》（七言律诗，怀古诗）","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj035","item":"高适：字达夫，唐代边塞诗派代表，与岑参并称“高岑”，代表作《燕歌行》；字达夫，边塞诗派，写当时边地形势和士兵疾苦；《燕歌行》、《别董大》；字达夫；边塞诗；《别董大》","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj036","item":"岑参：唐代边塞诗派代表，代表作《白雪歌送武判官归京》；边塞诗派，诗歌富有浪漫主义特色；岑参的诗想象丰富，意境新奇，气势磅礴，风格奇峭，词采瑰丽；诗歌风格：新奇壮丽、雄奇瑰丽；诗人陆游曾称赞说“太白、子美之后一人而已”；与高适齐名，并称“高岑”；《白雪歌送武判官归京》“忽如一夜春风来，千树万树梨花开。”；雪中送别诗、边塞诗、七言歌行体","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj037","item":"王昌龄：字少伯，唐代边塞诗人，尤擅七绝，被誉“七绝圣手”，代表作《出塞》《芙蓉楼送辛渐》；边塞诗派代表人物，西北边塞；“诗家天子王江宁之称”，“七绝圣手”，世称“王龙标”；诗风：气势雄浑，格调高昂，充满积极向上的精神；《出塞》“但使龙城飞将在，不教胡马度阴山。”；《从军行》（其四）是一首七言绝句，“黄沙百战穿金甲，不破楼兰终不还。”；字少伯；被称为“七绝圣手”，诗家夫子（也叫诗家天子），并在这一领域与李白同领风骚；《从军行》；《出塞》——唐人七绝的压卷之作；秦时明月汉时关，万里长征人未还。但使龙城飞将在，不教胡马度阴山","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj038","item":"崔颢：唐代诗人，代表作《黄鹤楼》，相传李白为之搁笔。","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj039","item":"孟郊：字东野，唐代诗人，诗风清苦寒涩，与贾岛并称“郊寒岛瘦”，代表作《游子吟》；字东野，号“诗囚”；与贾岛（诗奴）齐名，人称“郊寒岛瘦”；诗歌风格：瘦硬奇警；代表作《游子吟》","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj040","item":"贾岛：字阆仙，唐代苦吟诗人，“推敲”典故所出，与孟郊并称“郊寒岛瘦”。","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj041","item":"李贺：字长吉，浪漫主义诗人，想象奇诡，被称为“诗鬼”，代表作《雁门太守行》；字长吉，人称“李昌谷”“诗鬼”；开创“长吉体”诗歌；诗歌特色：想象丰富奇特，语言瑰丽奇峭；唐朝中期浪漫主义诗人，与诗仙李白、李商隐并称“唐代三李”；留下了“黑云压城城欲摧”，“雄鸡一声天下白”，“天若有情天亦老”等千古佳句。著有《昌谷集》","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj042","item":"白居易：字乐天，晚号香山居士。唐代新乐府运动倡导者，主张“文章合为时而著，歌诗合为事而作”，代表作《长恨歌》《琵琶行》《卖炭翁》；字乐天，号香山居士，唐代现实主义诗人，与元稹并称\"元白\"，倡导新乐府运动，主张\"文章合为时而著，歌诗合为事而作\"。代表作《长恨歌》《琵琶行》《卖炭翁》；字乐天，号“香山居士”，人称“白香山”，“诗魔”“诗王”之称；中唐新乐府运动倡导者，唐代伟大现实主义诗人；与好友元稹诗歌风格相近，世称“元白”；唐代诗人中诗歌作品流传下来最多的诗人，有3000首左右；主张倡导“文章合为时而著，歌诗合为事而作”——（《秦中吟》《新乐府》是这方面的代表作）","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj043","item":"元稹：字微之，与白居易共同倡导新乐府运动，并称“元白”，代表作《莺莺传》《离思》；字微之；中唐新乐府运动倡导者；唐传奇《莺莺传》，讲述贫寒书生张生对没落贵族女子崔莺莺始乱终弃的爱情悲剧故事","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj044","item":"刘禹锡：字梦得，唐代诗人、哲学家，代表作《陋室铭》《酬乐天扬州初逢席上见赠》；字梦得，唐代文学家，有\"诗豪\"之称，代表作《陋室铭》《乌衣巷》《酬乐天扬州初逢席上见赠》。","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj045","item":"杜牧：字牧之，号樊川居士，晚唐诗人，与李商隐并称“小李杜”，代表作《阿房宫赋》《泊秦淮》《赤壁》；字牧之，号“樊川居士”，人称“小杜”；与李商隐并称“小李杜”，以七言绝句著称；《泊秦淮》《清明》《江南春绝句》；擅长文赋《阿房宫赋》","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj046","item":"李商隐：字义山，号玉溪生，晚唐诗人，无题诗独树一帜，与杜牧并称“小李杜”，代表作《无题》《锦瑟》《夜雨寄北》；字义山，号“玉谿生”；与温庭筠合称“温李”，与温庭筠诗歌风格相近；写了大量无题诗，《无题》（七言律诗）“相见时难别亦难，东风无力百花残。”，“春蚕到死丝方尽，蜡炬成灰泪始干。”","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj047","item":"温庭筠：字飞卿，晚唐诗人、词人，花间词派鼻祖，与李商隐并称“温李”；字飞卿；第一位大量写词的文人，“花间词”派鼻祖；其诗辞藻华丽，浓艳精致，内容多闺情；《菩萨蛮》","dynasty":"唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp176","item":"高适（约704—765）、岑参（约715—770）：唐代边塞诗派代表，并称\"高岑\"，风格雄浑悲壮。高适《燕歌行》、岑参《白雪歌送武判官归京》。","dynasty":"唐","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp180","item":"李商隐（约813—约858）、杜牧（803—约852）：晚唐诗人，并称\"小李杜\"。李商隐《锦瑟》《无题》《夜雨寄北》含蓄深情；杜牧《泊秦淮》《阿房宫赋》《山行》俊爽峭健。","dynasty":"唐","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp182","item":"古文运动：唐代韩愈、柳宗元倡导的散文革新运动，反对六朝以来的骈文，主张恢复先秦两汉散文传统，\"文以明道\"，对后世影响深远；韩愈、柳宗元主张用散文体创作反对骈文；唐代韩愈、柳宗元倡导的散文革新运动，反对骈文，主张『文以明道』，恢复先秦两汉散文传统。宋代欧阳修等继起","dynasty":"唐","cat":"文体知识","source":"考纲文学常识扩展"},{"id":"lp183","item":"新乐府运动：中唐白居易、元稹倡导的诗歌革新运动，主张\"文章合为时而著，歌诗合为事而作\"，用新题写时事，反映现实；元稹、白居易（元白诗派）以新题写时事","dynasty":"唐","cat":"文体知识","source":"考纲文学常识扩展"},{"id":"lp184","item":"\"天生我材必有用，千金散尽还复来。\"——出自李白《将进酒》，抒发自信豪迈之情。","dynasty":"唐","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp185","item":"\"无边落木萧萧下，不尽长江滚滚来。\"——出自杜甫《登高》，写秋景苍茫，格律精严，被誉为\"古今七律第一\"。","dynasty":"唐","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp186","item":"\"安得广厦千万间，大庇天下寒士俱欢颜。\"——出自杜甫《茅屋为秋风所破歌》，表现推己及人的博大胸怀。","dynasty":"唐","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp187","item":"\"同是天涯沦落人，相逢何必曾相识。\"——出自白居易《琵琶行》，写同病相怜之感。","dynasty":"唐","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp188","item":"\"落霞与孤鹜齐飞，秋水共长天一色。\"——出自王勃《滕王阁序》，写景名句，色彩明丽、意境开阔。","dynasty":"唐","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp189","item":"\"春眠不觉晓，处处闻啼鸟。夜来风雨声，花落知多少。\"——出自孟浩然《春晓》。","dynasty":"唐","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp190","item":"\"大漠孤烟直，长河落日圆。\"——出自王维《使至塞上》，写塞外壮阔景象。","dynasty":"唐","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp025","item":"小李杜：晚唐诗人李商隐、杜牧的并称，以别于盛唐的李（白）杜（甫）。","dynasty":"晚唐","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp026","item":"花间词派：晚唐五代以温庭筠为鼻祖、后蜀《花间集》为代表的词派，风格绮丽婉约。","dynasty":"晚唐五代","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp027","item":"南唐词派：五代南唐以冯延巳、李璟、李煜为代表的词派，抒情深挚。","dynasty":"五代南唐","cat":"文学流派","source":"https://m.baike.com/"},{"id":"mj055","item":"“问君能有几多愁？恰似一江春水向东流。”——李煜《虞美人》。","dynasty":"南唐","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj048","item":"李煜：字重光，世称李后主，南唐亡国之君，著名词人，代表作《虞美人》《浪淘沙》；千古词帝；史称后主；其词主要收集在《南唐二主词》中；《南唐二主词》，系南唐中主李璟、后主李煜撰；约成书于南宋；“五代之冠”、“千古词帝”，南唐二主，李后主，字重光；五代最有成就的词人，洞晓音韵，工书善画；前期风格：柔靡绮丽，多宫廷享乐生活、男女之情；后期风格:亡国之痛、思乡之情；“国家不幸诗家幸，话到沧桑语便工。”；被王维评论：“遂变伶工之词（男女爱情、宫廷绮靡）而为士大夫之词。”","dynasty":"南唐","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp028","item":"豪放派：宋词中风格豪迈奔放的流派，以苏轼、辛弃疾为代表，称“苏辛”。","dynasty":"宋","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp029","item":"婉约派：宋词中风格委婉含蓄的流派，代表柳永、李清照、周邦彦、姜夔。","dynasty":"宋","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp030","item":"江西诗派：宋代以黄庭坚为宗师的诗歌流派，论诗主张“点铁成金”“夺胎换骨”，宋末方回提出“一祖三宗”——祖为杜甫，宗为黄庭坚、陈师道、陈与义。","dynasty":"宋","cat":"文学流派","source":"https://m.baike.com/"},{"id":"wt019","item":"记：以记叙为主、可兼议论抒情的杂记文体，多记亭台山水、人事杂事，如范仲淹《岳阳楼记》、欧阳修《醉翁亭记》。","dynasty":"宋","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt030","item":"豪放词派：风格豪迈奔放的词派，以苏轼、辛弃疾为代表，并称“苏辛”。","dynasty":"宋","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt031","item":"婉约词派：风格委婉含蓄的词派，以柳永、李清照为代表。","dynasty":"宋","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt035","item":"话本：宋代民间说书人演讲所用的故事底本，是白话小说的萌芽。","dynasty":"宋","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"mj069","item":"“生当作人杰，死亦为鬼雄。”——李清照《夏日绝句》。","dynasty":"宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj070","item":"“寻寻觅觅，冷冷清清，凄凄惨惨戚戚。”——李清照《声声慢》。","dynasty":"宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj057","item":"李清照：号易安居士，宋代女词人，婉约词派代表，代表作《声声慢》《一剪梅》《武陵春》，有《漱玉词》；号易安居士，宋代女词人，婉约词派代表，词风前期清丽明快、后期悲凉沉郁。代表作《声声慢》《如梦令》《醉花阴》《夏日绝句》；号易安居士，婉约词派，有“千古第一才女”之称，与辛弃疾（幼安）并称“济南二安”；提出“词别是一家”之说，崇尚典雅；南渡前词风比较开朗，悠闲生活，自然之美。幸福快乐浪漫《如梦令》（昨夜雨疏风骤）；中期词相思离别。离恨别愁，凄凉味道。《一剪梅》；南渡后主要抒发亡国之痛和身世之感，悲叹身世，怀念中原。孤苦伶仃，凄惨暗淡；善用白描。语言婉约，清新，忧愤，深沉，情调哀伤愁苦，风格婉约俊秀；《渔家傲》（天界云涛连晓雾）《永遇乐》（落日融金）；词集《漱玉词》。“漱玉词中，金石录里，文采有后主遗风。”","dynasty":"宋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp191","item":"苏轼（1037—1101）：字子瞻，号东坡居士，北宋文学家、书画家，\"唐宋八大家\"之一，豪放词派开创者，豪放词成就最高。诗、词、文、书、画俱精；词赋继承欧阳修传统，有冷静、旷达的人生态度；因\"乌台诗案\"被贬。代表作《念奴娇·赤壁怀古》（大江东去）、《水调歌头·明月几时有》、《江城子·密州出猎》、《赤壁赋》、《题西林壁》。书法列宋四家\"苏轼、黄庭坚、米芾、蔡襄\"，绘画擅松、木、竹、石，被誉为\"千古第一文人\"。苏轼：出为名相，处为名贤。乐在人后，忧在人先。","dynasty":"宋","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp192","item":"辛弃疾（1140—1207）：字幼安，号稼轩，南宋词人，豪放词派代表，与苏轼并称\"苏辛\"。代表作《破阵子·为陈同甫赋壮词以寄之》《永遇乐·京口北固亭怀古》《青玉案·元夕》；字幼安，号稼轩，南宋豪放派词人，与苏轼并称“苏辛”，代表作《永遇乐·京口北固亭怀古》《破阵子》；字幼安，号稼轩，南宋豪放派词人，人称“词中之龙”，弃武从文；与苏轼合称“苏辛”，与李清照并称“济南二安”；有强烈的爱国主义思想和战斗精神，以豪放为主，以文为词，壮志难酬，报国无门；《稼轩词》；《水龙吟·登建康赏心亭》；“休说鲈鱼堪脍，尽西风，季鹰归未？”：西晋张翰，字季鹰，见《晋书·张翰传》。另外，《世说新语·识鉴篇》；“求田问舍，怕应羞见，刘郎才气。”：典出《三国志·魏书·陈登传》许汜、刘备；字幼安，号稼轩；有“词中之龙”之称；与苏轼合称“苏辛”；与李清照并称“济南二安”","dynasty":"宋","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp194","item":"柳永（约987—约1053）：字耆卿，北宋词人，婉约派代表，大量创作慢词，代表作《雨霖铃》《望海潮》《八声甘州》；字耆卿，世称柳七、柳屯田，北宋婉约派词人，大量创制慢词，代表作《雨霖铃》《望海潮》；原名：柳三变，世称“柳屯田”，屯田员外郎；婉约词派开创者；北宋第一个专力写词的诗人；《定风波》《雨霖铃》《八声甘州》（对潇潇暮雨）（抒发了词人羁旅行役之苦）；初名三变，字景庄，后改名永，字耆卿；《乐章集》；比较多地描写了妓女的生活和思想","dynasty":"宋","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp195","item":"欧阳修（1007—1072）：字永叔，号醉翁、六一居士，北宋文学家、史学家，\"唐宋八大家\"之一，北宋诗文革新运动领袖。代表作《醉翁亭记》《秋声赋》《五代史伶官传序》；字永叔，号醉翁，晚号六一居士，北宋诗文革新运动领袖，“唐宋八大家”之一，代表作《醉翁亭记》《秋声赋》；字永叔，号醉翁、六一居士；主张文章应“明道”、致用；《欧阳文忠集》；《六一诗话》；开创了“诗话”新体材；字永叔，号醉翁，晚年又号“六一居士\"；北宋诗文革新运动的领袖，唐宋八大家之一；欧阳修：公少有大节，于富贵、贫贱、毁誉、欢戚，不一动其心，而慨然有志于天下”公为将，务持重，不急近功小利。","dynasty":"宋","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp196","item":"王安石（1021—1086）：字介甫，号半山，北宋政治家、文学家，\"唐宋八大家\"之一，主持熙宁变法。代表作《答司马谏议书》《游褒禅山记》《伤仲永》《泊船瓜洲》；字介甫，号半山，封荆国公，世称王荆公，北宋政治家、文学家，“唐宋八大家”之一，代表作《游褒禅山记》《泊船瓜洲》；字介甫，号半山，唐宋八大家之一，“王安石变法”；北宋诗文革新运动推动者；主张“文章有补于世，以适用为本”；被列宁称为“中国十一世纪的改革家”；其散文雄健峭拔，诗歌劲清新；《伤仲永》《元日》《泊船瓜洲》《临川先生文集》；字介甫，号半山，小字獾郎，封荆国公，世人又称王荆公；王安石：呜呼我公，一世之师。由初迄终，名节无疵......","dynasty":"宋","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp197","item":"苏洵（1009—1066）、苏辙（1039—1112）：与苏轼合称\"三苏\"，均列\"唐宋八大家\"。苏洵《六国论》为政论名篇。","dynasty":"宋","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp198","item":"曾巩（1019—1083）：字子固，北宋文学家，\"唐宋八大家\"之一，文风质朴雅正；字子固，北宋散文家，“唐宋八大家”之一，文风醇正，有《元丰类稿》。","dynasty":"宋","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp199","item":"陆游（1125—1210）：字务观，号放翁，南宋爱国诗人，存诗九千余首。代表作《示儿》《游山西村》《书愤》《十一月四日风雨大作》；字务观，号放翁，南宋爱国诗人，“中兴四大诗人”之一，存诗近万首，代表作《示儿》《书愤》《钗头凤》；字务观，号放翁，中兴四大诗人之一；诗歌风格：豪迈奔放为主，雄浑豪健；中国古代最高产的诗人（诗成就为最）；内容：抗敌复国，人民疾苦，隐逸情趣，爱情诗；《剑南诗稿》《放翁词》；《关山月》（乐府旧题）；以守边将士的身份和口吻，揭露和谴责南宋统治阶级对金人屈膝投降的政策；沦陷区人民盼望恢复而不得的悲痛心情（中原干戈古亦闻等四句）","dynasty":"宋","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp200","item":"文天祥（1236—1283）：南宋末爱国诗人，兵败被俘不屈而死，作《过零丁洋》《正气歌》，\"人生自古谁无死，留取丹心照汗青\"传诵千古；字宋瑞，又字履善，号文山，南宋爱国名臣，代表作《过零丁洋》《正气歌》。","dynasty":"宋","cat":"作家作品","source":"考纲文学常识扩展"},{"id":"lp201","item":"宋词：宋代代表性文体，句子长短不齐，有词牌、词题。按风格分豪放派（苏轼、辛弃疾）与婉约派（柳永、李清照）。","dynasty":"宋","cat":"文体知识","source":"考纲文学常识扩展"},{"id":"lp203","item":"\"但愿人长久，千里共婵娟。\"——出自苏轼《水调歌头·明月几时有》，寄托对亲人的美好祝愿。","dynasty":"宋","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp204","item":"\"大江东去，浪淘尽，千古风流人物。\"——出自苏轼《念奴娇·赤壁怀古》，豪放词代表句。","dynasty":"宋","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp205","item":"\"寻寻觅觅，冷冷清清，凄凄惨惨戚戚。\"——出自李清照《声声慢》，连用叠字，写尽凄凉。","dynasty":"宋","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp206","item":"\"先天下之忧而忧，后天下之乐而乐。\"——出自范仲淹《岳阳楼记》，表现政治抱负。","dynasty":"宋","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp207","item":"\"醉翁之意不在酒，在乎山水之间也。\"——出自欧阳修《醉翁亭记》。","dynasty":"宋","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp208","item":"\"山重水复疑无路，柳暗花明又一村。\"——出自陆游《游山西村》，喻困境中见转机。","dynasty":"宋","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"mj002","item":"“先天下之忧而忧，后天下之乐而乐。”——范仲淹《岳阳楼记》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj004","item":"“大江东去，浪淘尽，千古风流人物。”——苏轼《念奴娇·赤壁怀古》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj056","item":"“无可奈何花落去，似曾相识燕归来。”——晏殊《浣溪沙》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj057","item":"“衣带渐宽终不悔，为伊消得人憔悴。”——柳永《蝶恋花》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj058","item":"“多情自古伤离别，更那堪冷落清秋节。”——柳永《雨霖铃》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj059","item":"“醉翁之意不在酒，在乎山水之间也。”——欧阳修《醉翁亭记》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj060","item":"“忧劳可以兴国，逸豫可以亡身。”——欧阳修《五代史伶官传序》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj061","item":"“山高月小，水落石出。”——苏轼《后赤壁赋》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj062","item":"“但愿人长久，千里共婵娟。”——苏轼《水调歌头·明月几时有》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj063","item":"“不识庐山真面目，只缘身在此山中。”——苏轼《题西林壁》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj064","item":"“寄蜉蝣于天地，渺沧海之一粟。”——苏轼《赤壁赋》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj065","item":"“六国破灭，非兵不利，战不善，弊在赂秦。”——苏洵《六国论》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj066","item":"“不畏浮云遮望眼，自缘身在最高层。”——王安石《登飞来峰》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj067","item":"“春风又绿江南岸，明月何时照我还。”——王安石《泊船瓜洲》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj068","item":"“出淤泥而不染，濯清涟而不妖。”——周敦颐《爱莲说》。","dynasty":"北宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj014","item":"苏洵：字明允，号老泉，北宋散文家，与其子苏轼、苏辙合称“三苏”，俱列唐宋八大家。代表作《六国论》。","dynasty":"北宋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj016","item":"苏辙：字子由，晚号颍滨遗老，北宋散文家，“三苏”之一，“唐宋八大家”之一。代表作《黄州快哉亭记》；苏辙：范文正公笃于忠亮，虽喜功名，而不为朋党。","dynasty":"北宋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj050","item":"范仲淹：字希文，谥号文正，北宋政治家、文学家，代表作《岳阳楼记》；世称范文正公；先天下之忧而忧，后天下之乐而乐；范仲淹《岳阳楼记》","dynasty":"北宋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj051","item":"晏殊：字同叔，北宋词人，代表作《浣溪沙》，有《珠玉词》；字同叔，北宋倚声家初祖；有《珠玉词》，词多佳会宴游之余的消遣之作，有浓厚的雍容华贵的气派；题材多写伤春时，在寂寞中流连光景之情怀；把宋词语言推向文人化、典雅化；范仲淹、欧阳修均出其门下；主要作品有《珠玉词》","dynasty":"北宋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj055","item":"周敦颐：字茂叔，世称濂溪先生，北宋理学家，代表作《爱莲说》。","dynasty":"北宋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj056","item":"司马光：字君实，北宋史学家、政治家，主编我国最大的一部编年体史书《资治通鉴》；主要编撰《资治通鉴》（编年体通史巨著）；“鉴于往事，有资于治道。”；司马光：“由是四方从学者辐凑。其后宋人以文学有声名于场屋朝廷者，多其所教也。”","dynasty":"北宋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp031","item":"中兴四大诗人（南宋四大家）：南宋前期尤袤、杨万里、范成大、陆游四位诗人的并称。","dynasty":"南宋","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp032","item":"诚斋体：南宋杨万里独创的活泼自然、幽默风趣的诗风。","dynasty":"南宋","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp033","item":"四灵诗派（永嘉四灵）：南宋永嘉地区徐照、徐玑、翁卷、赵师秀四位诗人，字中皆带“灵”字，标榜晚唐。","dynasty":"南宋","cat":"文学流派","source":"https://m.baike.com/"},{"id":"mj071","item":"“莫等闲，白了少年头，空悲切。”——岳飞《满江红》。","dynasty":"南宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj072","item":"“王师北定中原日，家祭无忘告乃翁。”——陆游《示儿》。","dynasty":"南宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj073","item":"“山重水复疑无路，柳暗花明又一村。”——陆游《游山西村》。","dynasty":"南宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj074","item":"“众里寻他千百度，蓦然回首，那人却在灯火阑珊处。”——辛弃疾《青玉案·元夕》。","dynasty":"南宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj075","item":"“千古兴亡多少事，悠悠，不尽长江滚滚流。”——辛弃疾《南乡子·登京口北固亭有怀》。","dynasty":"南宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj076","item":"“人生自古谁无死，留取丹心照汗青。”——文天祥《过零丁洋》。","dynasty":"南宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj083","item":"“纸上得来终觉浅，绝知此事要躬行。”——陆游《冬夜读书示子聿》。","dynasty":"南宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj084","item":"“问渠那得清如许？为有源头活水来。”——朱熹《观书有感》。","dynasty":"南宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj085","item":"“青山遮不住，毕竟东流去。”——辛弃疾《菩萨蛮·书江西造口壁》。","dynasty":"南宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj086","item":"“接天莲叶无穷碧，映日荷花别样红。”——杨万里《晓出净慈寺送林子方》。","dynasty":"南宋","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj060","item":"范成大：字致能，号石湖居士，“中兴四大诗人”之一，代表作《四时田园杂兴》六十首；字至能，号石湖居士；风格平易浅显、清新妩媚；诗题材广泛，以反映农村社会生活内容的作品成就最高","dynasty":"南宋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj061","item":"杨万里：字廷秀，号诚斋，“中兴四大诗人”之一，诗风活泼自然，称“诚斋体”，代表作《小池》《晓出净慈寺送林子方》；字廷秀，号诚斋，自号诚斋野客；杨万里的诗自成一家，独具风格，形成对后世影响颇大的“诚斋体”；词特征：清新自然；代表作有《插秧歌》《竹枝词》《小池》等","dynasty":"南宋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj062","item":"朱熹：字元晦，号晦庵，南宋理学家，集理学之大成，编定《四书章句集注》；朱熹：范文正杰出之才。[300]本朝道学之盛，亦有其渐，自范文正以来已有好议论。[192]天地间气第一流人物。[299]范文正公作成忠义之风。[299]宋朝忠义之风却是自范文正作成起来也。","dynasty":"南宋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj104","item":"尤袤：字延之，号遂初居士，“中兴四大诗人”之一，存诗较少。","dynasty":"南宋","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp034","item":"江湖诗派：南宋后期以陈起《江湖集》得名的诗人群体，多为江湖布衣诗人。","dynasty":"南宋后期","cat":"文学流派","source":"https://m.baike.com/"},{"id":"wt034","item":"诸宫调：宋金时期的大型说唱文学，董解元《西厢记诸宫调》为代表。","dynasty":"宋金","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt032","item":"散曲：金元时期兴盛的配合北乐歌唱的新诗体，分小令和套数，如马致远《天净沙·秋思》；被誉为“秋思之祖”；点睛之笔：“断肠人在天涯。”；全文借景抒情、寓情于景。","dynasty":"金元","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"lp035","item":"元曲（杂剧与散曲）：元代兴盛的北曲戏曲与散曲合称，分杂剧（戏曲）与散曲（清唱）；元代文学代表，分杂剧（戏曲，有唱念做打、生旦净末丑）与散曲（清唱，分小令、套数）；杂剧；散曲（多写叹世归隐，男女恋情，流连风景和诗酒，风流，评击现实之作）；套数；小令","dynasty":"元","cat":"文学流派","source":"https://m.baike.com/"},{"id":"wt033","item":"杂剧：元代成熟的戏曲形式，有唱、科、白，分折，如关汉卿《窦娥冤》；取材昭君出塞，抒写家国衰败之痛；人物：王昭君、单于、汉元帝、毛延寿","dynasty":"元","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"mj077","item":"“兴，百姓苦；亡，百姓苦。”——张养浩《山坡羊·潼关怀古》。","dynasty":"元","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj078","item":"“枯藤老树昏鸦，小桥流水人家，古道西风瘦马。夕阳西下，断肠人在天涯。”——马致远《天净沙·秋思》。","dynasty":"元","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj064","item":"关汉卿：号已斋叟，元代杂剧奠基人，“元曲四大家”之首，代表作《窦娥冤》《救风尘》《单刀会》；元代最善于以抗争激情感染大众的戏剧家；《窦娥冤》（悲剧）；元杂剧悲剧典范，别名《感天动地窦娥冤》；核心问题：揭露社会不公正；血溅白绫、六月降雪、大旱三年；人物：窦娥、蔡婆、张驴儿父子；《拜月亭》（喜剧）《望江亭》《单刀会》；小关汉卿：高文秀；四大家之首；杂剧之祖；曲尽人情，字字本色；《窦娥冤》；元代杂剧奠基人，\"元曲四大家\"之首，代表作《窦娥冤》（我国古代最著名的悲剧）《救风尘》《望江亭》。","dynasty":"元","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj065","item":"王实甫：名德信，元代杂剧作家，代表作《西厢记》（《崔莺莺待月西厢记》），曲词清丽；元代杂剧家，代表作《西厢记》，写张生与崔莺莺的爱情故事，曲词优美，\"愿天下有情的都成了眷属\"；《西厢记》；人物：崔莺莺、张生；崔莺莺：勇于背叛封建礼教、追求自由爱情；张生：蔑视封建礼教、忠于爱情；红娘：婢女，地位卑下而心地高洁，富有正义感，集中表现了劳动人民的许多优秀品质；讴歌青年男女追求婚姻自主的斗争，表现“原普天下有情人终成眷属”的理想；被誉为“花间美人”；《西厢记》；故事来源；元稹的《莺莺传》；由原来的“才子配佳人”变成了“愿天下有情的都成了眷属”；崔莺莺；红娘；张生","dynasty":"元","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj066","item":"马致远：字千里，号东篱，“元曲四大家”之一，被誉为“曲状元”，代表作《天净沙·秋思》《汉宫秋》；秋思之祖；有“曲状元”之称；《汉宫秋》；元代杂剧家、散曲家，\"元曲四大家\"之一，散曲《天净沙·秋思》被誉为\"秋思之祖\"；号东篱，“曲状元”之称","dynasty":"元","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj067","item":"白朴：字仁甫，“元曲四大家”之一，代表作《梧桐雨》《墙头马上》；《墙头马上》；人物：裴少俊、李千金；《梧桐雨》；《墙头马上》","dynasty":"元","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj068","item":"郑光祖：字德辉，“元曲四大家”之一，代表作《倩女离魂》；《倩女离魂》；人物：张倩女、王文举","dynasty":"元","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj105","item":"张养浩：字希孟，号云庄，元代散曲家，代表作《山坡羊·潼关怀古》；散曲多写寄情林泉之乐，也不乏关怀民生；《山坡羊·潼关怀古》","dynasty":"元","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp213","item":"元杂剧四大家：关汉卿、马致远、郑光祖、白朴。元杂剧四大悲剧：《窦娥冤》《汉宫秋》《梧桐雨》《赵氏孤儿》。","dynasty":"元","cat":"文体知识","source":"考纲文学常识扩展"},{"id":"lp214","item":"\"枯藤老树昏鸦，小桥流水人家，古道西风瘦马。夕阳西下，断肠人在天涯。\"——马致远《天净沙·秋思》。","dynasty":"元","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"zj069","item":"施耐庵：元末明初小说家，著有我国第一部以农民起义为题材的长篇章回小说《水浒传》；《水浒传》；中国历史上最早用白话文写成的章回体小说之一；农民起义为题材的长篇小说；人物（武松，鲁智深，宋江，公孙胜，林冲，李逵、郭盛等）","dynasty":"元末明初","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj070","item":"罗贯中：名本，字贯中，元末明初小说家，著有我国第一部长篇章回体历史演义小说《三国演义》；《三国演义》；描写了从东汉末年到西晋初年之间近百年的历史风云；中国文学史上第一部章回小说，是历史演义小说的开山之作，也是第一部文人长篇小说；明清时期甚至有“第一才子书”之称；元末明初小说家，著《三国演义》，我国第一部长篇章回体历史演义小说。","dynasty":"元末明初","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp037","item":"前七子：明代弘治、正德年间以李梦阳、何景明为首的复古文学流派，主张“文必秦汉，诗必盛唐”；也叫弘正七子；以李梦阳、何景明为首的一个复古主义文学流派；其成员有徐祯卿、边贡、康海、王九思、王廷相","dynasty":"明","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp038","item":"后七子：明代嘉靖年间以李攀龙、王世贞为首的复古流派，继续主张文必秦汉、诗必盛唐；嘉靖七子；李攀龙、王世贞为首继前七子之后重新倡导复古的文学流派；成员有谢榛、吴国伦、宗臣、徐中行、梁有誉；《报刘一丈书》","dynasty":"明","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp039","item":"唐宋派：明代中叶反对前后七子复古、推崇唐宋散文的流派，代表归有光、茅坤、王慎中、唐顺之；嘉靖年间以王慎中、唐顺之、茅坤、归有光为代表的一个散文复古流派；推崇唐宋文风，强调自然流畅、直抒胸臆、反对艰深为文、模拟剽窃","dynasty":"明","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp040","item":"公安派：明代后期以袁宗道、袁宏道、袁中道“三袁”为代表的流派，主张“独抒性灵，不拘格套”；受李贽影响而出现的一个反复古的文学流派；袁宗道、袁宏道、袁中道；主张“独抒性灵，不拘格套”","dynasty":"明","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp041","item":"竟陵派：明代后期以钟惺、谭元春为代表的流派，湖广竟陵人，追求“深幽孤峭”；钟惺、谭元春；反复古、重性灵上与公安派一致；但不满公安派鄙俚、轻率、浅露的流弊","dynasty":"明","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp042","item":"临川派（玉茗堂派）：明代以汤显祖（临川人，斋名玉茗堂）为代表的戏曲流派，重文采才情，代表作《牡丹亭》。","dynasty":"明","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp043","item":"吴江派：明代以沈璟为代表的戏曲流派，讲究音律格律。","dynasty":"明","cat":"文学流派","source":"https://m.baike.com/"},{"id":"wt018","item":"序：送别赠言的文体称“赠序”，如宋濂《送东阳马生序》；也指著作前的引言（书序）；序：散文文体，也做“绪”“叙”，赠序（《送李愿归盘古序》）书序（《张中丞传后叙》）","dynasty":"明","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt036","item":"拟话本：明代文人模拟话本形式创作的白话短篇小说，如“三言”“二拍”。","dynasty":"明","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt040","item":"章回小说：分回标目、分章叙事的长篇白话小说，成熟于明清，如《三国演义》《红楼梦》；我国古典长篇小说的主要形式，分回标目、分章叙事，由宋元话本发展而来，成熟于明清。","dynasty":"明","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"wt041","item":"历史演义：以历史事迹为题材、敷演成文的长篇章回小说，如《三国演义》。","dynasty":"明","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"mj087","item":"“粉身碎骨浑不怕，要留清白在人间。”——于谦《石灰吟》。","dynasty":"明","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj073","item":"归有光：字熙甫，号震川，明代散文家，唐宋派代表，代表作《项脊轩志》《先妣事略》；散文。《项脊轩志》；号震川；《震川集》；《项脊轩志》；归有光散文被誉为“明文第一”；黄宗羲《明文综序》；今之欧阳修","dynasty":"明","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj074","item":"袁宏道：字中郎，号石公，明代公安派代表，与兄宗道、弟中道并称“三袁”，主张“独抒性灵，不拘格套”。","dynasty":"明","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj075","item":"汤显祖：字义仍，号若士、临川，明代戏曲家，代表作《牡丹亭》，另有《紫钗记》《邯郸记》《南柯记》，合称“临川四梦”；临川四梦（戏曲）：《牡丹亭》（柳梦梅、杜丽娘）《紫钗记》《邯郸记》《南柯记》；明代戏曲家，临川派代表，代表作\"临川四梦\"（《牡丹亭》《紫钗记》《南柯记》《邯郸记》），《牡丹亭》最著。","dynasty":"明","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj076","item":"吴承恩：字汝忠，号射阳山人，明代小说家，著有浪漫主义长篇神魔小说《西游记》；《西游记》；中国古代第一部浪漫主义章回体长篇神魔小说；明代小说家，著《西游记》，我国古代最杰出的浪漫主义神魔小说。","dynasty":"明","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj077","item":"冯梦龙：字犹龙，明代文学家，编订“三言”（《喻世明言》《警世通言》《醒世恒言》）；明代文学家，编\"三言\"（《喻世明言》《警世通言》《醒世恒言》），与凌濛初\"二拍\"合称\"三言二拍\"。","dynasty":"明","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj078","item":"凌濛初：字玄房，明代小说家，编著“二拍”（《初刻拍案惊奇》《二刻拍案惊奇》）。","dynasty":"明","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj079","item":"张溥：字天如，明末复社领袖，代表作《五人墓碑记》。","dynasty":"明","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp220","item":"明代四大奇书：《三国演义》《水浒传》《西游记》《金瓶梅》，分别代表历史演义、英雄传奇、神魔、世情四类长篇小说；明代四大奇书：《金瓶梅》《三国演义》《水浒传》《西游记》","dynasty":"明","cat":"文体知识","source":"考纲文学常识扩展"},{"id":"lp221","item":"\"滚滚长江东逝水，浪花淘尽英雄。\"——出自《三国演义》开篇词（杨慎《临江仙》）。","dynasty":"明","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"zj071","item":"宋濂：字景濂，号潜溪，明初文学家，被誉为“开国文臣之首”，代表作《送东阳马生序》；散文；宋濂主张“以道为文”，作品多道学气；《送东阳马生序》","dynasty":"明初","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj072","item":"刘基：字伯温，明初政治家、文学家，代表作《卖柑者言》；《卖柑者言》；“金玉其外，败絮其中”","dynasty":"明初","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj106","item":"高启：字季迪，明代诗人，“吴中四杰”之首，诗风豪迈。","dynasty":"明初","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp044","item":"桐城派：清代最大的散文流派，因方苞、刘大櫆、姚鼐三位代表均为安徽桐城人而得名，三人并称“桐城三祖”，方苞倡“义法”，姚鼐主张义理、考证、辞章合一。","dynasty":"清","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp045","item":"阳湖派：清代恽敬、张惠言等开创的散文流派，因阳湖（今常州）人而得名，桐城派支流。","dynasty":"清","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp046","item":"常州词派：清代嘉庆年间以张惠言、周济为代表的词派，主张词要“意内言外”“比兴寄托”。","dynasty":"清","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp047","item":"浙西词派：清代以朱彝尊为代表的词派，推崇南宋姜夔、张炎，追求醇雅。","dynasty":"清","cat":"文学流派","source":"https://m.baike.com/"},{"id":"mj079","item":"“落红不是无情物，化作春泥更护花。”——龚自珍《己亥杂诗》。","dynasty":"清","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"mj088","item":"“我劝天公重抖擞，不拘一格降人才。”——龚自珍《己亥杂诗》。","dynasty":"清","cat":"名句名篇","source":"https://www.gushiwen.cn/"},{"id":"zj017","item":"汪琬：字苕文，号钝庵、尧峰，清初散文家，与侯方域、魏禧并称“清初三大散文家”，文风简洁。","dynasty":"清","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj018","item":"蒲松龄：字留仙，一字剑臣，号柳泉居士，世称聊斋先生。著有文言短篇小说集《聊斋志异》，以花妖狐魅寄托孤愤；世称“聊斋先生”，中国短篇小说之王，我国文言小说的集大成者；《聊斋志异》（中国清初文言短篇小说集）；郭沫若评：“写鬼写妖高人一等，刺贪刺虐入骨三分。”；字留仙，号柳泉居士，清代小说家，著《聊斋志异》，我国古代最杰出的文言短篇小说集，借花妖狐魅讽喻现实；字“留仙”“剑臣”号“柳泉居士”","dynasty":"清","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj080","item":"纳兰性德：字容若，号楞伽山人，清代满族词人，风格哀婉，有《饮水词》；字容若，号饮水，楞伽山人，与朱彝尊、陈维崧并称“清词三大家”","dynasty":"清","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj081","item":"方苞：字灵皋，号望溪，清代桐城派创始人，主张“义法”说，代表作《狱中杂记》《左忠毅公逸事》。","dynasty":"清","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj082","item":"刘大櫆：字才甫，号海峰，清代桐城派代表，“桐城三祖”之一，提出“神气”说。","dynasty":"清","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj083","item":"姚鼐：字姬传，号惜抱先生，清代桐城派集大成者，“桐城三祖”之一，主张“义理、考证、辞章”三者合一，代表作《登泰山记》；清代散文家，桐城派集大成者，主张义理、考证、辞章三者合一，编《古文辞类纂》。","dynasty":"清","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj084","item":"吴敬梓：字敏轩，号粒民，清代小说家，著有长篇讽刺小说《儒林外史》；《儒林外史》（中国第一部长篇讽刺小说）；代表着中国古代讽刺小说的高峰，它开创了以小说直接评价现实生活的范例；清代小说家，著《儒林外史》，我国古代最杰出的讽刺小说，以范进中举等情节批判科举制度。","dynasty":"清","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj085","item":"曹雪芹：名霑，字梦阮，号雪芹，清代小说家，著有我国古代最伟大的现实主义长篇小说《红楼梦》（前八十回）；现实主义作品；中国古代章回体长篇小说，中国古典四大名著之一；中国封建社会的百科全书，传统文化的集大成者；以贾、史、王、薛四大家族的兴衰为背景，以富贵公子贾宝玉为视角，以贾宝玉与林黛玉、薛宝钗的爱情婚姻悲剧为主线；《宝玉挨打》；挨打的导火索——宝玉与戏剧名角气琪官交往；挨打的真正原因——荒疏学业，鄙视和背离家人为他安排的仕途道路；“葳葳蕤蕤”指疲惫不堪、萎靡不振；祖孙三代任江宁织造；雍正即位曹家失势；清代小说家，著《红楼梦》（前八十回），我国古典小说的巅峰之作，以贾宝玉、林黛玉爱情悲剧为线索，展现封建家族的衰亡；名霑，字梦阮，号雪芹、又号芹圃","dynasty":"清","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj086","item":"袁枚：字子才，号简斋，晚号随园老人，清代诗人，主张“性灵说”，有《随园诗话》。","dynasty":"清","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj087","item":"纪昀：字晓岚，清代学者，主编《四库全书》，著有笔记小说《阅微草堂笔记》。","dynasty":"清","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj088","item":"龚自珍：字璱人，号定盦，清代思想家、文学家，近代启蒙思想先驱，代表作《己亥杂诗》《病梅馆记》；《龚自珍全集》《己亥全诗》主张“更法”、“改图”揭露清统治者的腐朽；被柳亚子誉为“三百年来第一主流”；“我劝天公重抖擞，不拘一格降人才。”；乙亥杂诗；清代思想家、文学家，近代启蒙思想先驱，代表作《己亥杂诗》，\"我劝天公重抖擞，不拘一格降人才\"。","dynasty":"清","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj107","item":"洪昇：号稗畦，清代戏曲家，代表作《长生殿》，写唐明皇与杨贵妃故事。","dynasty":"清","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj108","item":"孔尚任：字聘之，号东塘，清代戏曲家，代表作《桃花扇》，与洪昇并称“南洪北孔”。","dynasty":"清","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp227","item":"晚清四大谴责小说：李宝嘉《官场现形记》、吴沃尧《二十年目睹之怪现状》、刘鹗《老残游记》、曾朴《孽海花》；李宝嘉别名：李伯元；《官场现形记》（谴责小说）首开近代小说批判现实的风气；吴沃尧别名：吴趼人；《二十年之目睹怪现状》（带有自传色彩的长篇小说）；刘鹗；《老残游记》（带有自传性质的未竟作品）；曾朴；《孽海花》（既有谴责小说、又具有历史小说，还具有政治小说特点的长篇小说）；李伯元的《官场现形记》；吴沃尧（吴趼人）的《二十年目睹之怪现状》；刘鹗的《老残游记》；曾朴的《孽海花》李宝嘉《官场现形记》、吴沃尧《二十年目睹之怪现状》、刘鹗《老残游记》、曾朴《孽海花》；李宝嘉（李伯元）的《官场现形记》；吴沃尧（吴趼人）的《二十年目睹之怪现状》；刘鹗的《老残游记》；曾朴的《孽海花》","dynasty":"清","cat":"文体知识","source":"考纲文学常识扩展"},{"id":"lp228","item":"\"落红不是无情物，化作春泥更护花。\"——出自龚自珍《己亥杂诗》，喻无私奉献。","dynasty":"清","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp229","item":"\"满纸荒唐言，一把辛酸泪。都云作者痴，谁解其中味？\"——出自《红楼梦》开篇诗。","dynasty":"清","cat":"名句名篇","source":"考纲文学常识扩展"},{"id":"lp048","item":"同光体：清末同治、光绪年间以陈三立、郑孝胥为代表的宋诗派诗流。","dynasty":"清末","cat":"文学流派","source":"https://m.baike.com/"},{"id":"wt042","item":"谴责小说：清末以暴露社会黑暗为宗旨的小说，如《官场现形记》《二十年目睹之怪现状》。","dynasty":"清末","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"zj109","item":"刘鹗：字铁云，小说家，著有《老残游记》，为晚清四大谴责小说之一。","dynasty":"清末","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj110","item":"李宝嘉（李伯元）：小说家，著有《官场现形记》，为晚清四大谴责小说之一。","dynasty":"清末","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj111","item":"吴沃尧（吴趼人）：小说家，著有《二十年目睹之怪现状》，为晚清四大谴责小说之一。","dynasty":"清末","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj112","item":"曾朴：小说家，著有《孽海花》，为晚清四大谴责小说之一。","dynasty":"清末","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"lp053","item":"鸳鸯蝴蝶派（礼拜六派）：清末民初以言情、消闲小说为主的通俗文学流派，代表作《玉梨魂》；张恨水","dynasty":"清末民初","cat":"文学流派","source":"https://m.baike.com/"},{"id":"wt043","item":"报告文学：介于新闻报道与文学之间、真人真事兼顾文学性的散文体裁。","dynasty":"现代","cat":"文体知识","source":"https://m.baike.com/wiki/%E5%89%8D%E5%9B%9B%E5%8F%B2/278415"},{"id":"lp230","item":"古代神话：《山海经》（先秦）；成书年代：战国时期至汉代初期；是收录中国古代神话最多的著作；内容：精卫填海、夸父追日；《淮南子》（西汉，刘安）；四大神话：女娲补天、后羿射日、嫦娥奔月、共工触山","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp232","item":"《伐檀》《硕鼠》《采薇》","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp233","item":"收入自西周初期至春秋中叶约500年间的诗歌305篇","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp234","item":"最初称《诗》《诗三百》","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp235","item":"孔子编订，收录原则“哀而不伤”","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp236","item":"句式上以四言为主","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp237","item":"按内容分：风（音乐曲调，国风指各地方的乐调）；雅（大部分是贵族的宫廷，分为大雅和小雅）；颂（周天子和诸侯用以祭祀宗庙的舞乐，分《周颂》《鲁颂》《商颂》）","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp238","item":"按表现手法分：（开启了我国古代诗歌创作的基本手法）；赋（铺陈直叙）；比（“以彼物比彼物”）；兴（铺垫、开头）","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp239","item":"拓展：四书：《大学》《中庸》《论语》《孟子》；五经：（诗书礼易春秋）《诗经》《尚书》《礼记》《易经》《春秋》；“六艺”：礼乐射御书数","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp240","item":"《楚辞》（我国第二部诗歌总集（浪漫主义创作））：辑录者：西汉末年刘向；收录：屈原、宋玉的作品，及汉代人模仿这种诗体的作品；我国第一部浪漫主义诗歌总集；开创了文人独立创作的新时期；《楚辞》（浪漫主义）+《诗经》（现实主义）=中国诗歌史上的两大源头；《诗经·国风》+《楚辞·离骚》=“风骚”","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp241","item":"名丘、字仲尼——至圣","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp242","item":"春秋末期：思想核心：仁和礼、因材施教","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp248","item":"散文代表篇目：《秋水》（对话方式的论说文，采用寓言形式）；河：黄河江：长江；《逍遥游》；《齐物论》；《养生主》","dynasty":"战国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp250","item":"战国秦朝：李斯；师从荀子；小篆字体的创造者；谏逐客书；选自《史记·李斯列传》，是李斯写给秦王的奏章，也是一篇论说文，对比论证法；中心观点：“臣闻吏议逐客，窃以为过矣。”","dynasty":"战国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp251","item":"伊索：《伊索寓言》，反对暴政，反抗奴隶主","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp252","item":"苏格拉底、柏拉图《理想国》、亚里士多德","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp253","item":"两汉：汉赋四大家:司马相如、扬雄、班固、张衡","dynasty":"西汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp255","item":"枚乘（赋开拓者）：《七发》——汉大赋的正式形成","dynasty":"西汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp257","item":"扬雄（汉赋四大家之一）：四大赋——《甘泉赋》《河东赋》《羽猎赋》《长扬赋》","dynasty":"西汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp258","item":"字子长，“史圣”","dynasty":"西汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp259","item":"司马迁首创以人物为中心的纪传体史学著作","dynasty":"西汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp260","item":"“前四史”：《史记》纪传体通史（司马迁）；《汉书》中国第一部纪传体断代史（班固）；《后汉书》纪传体史书，人物传记（范晔、司马彪）；《三国志》纪传体史书，国别体（陈寿）；“前四史”：《史记》《汉书》《后汉书》《三国志》","dynasty":"西汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp261","item":"《李将军列传》选自《史记》：对李广悲剧英雄人物的刻画，表达了作者对一代名将的衷心倾慕，揭露和批判了汉朝统治者妒贤嫉能、任人唯贤以及不合理的军工制度，同时也寄寓了作者对自己身世的慨叹；四场战役：上郡遭遇战、雁门出击战、右北平之战、随卫青出击战；擅长运用对比手法","dynasty":"西汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp263","item":"张衡（汉赋四大家之一）：《思玄赋》《二京赋》（抒情小赋）《南都赋》《归田赋》；《两京赋》","dynasty":"东汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp264","item":"西汉王朝的音乐官署","dynasty":"西汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp265","item":"汉乐府：西汉时多杂言，东汉时则为五言；罗敷拒绝使君；开创诗歌现实主义新风，开拓叙事诗发展成熟的新阶段；乐府诗主要收录在北宋·郭茂倩的《乐府诗集》中；《孔雀东南飞》与《木兰诗》合称“乐府双璧”；汉代《孔雀东南飞》，北朝《木兰诗》和唐代韦庄《秦妇吟》并称“乐府三绝”；本意为官职，后延伸成一种诗体","dynasty":"西汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp266","item":"《孔雀东南飞》：古今第一首长诗，我国古代最长叙事诗；最早见于南朝徐陵所编的《玉台新咏》；我国古代最长的叙事诗，爱情悲剧；人物：刘兰芝、焦仲卿（自挂东南枝）","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp269","item":"被鲁迅誉为“改造文章的祖师”","dynasty":"三国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp270","item":"《蒿里行》《龟虽寿》《观沧海》","dynasty":"三国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp272","item":"司马彪：与范晔《后汉书》（纪传体史书，人物传记）","dynasty":"西晋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp273","item":"陈寿：《三国志》（纪传体史书，国别体）","dynasty":"西晋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp274","item":"我国古代第一位杰出的田园诗人","dynasty":"东晋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp275","item":"钟嵘称为“古今隐逸诗人之宗”","dynasty":"东晋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp276","item":"菊和酒是他的象征","dynasty":"东晋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp277","item":"《饮酒》（田园生活五言古诗）：“此中有真意，欲辨已忘言”选自《庄子·外物》：“言者所以在意也，得意而忘言。”；悠闲自得的田园生活中远离世俗，欣赏自然的兴致，和从中领悟人生的真正意义，“心远地自偏”的哲理；这首诗融写景、抒情、说理为一体","dynasty":"东晋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp279","item":"谢朓（小谢）：山水诗人，发展山水诗——自然秀逸","dynasty":"南北朝","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp281","item":"庾信：集南北朝文学之集大成的作家；《哀江南赋》；前期宫体诗风格华丽，后期风格苍劲","dynasty":"南北朝","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp282","item":"范晔（南朝）：司马彪《后汉书》","dynasty":"南北朝","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp283","item":"南北朝民歌：南朝：《西洲曲》数量多，语言清新自然，反映真挚纯洁的爱情生活；北朝：《敕勒歌》《木兰诗》数量少，语言质朴无华，爽直坦率，风格豪放，多反映北地风光，游牧生活、人民疾苦","dynasty":"南北朝","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp285","item":"近体诗（唐兴）唐代之后的不一定是近体诗：字数、句数、押韵、平仄对仗；律诗（八句）首联、颔联、颈联、尾联；七律；五律；绝句（四句）；七绝；五绝","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp286","item":"吴中四士：张若虚；《春江花月夜》“以孤篇压倒全唐”之誉，奠定他在唐诗史上的地位；闻一多称“诗中的诗，顶峰上的顶峰”；初唐歌行体代表作，唐诗最高代表；贺知章；张旭；包融","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp288","item":"张九龄：字子寿；《望月怀远》一句“海上生明月，天涯共此时”唱绝千古","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp289","item":"盛唐：唐代“四大边塞诗人”：高适、岑参、王昌龄、王之涣","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp290","item":"诗歌风格：豪放飘逸；诗歌风格：平淡自然，朴实无华；诗歌风格：通俗平易","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp291","item":"《蜀道难》《梦游天姥吟留别》《将进酒》","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp292","item":"《行路难》（用典、比兴）：诗歌是乐府《杂曲歌辞》的旧题，属于七言歌行体；“将登太行雪满山”一句化用鲍照的《舞鹤赋》的句子；“闲来垂钓”句使用了姜子牙（姜太公吕尚）、伊尹的典故；“长风破浪”句使用了宗悫的典故","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp295","item":"《张中丞传后序》：是为李翰《张巡传》写的一篇后记；本文语言简洁、抑扬顿挫，有似《史记》；论辩凌厉威严，有似《孟子》；有叙有议，叙议结合；张中丞原名张巡，和他一起守城战死的人的徐远。部将南霁云，见死不救的贺兰进明；徐远：宽厚谦和；张巡：才能杰出、博学、正义凛然；南霁云：嫉恶如仇、武勇过人","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp296","item":"《长恨歌》《琵琶行》《卖炭翁》","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp297","item":"《杜陵叟》：叙事诗，新乐府诗；诗的叙述角度从第三人称变为第一人称，人称转换的手法","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp298","item":"中唐：字阆仙，一作浪仙，号“诗奴”，自谓“两句三年得，一吟双泪流。”；李贺；诗鬼；诗仙李白、李商隐称为“唐代三李”，后世称李昌谷；刘禹锡；诗豪；柳宗元；字子厚，唐宋八大家之一；世称“柳河东”、“河东先生”，因官终柳州刺史，又称“柳柳州”；文人词出现，词开始自民间步入文坛。","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp299","item":"唐传奇：元稹《莺莺传》（《西厢记》之祖）；王度《古镜记》；张鷟所撰《游仙窟》；沈既济《枕中记》（黄粱美梦）；李公佐《南柯太守传》（南柯一梦）；白行简《李娃传》；蒋防《霍小玉传》元稹《莺莺传》；蒋防《霍小玉传》","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp300","item":"《虞美人》：借景抒情，融情于景，白描，比喻；“问君能有几多愁？”夸张、设问、比喻","dynasty":"五代","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp301","item":"宋代：唐宋八大家：韩愈（为首）、柳宗元、欧阳修、苏洵、苏轼、苏辙、王安石、曾巩（欧阳修最得意的学生）；宋代六大家：欧阳修、苏洵、苏轼、苏辙、王安石、曾巩；千古文章四大家：韩愈、柳宗元、欧阳修、苏轼","dynasty":"宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp302","item":"散文名篇《醉翁亭记》《秋声赋》","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp303","item":"《五代史伶官传序》：中心论点“盛衰之理，虽曰天命，岂非人事哉。”；序文，史论；“忧劳可以兴国，逸豫可以亡身”；“祸患常积于忽微，而智者多困于所溺”","dynasty":"五代","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp304","item":"《六一诗话》是我国第一部诗话","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp305","item":"秦观：字少游，一字太虚，号“淮海居士”，婉约派代表人物；与黄庭坚、晁补之、张耒合称“苏门四学士”；词的意境“最为凄婉”，“愁”，在伤怀人生命运之外，也有写男女之情的词，真挚动人；《淮海词》《浣溪沙》《鹊桥仙》“两情若是长久时，又岂在朝朝暮暮。”","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp306","item":"贺铸：字方回，自称庆湖遗老，“贺鬼头”","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp307","item":"《前赤壁赋》（文赋）：运用了传统赋体中主客问答的形式；骈散相间的语言特色","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp308","item":"诗——苏黄","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp309","item":"词——苏辛","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp310","item":"散文——唐宋八大家","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp311","item":"水利工程——苏提","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp312","item":"饮食——东坡肉","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp313","item":"黄庭坚：字鲁直，号山谷道人，江西诗派开山之祖；作品有《山谷词》《豫章黄先生文集》等；苏轼称黄庭坚的诗为“山谷体”；黄庭坚：“范文正公，当时文武第一人。”","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp314","item":"《声声慢》（李清照后期的代表作）：抒发的是国破家亡后的孤苦之感，“物是人非”的寂寞之情，国破家亡，无所依之感。","dynasty":"南宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp315","item":"姜夔：字尧章，号白石道人；慨叹国事，有一种深深的伤感与凄凉；号白石道人；继苏轼之后又一难得的艺术全才","dynasty":"南宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp316","item":"永嘉四灵：赵师秀（字灵秀）；徐玑（字灵渊）；徐照（字灵晖）；翁卷（字灵舒）","dynasty":"南宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp317","item":"元代：元四大悲剧：《窦娥冤》关汉卿、《汉宫秋》马致远、《梧桐雨》白朴、《赵氏孤儿》纪君祥；元四大爱情：《拜月亭》关汉卿、《墙头马上》白朴、《西厢记》王实甫、《倩女离魂》郑光祖","dynasty":"元","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp319","item":"散曲《东篱乐府》","dynasty":"元","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp320","item":"纪君祥：《赵氏孤儿》","dynasty":"元","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp321","item":"兰陵笑笑生：《金瓶梅》；被列为明代“四大奇书”之首，世情小说的开山之作；中国明代长篇白话世情小说，一般认为是中国第一部文人独立创作的章回体长篇小说；由书中三个女主人公潘金莲、李瓶儿、庞春梅名字中各取一字合成","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp322","item":"三言两拍：冯梦龙；《喻世明言》《警世通言》《醒世恒言》——三言（中国白话短篇小说）；《白娘子永镇雷峰塔》《杜十娘怒沉百宝箱》——《警世通言》；凌濛初；《初刻拍案惊奇》《二刻拍案惊奇》——二拍（中国古典短篇小说的代表）","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp323","item":"侯方域：《马伶传》；先写马伶打败，为后面大胜作铺垫；欲扬先抑的手法，之后采用倒叙手法；侧面描写人物","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp324","item":"明末清初四大儒：黄宗羲；王夫之；顾炎武","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp325","item":"性灵派三大家：袁枚；张问陶；赵翼","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp326","item":"桐城三祖：方苞；字灵皋，亦字凤九，晚年号望溪，亦号南山牧叟；桐城派散文的创始人；姚鼐；字姬传，师承刘大櫆；提出“义理、考据、辞章”三者互为作用，为桐城派散文之集大成者；刘大櫆","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp327","item":"朱彝尊：浙西词派开创者；朱彝尊与该词派其他主要作家李良年、李符、沈皞日、沈岸登、龚翔麟并称“浙西六家”","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp328","item":"郑燮：郑板桥，字克柔，号理庵，又号板桥，人称板桥先生；“扬州八怪”之一；一生只画兰、竹、石，其诗书画，世称“三绝”，是清代比较有代表性的文人画家。","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp329","item":"梁启超：中国近代文学史上最早高度评价和极力提倡小说创作的人“小说界革命”“诗界革命”；字卓如，号任公，别署饮冰室主人；《论毅力》；戊戌变法之后的第四年，全篇大量运用对比论证法、比喻修辞手法；“我则一日而返焉，或二三日而反焉，或五六日而反焉。”（比喻）；中国近代史上著名的政治活动家、启蒙思想家、资产阶级宣传家、教育家、史学家和⽂学家；戊戌维新运动领袖之⼀；号任公，又号饮冰室主人","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp330","item":"康有为","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp331","item":"谭嗣同","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp332","item":"林则徐《四洲志》","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp333","item":"魏源《海国图志》","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp334","item":"南洪北孔：洪昇；《长生殿》（唐明皇李隆基、杨贵妃)；孔尚任；《桃花扇》（侯方域、李香君）","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp335","item":"（近代）朱光潜：是最早向中国介绍西方美学的学者；西学东渐；鸦片战争后：“师夷长技以制夷”——林则徐《西洲志》、魏源《海国图志》；甲午战争后：学习自然科学、社会科学；改革政治——康有为、梁启超、谭嗣同","dynasty":"近代","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp336","item":"伴随着文字的产生而出现的先秦文学，以诗歌和散文为主。","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp337","item":"夏商文化以巫文化最有代表性","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp338","item":"诗歌：《九歌》；《诗经·商颂》（五篇）；自嘲；运交华盖欲何求，未敢翻身已碰头；破帽遮颜过闹市，漏船载酒泛中流；横眉冷对千夫指，俯首甘为孺子牛；躲进小楼成一统，管他冬夏与春秋。","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp339","item":"散文：《商书》；其中的《盘庚》是可信的殷人作品；《尚书》——中国最早的散文总集；所录《禹贡》和《甘誓》两篇；据说是夏代的遗文；初盛唐：骈文仍居统治地位，但已开始出现变化；中唐：“古文运动”兴起，有力打击了骈文，出现了韩、柳两位散文大家，创作了大批优秀之作；晚唐：散文发展趋于衰落，骈文有复燃之势；朝花夕拾；散文：《龙·虎·狗》《旅途随笔》《生之忏悔》《随想录》","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp340","item":"神话：《山海经》","dynasty":"先秦","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp341","item":"西周春秋文学：巫术宗教文化逐渐被取代，礼乐文化成了主流；进入了以礼乐为标志的理性文明阶段。“史官文化”也因此而成熟。","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp342","item":"百家争鸣：战国时期思想文化领域十分活跃，百家争鸣的局面促进了文学的繁荣，产生了不同于前代而又风格各异的散文和诗赋","dynasty":"战国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp343","item":"名平","dynasty":"战国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp344","item":"字原","dynasty":"战国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp345","item":"《离骚》——浪漫主义色彩：是中国古代文学史上最长的一首浪漫主义抒情诗；以现实主义为基调，而以浪漫主义为特色，大量运用的比兴手法；打破了《诗经》的四言格式，创造了一种句法参差、韵散结合的新形式，后人称之为“骚体”","dynasty":"战国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp346","item":"《天问》","dynasty":"战国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp347","item":"《九歌》（11篇）","dynasty":"战国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp348","item":"《九章》（9篇）——鲜明的现实主义特征：《九章》在思想内容上与《离骚》大体相近，反复抒写理想不得实现的愤懑；但在表现手法上与《离骚》有所不同：多直抒胸臆，文笔比较朴素，想象夸饰成分极少","dynasty":"战国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp349","item":"《招魂》","dynasty":"战国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp350","item":"《卜居》","dynasty":"战国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp351","item":"《渔父》","dynasty":"战国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp352","item":"战国文学：战国文学突破了春秋时温文尔雅的风尚，时常表现出强烈的个性和激情，其中最有代表性的是《孟子》和《庄子》。","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp353","item":"秦：谏逐客书","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp354","item":"散体大赋","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp355","item":"骚体赋","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp357","item":"陋室铭中的“西蜀子云亭”","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp358","item":"《汉书》；《汉书》，又称《前汉书》；是中国第一部纪传体断代史，“二十四史”之一；由东汉时期史学家班固编撰；《汉书》是继《史记》之后中国古代又一部重要史书，与《史记》《后汉书》《三国志》并称为“前四史”；《汉书》全书主要记述了上起汉高祖元年（公元前206年），下至新朝王莽地皇四年（公元23年）共230年的史事，包括纪十二篇，表八篇，志十篇，传七十篇，共一百篇，后人划分为一百二十卷，全书共有八十万字。","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp359","item":"《两都赋》：西汉——长安；东汉——洛阳","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp360","item":"左思——三都赋：蜀都赋；吴都赋；魏都赋","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp362","item":"杨雄","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp363","item":"汉初三杰：韩信、张良、萧何","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp365","item":"《淮南子》：杂家；黄老之学的代表作；淮南王刘安所作；女娲补天、后羿射日、嫦娥奔月","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp366","item":"乐府双壁：《孔雀东南飞》；《木兰诗》；南朝","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp367","item":"乐府三绝：《孔雀东南飞》；《木兰诗》；南朝；《秦妇吟》；唐——韦庄","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp368","item":"《古诗十九首》——汉代文人五言诗最高成就：南朝萧统——《昭明文选》；五言之冠冕","dynasty":"汉代","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp369","item":"《说文解字》：东汉许慎；第一部按部首编排的字典","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp370","item":"曹操——改造文章的祖师：《龟虽寿》；《短歌行》；《观沧海》","dynasty":"魏晋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp371","item":"《全唐诗》及《全唐诗外编》：共收录诗作近五万二千首","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp372","item":"前期：代表诗人：宫廷诗人；上官仪；五言诗；“绮错婉媚”；上官体；在野诗人；王绩","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp373","item":"张若虚：与贺知章、张旭、包融齐名，并称为“吴中四士”","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp374","item":"后期：初唐四杰；王勃、杨炯、卢照邻、骆宾王；闻一多说他们“年少而才高，官小而名大”；《戏为六绝句》；杜甫创作的组诗作品；王杨卢骆当时体，轻薄为文哂未休；尔曹身与名俱灭，不废江河万古流。","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp375","item":"晚唐：小李杜；杜牧；字牧之，号樊川居士；杜樊川；李商隐；部分诗歌（以《锦瑟》为代表）过于隐晦迷离，难于索解，至有“诗家总爱西昆好，独恨无人作郑笺”；温庭筠；“温八叉”、“温八吟”；是花间词派的重要作家之一。被称为花间鼻祖；诗与李商隐齐名，并称“温李”；词与韦庄齐名，并称“温韦”","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp376","item":"唐代小说（唐传奇）：“标志着小说发展的一大变迁”；鲁迅；《枕中记》；沈既济；明朝汤显祖改编《邯郸记》","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp377","item":"初盛唐：处于民间词阶段","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp378","item":"五代时期：词体呈现片面的繁荣；出现了两大词坛；西蜀词坛；以“花间派”为主；代表词人：韦庄；南唐词坛；代表词人：李璟、李煜、冯延巳","dynasty":"五代","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp379","item":"韦庄：是长篇叙事诗《秦妇吟》；所著长诗《秦妇吟》；与《孔雀东南飞》《木兰诗》；并称“乐府三绝”","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp380","item":"庐陵五忠一节：欧阳修、杨邦乂、胡铨、周必大、杨万里、文天祥；杨万里；一节；脖子最硬——胡铨","dynasty":"宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp381","item":"元嘉三大家：鲍照；颜延之；谢灵运","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp382","item":"字子瞻，号东坡居士","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp383","item":"天下第三行书：寒食帖","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp384","item":"“三苏”：苏洵；苏辙","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp385","item":"北宋四大家：黄庭坚、米芾、蔡襄；宋词至柳永而一变，至苏轼而再变","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp386","item":"苏门四学士：黄庭坚、秦观、晁补之、张耒；秦观；字少游，号淮海居士；《宋史》评为“文丽而思深”；黄庭坚；江西诗派开山之祖；苏轼称其为“山谷体”","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp387","item":"陈师道","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp388","item":"周邦彦","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp389","item":"南宋前期：江西诗派；李清照；号易安居士；提出“别是一家”的观点；婉约词派代表，有“千古第一才女”之称；后人辑有《漱玉集》","dynasty":"南宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp390","item":"“中兴四大家”：杨万里；号诚斋，自号诚斋野客；杨万里的诗自成一家，独具风格，形成对后世影响颇大的诚斋体；范成大、尤袤、陆游","dynasty":"南宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp391","item":"南宋后期：江湖诗派；是南宋后期继永嘉四灵后而兴起的一个诗派，因陈起刊刻的《江湖集》而得名；四灵诗派，在一定程度上纠正了江西诗派以学问为诗、专在书本上找材料的习气。","dynasty":"南宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp392","item":"宋末：一派是稼轩之遗响，主要词人有刘克庄、刘辰翁、文天祥等；另一派是白石之羽翼，重要词家有吴文英、周密、王沂孙、张炎等","dynasty":"宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp393","item":"曲中双璧：张可久、乔吉","dynasty":"元","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp394","item":"四大南戏：“荆、刘（白）、拜、杀”；《荆钗记》；《白兔记》；《拜月亭》；《杀狗记》；四大南戏：（四大传奇）《荆钗记》《拜月亭记》《白兔记》《杀狗记》","dynasty":"元","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp395","item":"元杂剧四大悲剧：《窦娥冤》---关汉卿；《汉宫秋》---马致远；《梧桐雨》---白朴；《赵氏孤儿》---纪君祥","dynasty":"元","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp396","item":"元杂剧四大爱情剧：《拜月亭》---关汉卿；《西厢记》---王实甫；《墙头马上》---白朴；《倩女离魂》----郑光祖","dynasty":"元","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp397","item":"明代文学以嘉靖时期为界分前后两期","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp398","item":"明前期：《三国》、《水浒》","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp399","item":"汤显祖《临川四梦》：牡丹亭；紫钗记；南柯记；邯郸记","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp400","item":"吴承恩《西游记》","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp401","item":"兰陵笑笑生《金瓶梅》","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp402","item":"冯梦龙《三言》","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp403","item":"凌濛初“二拍”","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp404","item":"诗文最突出的是--公安派","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp405","item":"长篇章回体小说：这是中国古代长篇小说惟一的体裁；特点；分章叙事，分回标目，每回故事相对独立；前后勾连，首尾相接，全书构成统一整体；以《三国》《水浒》《西游》《金瓶梅》这“四大奇书”为标志","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp406","item":"短篇小说：以“三言”“二拍”为代表；林家铺子；农村三部曲；春蚕；秋收；残冬","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp407","item":"《紫钗记》：霍小玉","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp408","item":"《牡丹亭》：杜丽娘；大胆追求爱情、追求自由、追求个性解放的女性叛逆者形象；死而复生；汤显祖“自谓一生四梦，得意处唯在《牡丹》”","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp409","item":"《南柯记》：淳于棼顿悟：“人间君臣眷属，蝼蚁何殊？一切苦乐兴衰，南柯无二”","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp410","item":"《邯郸记》：卢生大悟：“糊涂帐，六十年光景，熟不得半箸黄梁！”","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp411","item":"吴中四杰：高启；杨基；张羽；徐贲","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp412","item":"台阁体：其主要代表“三杨”；杨士奇、杨荣、杨溥；于谦；是台阁颓风中一枝独秀的诗人","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp413","item":"茶陵派：谢铎、张泰、邵宝；做诗强调宗唐法杜，着眼于音调、法度；具有从“台阁体”向“前后七子”转化时期的过渡特点","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp414","item":"复社：明末以张溥、张采为首的具有政治斗争色彩的文化组织；张溥《五人墓碑记》；其宗旨是“兴复古学，务为有用”；文学上反对公安派、竟陵派末流空谈性灵、不问时事倾向；重新标举“复古”，为现实斗争服务；作品多表现时事，富于激情","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp415","item":"几社：陈子龙、夏完淳为首的文社组织；散文《狱中上母书》；政治态度、文学主张都与复社相同","dynasty":"明","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp416","item":"遗民诗人：顾炎武；《亭林诗文集》；《秋山》、《海上》、《精卫》；主张“文须有益于天下”；“诗主性情，不贵奇巧”；屈大均；《鲁连台》；富于民族意识，多故国之悲","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp417","item":"入仕诗人：钱谦益；宗宋派领袖；有《初学集》《有学集》《投笔集》等；吴伟业；尊唐派领袖；《梅村集》存诗1000多首；梅村体；代表作《圆圆曲》","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp418","item":"王士祯：神韵说；论诗提倡“神韵”；“神韵”即风神韵味","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp419","item":"沈德潜：《归愚诗文集》；格调说；强调写诗须讨究格律声调：“诗贵性情，亦须论法”","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp420","item":"翁方纲：倡“肌理说”；“为诗必以肌理为准”","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp421","item":"乾隆三大家：袁枚；《小仓山房诗文集》《随园诗话》；性灵说；提倡“提笔先须问性情”；赵翼；蒋士铨","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp422","item":"后期诗人：多重形式技巧，喜立派别门户","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp423","item":"清初词：“三大家”；陈维崧；“阳羡词派”领袖；朱彝尊；“浙西词派”领袖；纳兰性德","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp424","item":"清中叶词：“常州词派”；张惠言；周济","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp425","item":"清初散文：“学人之文”；以议论文见长；黄宗羲、顾炎武、王夫之；“文人之文”；以传记文见长；侯方域、魏禧、汪婉","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp426","item":"清中叶散文：“桐城派”；方苞；刘大櫆；姚鼐；提倡“义理”、“考证”、“辞章”三者相互为用","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp427","item":"苏州派：李玉；代表作《清忠谱》","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp428","item":"李渔的《风筝误》：是我国第一个喜剧创作专家；其中《风筝误》是代表作；《肉蒲团》；三弟肉蒲团真的好！","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp429","item":"洪昇的《长生殿》：《长生殿》；展现帝、妃情缘，宣扬李、杨挚爱；基本由《梧桐雨》脱化而来","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp430","item":"孔尚任的《桃花扇》：侯方域&李香君；“借离合之情，写兴亡之感”；侯方域&amp;李香君","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp431","item":"“批阅十载，增删五次”：只写成80回稿","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp432","item":"高鹗续书：《红》后40回由高鹗补成120回，完成宝、黛爱情悲剧。结尾有违雪芹原意，艺术也较逊色。","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp433","item":"脂砚斋：抄本80回，多有脂砚斋评语，题为《脂砚斋重评石头记》，简称“脂本”","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp434","item":"王国维《红楼梦评论》：《红楼梦》一书与一切喜剧相反，彻头彻尾之悲剧也。”","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp435","item":"宝玉：不满“金玉良缘”，向往“木石前盟”；“无材可去补苍天”；“三大病”；“恶劝”；“重情不重礼”；“有情极之毒”","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp436","item":"黛玉","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp437","item":"薛宝钗：任是无情也动人；“无情”集中体现为冷情寡欲，冷漠处世等；“动人”：体现为美貌、学识、善良天性。悲剧命运。","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp438","item":"王熙凤","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp439","item":"《儒林外史》：比较纯熟的白话；吴敬梓；鲁迅《中国小说史略》；作家“秉承公心，指摘时弊”；范进中举","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp440","item":"《聊斋志异》：蒲松龄；世称聊斋先生；《席方平》；阴曹之暗昧，尤甚于阳间；大冤未伸，寸心不死；《促织》；天子一跬步，皆关民命；喜剧故事《婴宁》","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp441","item":"《阅微草堂笔记》：纪昀","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp442","item":"清代四大藏书楼：山东聊城杨氏“海源阁”；常熟瞿氏铁琴铜剑楼；浙江归安陆氏“皕宋楼”；浙江钱塘丁氏“八千卷楼”","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp443","item":"魏源：海国图志","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp444","item":"严复：《天演论》；物竞天择，适者⽣存","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp445","item":"黄遵宪：我手写我口，古岂能拘牵；晚清诗史","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp447","item":"小说界革命：梁启超","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp448","item":"文界革命：梁启超；主张欧西文思；虽用文言文，却通俗易懂","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp449","item":"戏剧革命：新罗马传奇","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp450","item":"诗界革命：鲜明提出“诗界革命”口号的尽管是梁启超；但早已反映出诗歌变革趋向并获得创作成功，从而成为“诗界革命”旗帜的却是黄遵宪；诗界革命三长；新意境；新语句；以古意入诗","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp451","item":"王国维：人间词话","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp453","item":"前期小说：呐喊；彷徨","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp454","item":"后期历史小说：故事新编","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp455","item":"唯一一部中篇小说：阿Q正传","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp456","item":"诗化小说：伤逝；涓生和子君","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp457","item":"杂文：《记念刘和珍君》；且介亭杂文","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp459","item":"沈德鸿，字雁冰","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp460","item":"世纪中国的巴尔扎克；20世纪中国的巴尔扎克","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp461","item":"中篇小说：蚀三部曲；幻灭；发表第⼀篇⼩说《幻灭》使⽤“茅盾”为笔名；动摇；追求","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp462","item":"长篇小说：子夜；长篇小说：《骆驼样子》《四世同堂》（以祁家四世同堂的生活为主线，是一部感人的现实主义杰作，《惶恐》《偷生》《饥荒》）","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp466","item":"张恨水：章回体小说家；啼笑因缘；金粉世家","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp467","item":"我是天空里的一片云","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp468","item":"偶尔投影在你的波心——","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp469","item":"你不必讶异","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp470","item":"更无须欢喜——","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp471","item":"偶然：在转瞬间消灭了踪影；你有你的，我有我的，方向；在这交会时互放的光亮！","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp472","item":"你我相逢在黑夜的海上","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp473","item":"你记得也好","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp474","item":"最好你忘掉","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp475","item":"再别康桥：轻轻的我走了，正如我轻轻的来；我轻轻的招手，作别西天的云彩；那河畔的金柳，是夕阳中的新娘；波光里的艳影，在我的心头荡漾；软泥上的青荇，油油的在水底招摇；在康河的柔波里，我甘心做一条水草！；那榆荫下的一潭，不是清泉，是天上虹；揉碎在浮藻间，沉淀着彩虹似的梦；寻梦？撑一支长篙，向青草更青处漫溯；满载一船星辉，在星辉斑斓里放歌；但我不能放歌，悄悄是别离的笙箫；夏虫也为我沉默，沉默是今晚的康桥！；悄悄的我走了，正如我悄悄的来；我挥一挥衣袖，不带走一片云彩。","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp478","item":"汉园三诗人：何其芳；李广田；卞之琳","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp482","item":"欧阳予倩：中国现代戏剧之父","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp486","item":"爱情三部曲：雾；雨；电","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp488","item":"老舍：舒庆春，字舍予；带泪的笑；骆驼祥子；四世同堂；我这一辈子；话剧；茶馆；京味文学开创者，老舍、巴金、茅盾是三位齐名的长篇小说大家；话剧：《茶馆》《龙须沟》（奠定“人民艺术家”的称号）原名舒庆春，字舍予，现代小说家、剧作家，获“人民艺术家”称号，京味文学代表，代表作《骆驼祥子》《茶馆》《四世同堂》","dynasty":"现代","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp493","item":"艾⻘：诗集《⼤堰河》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp494","item":"中国话剧现实主义的基石","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp495","item":"周朴园","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp496","item":"繁漪：最具“雷⾬”性格：⼀个受五四思想感染的新⼥性；现实中⼀个“⺟亲不是⺟亲","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp497","item":"周萍","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp498","item":"四风","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp499","item":"鲁大海","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp500","item":"鲁妈","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp502","item":"王昭君","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp507","item":"贺敬之：白毛女；黄世仁；杨白劳；喜儿；旧社会把人变成鬼；新社会把鬼变成人","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp508","item":"红岩：江姐","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp512","item":"周立波：《暴风骤雨》；与丁玲的《太阳照在桑干河上》一起获得斯大林文学奖；代表作《暴风骤雨》《山乡巨变》，写农村土改与合作化","dynasty":"当代","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp513","item":"魏巍：《谁是最可爱的人》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp514","item":"杜鹏程：《保卫延安》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp515","item":"杨朔：好的散文就是一首诗；杨氏散文","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp516","item":"刘白羽：《日出》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp517","item":"杨沫：青春三部曲；《青春之歌》；林道静；《苏菲之歌》；《英华之歌》代表作《青春之歌》，塑造林道静这一成长中的知识分子形象","dynasty":"当代","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp525","item":"余秋雨：“文化散文”；《文化苦旅》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp528","item":"海岩：《一场风花雪月的事》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp529","item":"林海音：《城南旧事》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp531","item":"——————————————————","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp532","item":"新文化运动：新青年；主编——陈独秀","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp533","item":"五四白话文运动：文学改良刍议；是倡导文学革命的第一篇文章；狂人日记；标志着中国现代文学的开端","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp534","item":"文学研究会：周作⼈、郑振铎、沈雁冰、王统照、许地⼭、朱希祖、蒋百⾥、耿济之、瞿世英、郭绍虞、孙伏园、叶绍钧等12⼈；研究介绍世界⽂学，整理中国旧⽂学，创造新⽂学；为⼈⽣⽽艺术；1921年1月成立于北京，发起人有郑振铎、沈雁冰（茅盾）、叶绍钧（叶圣陶）、许地山、王统照、周作人等，以《小说月报》为阵地，提倡现实主义，主张“为人生而艺术”","dynasty":"现代","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp536","item":"新⽉社：新格律派；胡适、陈源、徐志摩、闻⼀多、梁实秋","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp539","item":"中国左翼作家联盟：左联；鲁迅；夏衍","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp540","item":"孤岛文学：夜上海","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp542","item":"解放区⽂学：⼩说有赵树理的《⼩⼆⿊结婚》；丁玲的《太阳照在桑乾河上》；周⽴波的《暴⻛骤⾬》；贺敬之等集体创作的新歌剧《⽩⽑⼥》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp543","item":"白洋淀派（荷花淀派）：孙犁；铁木前传","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp544","item":"十七年文学：红日；林海雪原；太阳照在桑干河上；老舍；田汉；柳青；周立波","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp545","item":"三红一创：吴强的《红日》；罗广斌、杨益言的《红岩》；梁斌的《红旗谱》；柳青的《创业史》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp546","item":"世纪50年代文坛三大散文家：杨朔；秦牧；刘白羽","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp550","item":"先锋派小说：余华","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp551","item":"蒲松龄（清）小说家：《聊斋志异》简称《聊斋》，俗名《鬼狐传》，是志怪小说；山东学政施闰章所赏识，称其文章“观书如月，运笔如风，有掉臂游行之乐；全国人大常委原副委员长胡厥文题词：落落宏才未得申，挥笔弄墨染风尘。意弥性挚开金石，天顺人和狐鬼驯。绣口锦心有若无，生花彩笔假犹真。千篇恩爱悲欢剧，易俗移风劝世人；文言短篇小说的巅峰之作，我国文言短篇小说最高成就","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp552","item":"《聊斋》目录：《婴宁》——书生与花鬼狐妖爱情；《席方平》——勇敢的复仇者","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp553","item":"《聊斋》评价：清代冯镇峦〈读聊斋杂说〉：“如名儒讲学，如老僧谈禅，如乡曲长者读诵劝世文，观之实有益于身心，警戒顽愚。至说到忠孝节义，令人雪涕，令人猛醒，更为有关世教之书。”；现代文学家鲁迅：“变幻之状，如在目前；又或易调该弦，别叙崎人异行，出于幻灭，顿入人间；偶叙琐闻，亦多简洁，故读者耳目，为之一新。使花妖狐魅，多是人情，和易可亲，忘为异类，而又偶见鹘突，知复非人。”；现代文学家郭沫若：“写鬼写妖高人一等，刺贪刺虐入骨三分。”；现代文学家老舍：“鬼狐有性格，笑骂成文章。”","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp557","item":"自称“异史氏”","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp558","item":"中国第一部神话小说：《山海经》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp559","item":"中国第一部神话小说集：《搜神记》——东晋史学家干宝，笔记体志怪小说集，开创了中国古代神话小说的先河","dynasty":"东晋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp560","item":"《搜神记》（志怪小说）","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp561","item":"《世说新语》（志人小说）","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp562","item":"鲁迅的《铸剑》：短篇历史小说，原题《眉间尺》，取材于《列异传》《搜神记》等古籍所记载的“三王冢”的故事","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp563","item":"上古三大奇书：《山海经》《易经》《黄帝内经》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp564","item":"“史学双壁”：《史记》（西汉司马迁）、《资治通鉴》（北宋司马光）；“史学双壁”：《史记》《资治通鉴》","dynasty":"西汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp565","item":"“乐府双壁”：《孔雀东南飞》（汉代乐府民歌，长篇叙事诗）、《木兰诗》（南北朝长篇叙事诗）","dynasty":"汉代","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp566","item":"清代文言笔记小说的＂双璧＂：《阅微草堂笔记》，《聊斋志异》","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp567","item":"《乐府诗集》：郭茂倩（北宋）；继《诗经》之后总括中国古代乐府歌辞的诗歌总集，是现存收集乐府歌辞最完备的一部","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp568","item":"汪琬（清）散文家：字苕文、小字液仙；号钝庵，初号玉遮山樵、晚号尧峰；世称“尧峰先生”；著《传世楼记》、《尧峰诗文钞》、《钝翁前后类稿、续稿》；文风：疏畅通达；汪琬的散文创作可分为两大类：经史之文与小品纪游之文，经史之文不仅占据了大多数篇幅，而且体现了其创作的根本旨趣与艺术风格，代表着其散文的主要成就；评价；梁启超等人将清代朴学之兴归功于顾炎武、阎若璩等人。汪琬也是朴学隆兴的关键人物之一。吴中经学一派近源有二，即汪琬与顾炎武。","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp569","item":"明末清初散文“三大家”：侯方域、魏禧、汪琬","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp570","item":"昆山三徐（一门三进士）：（清）徐乾学、徐秉义、徐元文三兄弟","dynasty":"清","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp571","item":"《纳兰容若词传》（一三六）——传是楼：教子有遗经，诗书易春秋礼记，；传家无别业，解会状榜眼探花。","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp572","item":"胡铨（南宋）爱国名臣、文学：《戊午上高宗封事》：奏疏痛斥了王伦、秦桧、孙近等人的投降卖国行径，阐明了反对和议、坚持抗金的立场和理由，提出了将王伦、秦桧、孙近斩首示众的严正要求；字邦衡；号澹庵；追赠通议大夫；谥号“忠简”；著有《澹庵集》《戊午上高宗封事》（骈体文）；评价；王庭珪：痴儿不了公家事，男子要为天下奇","dynasty":"南宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp573","item":"庐陵“五忠一节”：“文忠”欧阳修、（忠襄）杨邦乂、（忠简）胡铨、（文忠）周必大、（忠烈）文天祥、（文节）杨万里","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp574","item":"“南宋四名臣”：李纲、赵鼎、李光、胡铨","dynasty":"南宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp575","item":"别名：朱说、范履霜、范文正","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp576","item":"字希文，谥号“文正”，世称范文正公，“三光名臣”","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp577","item":"著《范文正公集》《岳阳楼记》（庆历新政后这篇文章便是写于邓州，而非写于岳阳楼）","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp578","item":"蔡襄：“公薨之后，独无余资。君国以忠，亲友以义，进退安危，不易其志。立身大节，明白如是。”[298]","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp579","item":"毛泽东：中国历史上有些知识分子是文武双全，不但能够下笔千言，而且是知兵善战。范仲淹就是这样的一个典型，（范仲淹词）介于婉约与豪放两派之间，既苍凉又优美，使人不厌读。","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp580","item":"江泽民：所有党员领导干部，都应该“先天下之忧而忧，后天下之乐而乐”","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp581","item":"典故：断齑画粥","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp582","item":"字子厚","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp583","item":"人称柳河东，又称柳柳州，“河东先生”","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp584","item":"堪称中国历史上最杰出的散文家","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp585","item":"唐宋八大家之一","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp586","item":"“刘柳”：与刘禹锡并称","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp587","item":"“韩柳”：与韩愈并称；“韩柳”：与柳宗元并称","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp588","item":"“王孟韦柳”：王维、孟浩然、韦应物并称","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp589","item":"文风：骈文有近百篇，散文论说性强，笔锋犀利，讽刺辛辣","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp590","item":"柳宗元一生留诗文作品达600余篇，其文的成就大于诗","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp591","item":"著《永州八记》名为《柳河东集》，代表作有《溪居》《江雪》《渔翁》","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp592","item":"柳宗元·历代评价：苏轼：“所贵乎枯谈者，谓其外枯而中膏，似淡而实美，渊明、子厚之流是也。”；欧阳修：“天于生子厚，禀予独艰哉。超凌骤拔擢，过盛辄伤摧。苦其危虑心，常使鸣心哀。投以空旷地，纵横放天才。山穷与水险，上下极沿洄。故其于文章，出语多崔嵬。”；严羽：“唐人惟子厚深得骚学。”；毛泽东：“柳宗元是一位唯物主义哲学家，见之于他的《天说》，这篇哲学论著提出了‘天与人交相胜’的论点反对天命论。刘禹锡发展了这种唯物主义。”；潘向黎：作为作家，他敢为风气之先，为文为诗气势磅礴；作为一个生命个体的“人”，他刚直敢任，人格伟岸，诚为伟丈夫。如此人中鸾凤，却也是性情中人，不但极重感情，而且敏感于生活中的许多细微乐趣或烦恼，而且有幽默的一面；白居易：学术精博，文力雄健，立词措意，有班（班固）、马（司马迁）之风，求之一时，甚不易得。加以性方道直，介然有守，不交势利，自致名望。可使执简，列为史官，记事书法，必无所苟。[53]","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp593","item":"永州八记：《始得西山宴游记》；《古鉧潭记》；《古鉧潭西小丘记》；《至小丘西小石潭记》；《袁家渴记》；《石渠记》；《石涧记》；《小石城山记》","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp595","item":"《张中丞传后叙》：这是表彰安史之乱期间睢阳（今河南商丘）守将张巡、许远的一篇名作，是作者在阅读李翰所写的《张巡传》后，对有关材料作的补充，对有关人物的议论，所以题为“后叙”。文中关于南霁云拒食断指、抽矢射塔，张巡诵读《汉书》、起旋众泣等细节描写颊上添毫，传神写意，形象栩栩如生，光采照人。","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp597","item":"自称“祖籍昌黎郡”，世称“韩昌黎”、“昌黎先生”，人称“韩吏部”","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp598","item":"追赠礼部尚书，谥号为“文”，故称“韩文公”","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp599","item":"追封昌黎郡伯，并从祀孔庙","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp600","item":"唐代古文运动的倡导者","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp601","item":"名列“唐宋八大家”之首","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp602","item":"有“文章巨公”和“百代文宗”之名","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp603","item":"“千古文章四大家”：柳宗元、欧阳修和苏轼并称；“千古文章四大家”：韩愈、柳宗元、欧阳修、苏轼","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp604","item":"倡导“文道合一”、“气盛言宜”、“务去陈言”、“文从字顺”等写作理论","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp605","item":"著《韩昌黎集》《张中丞传后叙》","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp606","item":"郦道元（北朝北魏）地理学家、散文家：字善长；文风：文笔隽永，描写生动；《水经注》可称为我国游记文学的开创者，对后世游记散文的发展影响颇大；撰《水经注》四十卷，著《本志》十三篇及《七聘》；评价；毛泽东：①《水经注》作者也是一位了不起的人。②《水经注》写得好！但不是深入实地地去走一走是写不出那么好的文字的。郦道元从事野外工作力求实证的方法和成果，标志着中国古代地理学进入一个新阶段；日本地理学家米仓二郎：郦道元是中世纪世界上最伟大的地理学家；原德国柏林大学校长李希霍芬称郦道元《水经注》：世界地理学的先导。","dynasty":"南北朝","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp607","item":"司马迁（西汉）史学家：字子长；司马谈之子；尊称为史迁、太史公、历史之父；他以其“究天人之际，通古今之变，成一家之言”的史识创作了中国第一部纪传体通史《史记》（原名《太史公书》），被公认为是中国史书的典范，该书记载了从上古传说中的黄帝时期，到汉武帝元狩元年，长达3000多年的历史，是“二十四史”之首；评价；鲁迅誉为“史家之绝唱，无韵之离骚”","dynasty":"西汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp608","item":"班固（东汉）史学家：字孟坚；东汉大臣、史学家、文学家；与司马迁并称“班马”；作为史学家，修撰《汉书》，是“前四史”之一；作为辞赋家，是“汉赋四大家”之一，《两都赋》开创了京都赋的范例，列入《文选》第一篇；作为经学理论家，所编《白虎通义》集当时经学之大成，将谶纬神学理论化、法典化；相关典故：文人相轻；不相伯仲、不分伯仲；下笔不休","dynasty":"东汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp609","item":"“汉赋四大家”：司马相如、扬雄、班固、张衡","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp610","item":"司马相如“赋圣”、“辞宗”：司马相如，字长卿；被誉为“赋圣”、“辞宗”；第二批四川历史名人；著《子虚赋》，《上林赋》、《大人赋》、《长门赋》、《美人赋》、《哀秦二世赋》，《梨赋》、《鱼葅赋》、《梓山赋》、《司马相如上书谏猎》，《凤求凰》，《天子游猎赋》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp611","item":"扬雄（汉）辞赋家：扬雄，字子云；著有《甘泉赋》、《羽猎赋》、《长杨赋》、《河东》《法言》《太玄》；仿效屈原楚辞，写有《反离骚》、《广骚》和《畔牢愁》等作品（《反离骚》为凭吊屈原而作，对诗人遭遇充满同情，但又用老、庄思想指责屈原“弃由、聃之所珍兮，摭彭咸之所遗”，反映了作者明哲保身的思想，而未能正确地评价屈原）；将源于老子之道的“玄”作为最高范畴，在构筑宇宙生成图式、探索事物发展规律方面，是汉朝道家思想的继承和发展者，对后世意义可谓重大。","dynasty":"汉代","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp612","item":"张衡（东汉）天文学家、数学家、发明家、地理学家、文学家：张衡，字平子，北宋时被追封为西鄂伯；后人誉其为“木圣”或“科圣”；张衡在天文学方面著有《灵宪》《浑仪图注》；数学著作有《算罔论》；文学作品以《二京赋》《归田赋》；张衡为中国天文学、机械技术、地震学的发展作出了杰出的贡献，发明地动仪、改进浑天仪，是东汉中期浑天说的代表人物之一","dynasty":"东汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp613","item":"傅毅：著《洛都赋》《反都赋》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp614","item":"范晔（南朝宋）史学家：范晔，字蔚宗；著《后汉书》，博采众书，结构严谨、属词丽密；与《史记》《汉书》《三国志》并称“前四史”。","dynasty":"南北朝","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp615","item":"《后汉书》：《后汉书》中分十纪、八十列传和八志（取自司马彪《续汉书》）；全书主要记述了上起东汉的汉光武帝建武元年（公元25年），下至汉献帝建安二十五年（公元220年），共195年的史事；《后汉书》的进步性还体现在勇于暴露黑暗政治，同情和歌颂正义的行为方面，一方面揭露鱼肉人民的权贵，另一方面又表彰那些刚强正直、不畏强暴的中下层人士","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp616","item":"陈寿（三国时期）史学家：字承祚；纪传体史学巨著《三国志》此书完整地记叙了自汉末至晋初近百年间中国由分裂走向统一的历史全貌","dynasty":"三国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp617","item":"《三国志》：《三国志》，二十四史之一，是由西晋史学家陈寿所著；记载中国三国时期的曹魏、蜀汉、东吴纪传体断代史；三国志最早以《魏书》《蜀书》《吴书》三书单独流传。为了避免曹魏的《魏书》与南北朝时期北魏的《魏书》相互混淆，北宋王朝在咸平六年（1003年）将三书合为一书，最终成书；《三国志》也是二十四史中最为特殊的一部，因为其过于简略，没有记载王侯、百官世系的“表”，也没有记载经济、地理、职官、礼乐、律历等的“志”，不符合《史记》和《汉书》所确立下来的一般正史的规范","dynasty":"三国","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp618","item":"司马光（北宋）政治学家、史学家：字君实，号迂叟，世称涑水先生；追赠太师、温国公，谥号文正；名列“元祐党人”，配享宋哲宗庙廷，图形昭勋阁；从祀于孔庙，称“先儒司马子”；从祀历代帝王庙；以“日力不足，继之以夜”自诩，堪称儒学教化下的典范；著《资治通鉴》《温国文正司马公文集》、《稽古录》、《涑水记闻》、《潜虚》","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp619","item":"《资治通鉴》：《资治通鉴》（常简作《通鉴》）；是由北宋史学家司马光主编的一部多卷本编年体史书，共294卷，历时十九年完成；主要以时间为纲，事件为目，从周威烈王二十三年（公元前403年）写起，到五代后周世宗显德六年（公元959年）征淮南停笔，涵盖十六朝1362年的历史；宋神宗认为此书“鉴于往事，有资于治道”，即以历史的得失作为鉴诫来加强统治，所以定名为《资治通鉴》；《资治通鉴》全书294卷，约三百多万字，另有《考异》、《目录》各三十卷","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp620","item":"贾谊（西汉）政论家：《过秦论》先帝例子（秦孝公、秦惠王、秦穆公、秦昭王）；四君子（齐有孟尝，赵有平原，楚有春申，魏有信陵）；世称“贾生”；贾谊与屈原并称为“屈贾”；贾谊著作主要有散文和辞赋两类，散文的主要文学成就是政论文，评论时政，风格朴实峻拔，议论酣畅，鲁迅称之为“西汉鸿文”；代表作有《过秦论》《论积贮疏》《陈政事疏》，其辞赋皆为骚体，形式趋于散体化，是汉赋发展的先声，以《吊屈原赋》《鵩鸟赋》最为著名；评价；毛泽东：“（《治安策》）是西汉一代最好的政论”，“全文切中当时事理”；鲁迅：贾谊的政论文是“西汉鸿文”","dynasty":"西汉","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp621","item":"李斯（秦）政治家、书法家：《谏逐客书》：写给秦王嬴政的奏议。此文先叙述秦国自秦穆公以来皆以客致强的历史，说明秦国若无客助则未必强大的道理；然后列举各种女乐珠玉虽非秦地所产却被喜爱的事实作比，说明秦王不应重物而轻人；字通古；李斯的政治主张的实施，对中国和世界产生了深远的影响，奠定了中国两千多年封建专制的基本格局；评价；毛泽东：“孟夫子一派主张后法先王，厚古薄今，反对秦始皇。李斯是拥护秦始皇的，属于荀子一派，主张先法后王。”；鲁迅：“秦之文章，李斯一人而已”，“然子文字，则有殊勋。”他的书法“小篆入神，大篆入妙”，被称为书法鼻祖","dynasty":"秦代","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp622","item":"《左传》重纪事：中国第一部叙事详细的编年史著作：《春秋》是记事的，后多散佚，仅留下孔子整理的鲁国《春秋》；《左传》原名《左氏春秋》，汉代改称《春秋左氏传》，简称《左传》。旧时相传是春秋末年左丘明为解释孔子的《春秋》而作；我国第一部最富文采，标志着我国古代叙事散文的成熟著作；历代评价：晋范宁评“春秋三传”的特色说：“《左氏》艳而富，其失也巫（指多叙鬼神之事）。《谷梁》清而婉，其失也短。《公羊》辩而裁，其失也俗。”当然，这只是一家之言；南宋·吕祖谦《东莱博议》卷一：“导之以逆，而反诛逆；教之以叛，而反讨其叛！庄公之用心亦险矣！”；明·归有光《世宗实录》：“此左氏笔力之最高者。”；清·余诚《重订古文释义新编》卷一引吴荪右语：“文章之祖。”","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp623","item":"《国语》重纪言：中国第一部国别体史书：上起周穆王十二年（公元前990年）西征犬戎（约公元前947年），下至智伯被灭（公元前453年）","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp624","item":"姓姜，氏丘，名明，一说复姓左丘，名明；一说单姓左，名丘明","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp625","item":"左丘明是中国传统史学的创始人","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp626","item":"史学界推左丘明为中国史学的开山鼻祖","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp627","item":"被誉为“百家文字之宗、万世古文之祖”","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp628","item":"被誉为“文宗史圣”、“经臣史祖”","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp629","item":"著有《春秋左氏传》、《国语》","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp630","item":"孔子、司马迁均尊左丘明为“君子”","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp631","item":"“春秋三传”：《公羊传》、《谷梁传》、《左传》，且都是编年体史书","dynasty":"春秋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp633","item":"周代：公、候、伯、子、男","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp634","item":"刘向（汉）中国目录学鼻祖：原名刘更生，字子政；所撰《别录》，是我国最早的图书公类目录；今存《新序》《说苑》《列女传》《战国策》《五经通义》；编订《楚辞》，联合儿子刘歆共同编订《山海经》；散文主要是奏疏和校雠古书的“叙录”，较有名的有《谏营昌陵疏》和《战国策·叙录》，作品收录于《刘子政集》","dynasty":"汉代","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp635","item":"————————————————————————————————————————————————————————————————————","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp636","item":"“苏门四学士”：黄庭坚、张耒、晁补之、秦观","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp637","item":"“宋四家”（书法）：黄庭坚、北宋苏轼、米芾、蔡襄","dynasty":"北宋","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp638","item":"“苏黄”（文学）：黄庭坚、苏轼","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp639","item":"战役：以弱胜强；长勺之战；赤壁之战；官渡之战；淝水之战；以少胜多","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp641","item":"记→散文体裁：叙事《桃花源记》；写景《小石潭记》；说明《核舟记》；言志《岳阳楼记》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp643","item":"《春江花月夜》（唐）张若虚：“人生代代无穷已，江月年年望相似”：“诗中的诗，顶峰上的顶峰”——闻一多赞誉","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp644","item":"《代悲白头翁》（唐）刘希夷：“年年岁岁花相似，岁岁年年人不同”","dynasty":"唐","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp645","item":"庄周——《庄子》：东施效颦；邯郸学步；曳尾涂中；鸱得腐鼠；知鱼之乐","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp646","item":"孟轲——《孟子》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp647","item":"韩非——《韩非子》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp648","item":"柳宗元——《三戒》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp649","item":"《山海经》——刘向","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp650","item":"《淮南子》——刘安","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp651","item":"“风骚”：《诗经》（的《国风》）、《离骚》（《楚辞》里）","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp652","item":"我国第一部文学批评专注：《文赋》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"},{"id":"lp653","item":"我国第一篇论文：《典论*论文》","dynasty":"","cat":"作家作品","source":"幕布笔记整理"}],"n":689},{"key":"B","name":"中国传统文化·基本常识","desc":"纪年纪时 · 节令民俗 · 称谓避讳 · 年龄称谓 · 科举官制 · 职官制度 · 礼制婚丧 · 宗法家族 · 地理方位 · 经史子集 · 文体知识 · 文学流派 · 书画艺术 · 音乐名物 · 科技典籍 · 宗教哲学 · 谦敬辞令","count":115,"items":[{"id":"wh004","item":"年号：封建帝王纪年的名号，始于汉武帝，如康熙、乾隆；新君即位常改元。","dynasty":"","cat":"纪年纪时","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"纪年纪时"},{"id":"wh005","item":"干支纪年：以十天干（甲乙丙丁戊己庚辛壬癸）配十二地支（子丑寅卯辰巳午未申酉戌亥）循环纪年，六十年一周期，称一甲子。","dynasty":"","cat":"纪年纪时","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"纪年纪时"},{"id":"wh006","item":"十二生肖（属相）：与十二地支相配的十二种动物——鼠、牛、虎、兔、龙、蛇、马、羊、猴、鸡、狗、猪。","dynasty":"","cat":"纪年纪时","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"纪年纪时"},{"id":"wh007","item":"十二时辰：古人把一昼夜分为十二段，用地支纪时，子时为23时至1时，每时辰合今两小时。","dynasty":"","cat":"纪年纪时","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"纪年纪时"},{"id":"wh008","item":"五更：古人把夜分为甲、乙、丙、丁、戊五段，称五鼓、五更，每更约两小时。","dynasty":"","cat":"纪年纪时","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"纪年纪时"},{"id":"wh009","item":"二十四节气：古人根据太阳运行划分的二十四个时令，如立春、清明、夏至、秋分、冬至等，指导农时。","dynasty":"","cat":"纪年纪时","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"纪年纪时"},{"id":"wh039","item":"花甲（耳顺）之年：指六十岁，因干支纪年六十年循环一周（一甲子）。","dynasty":"","cat":"纪年纪时","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"纪年纪时"},{"id":"wh113","item":"古代计时：一昼夜十二时辰（子丑寅卯辰巳午未申酉戌亥），每时辰两小时；一夜五更，每更两小时；另有漏刻、日晷计时。","dynasty":"","cat":"纪年纪时","source":"文学常识补充（教材通行说法）","theme":"纪年纪时"},{"id":"wh122","item":"干支纪日：用天干地支相配纪日，六十日一循环，是我国最早的纪日法，甲骨文中已使用。","dynasty":"","cat":"纪年纪时","source":"考纲文化常识扩展","theme":"纪年纪时"},{"id":"wh123","item":"朔望晦：农历每月初一为朔，十五为望，最后一天为晦。既望指十六日，如《赤壁赋》\"壬戌之秋，七月既望\"。","dynasty":"","cat":"纪年纪时","source":"考纲文化常识扩展","theme":"纪年纪时"},{"id":"wh124","item":"孟仲季：古人以孟、仲、季表示每季的三个月份，如孟春为正月、仲春为二月、季春为三月。","dynasty":"","cat":"纪年纪时","source":"考纲文化常识扩展","theme":"纪年纪时"},{"id":"wh206","item":"干支纪年换算：公元纪年换算干支，可用（年份-3）÷60取余数对应干支；如2026年为丙午年。","dynasty":"","cat":"纪年纪时","source":"考纲文化常识扩展","theme":"纪年纪时"},{"id":"wh207","item":"古代时间单位：一刹那、一念、一瞬、一弹指、一罗预、须臾、一盏茶、一炷香、一时辰、一昼夜。","dynasty":"","cat":"纪年纪时","source":"考纲文化常识扩展","theme":"纪年纪时"},{"id":"wh208","item":"更点制：一夜五更，每更又分五点，一更约两小时，一点约24分钟。\"三更\"约当午夜。","dynasty":"","cat":"纪年纪时","source":"考纲文化常识扩展","theme":"纪年纪时"},{"id":"wh010","item":"春节：农历正月初一，古称元日、元旦，有贴春联、守岁、拜年习俗。","dynasty":"","cat":"节令民俗","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"节令民俗"},{"id":"wh011","item":"元宵节：农历正月十五，又称上元节，有赏灯、吃元宵习俗。","dynasty":"","cat":"节令民俗","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"节令民俗"},{"id":"wh012","item":"清明节：公历四月五日前后，扫墓祭祖、踏青，与寒食节相联。","dynasty":"","cat":"节令民俗","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"节令民俗"},{"id":"wh013","item":"端午节：农历五月初五，纪念屈原，有赛龙舟、吃粽子、挂艾草习俗。","dynasty":"","cat":"节令民俗","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"节令民俗"},{"id":"wh014","item":"七夕：农历七月初七，相传牛郎织女相会，又称乞巧节。","dynasty":"","cat":"节令民俗","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"节令民俗"},{"id":"wh015","item":"中秋节：农历八月十五，阖家团圆，赏月、吃月饼。","dynasty":"","cat":"节令民俗","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"节令民俗"},{"id":"wh016","item":"重阳节：农历九月初九，登高、赏菊、饮菊花酒、插茱萸，现为老人节。","dynasty":"","cat":"节令民俗","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"节令民俗"},{"id":"wh017","item":"除夕：农历一年最后一天的晚上，阖家团聚、守岁。","dynasty":"","cat":"节令民俗","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"节令民俗"},{"id":"wh099","item":"绘画名家：顾恺之（东晋，《洛神赋图》）、吴道子（唐，『画圣』）、阎立本、张择端（《清明上河图》）、八大山人（朱耷）、郑板桥（扬州八怪）。","dynasty":"","cat":"节令民俗","source":"文学常识补充（教材通行说法）","theme":"节令民俗"},{"id":"wh116","item":"上巳节：农历三月初三，古人在水边洗濯祓除不祥，后演变为春游踏青，王羲之《兰亭集序》所记即上巳修禊之事。","dynasty":"","cat":"节令民俗","source":"考纲文化常识扩展","theme":"节令民俗"},{"id":"wh117","item":"寒食节：清明前一两天，禁烟火、吃冷食，相传为纪念介子推，后与清明节融合。","dynasty":"","cat":"节令民俗","source":"考纲文化常识扩展","theme":"节令民俗"},{"id":"wh118","item":"中元节：农历七月十五，又称鬼节、盂兰盆节，祭祖超度亡魂。","dynasty":"","cat":"节令民俗","source":"考纲文化常识扩展","theme":"节令民俗"},{"id":"wh119","item":"腊八节：农历十二月初八，喝腊八粥，相传与佛教释迦牟尼成道日有关。","dynasty":"","cat":"节令民俗","source":"考纲文化常识扩展","theme":"节令民俗"},{"id":"wh120","item":"小年：农历腊月二十三（北方）或二十四（南方），祭灶神，标志年节开始。","dynasty":"","cat":"节令民俗","source":"考纲文化常识扩展","theme":"节令民俗"},{"id":"wh121","item":"社日：古代祭祀土神的日子，分春社（祈丰收）、秋社（谢神），王驾《社日》\"桑柘影斜春社散\"。","dynasty":"","cat":"节令民俗","source":"考纲文化常识扩展","theme":"节令民俗"},{"id":"wh002","item":"谥号：古代帝王、大臣死后按其生平事迹给予的评价性称号，如范仲淹谥“文正”，欧阳修谥“文忠”。","dynasty":"","cat":"称谓避讳","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"称谓避讳"},{"id":"wh003","item":"庙号：帝王死后在太庙立室奉祀追尊的名号，如“太祖”“太宗”。","dynasty":"","cat":"称谓避讳","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"称谓避讳"},{"id":"wh052","item":"避讳：古代对君主或尊长的名字，避免直接直说或直写，须改用同义字或缺笔；古人对君主或尊长不直称其名，须改用同义字或缺笔。如避唐太宗李世民讳，『民』改『人』；避孔子讳，『丘』缺笔。","dynasty":"","cat":"称谓避讳","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"称谓避讳"},{"id":"wh066","item":"谦辞：称自己或自己一方用谦辞。家父/家严（父）、家母/家慈（母）、舍弟（弟）、拙作（自己的作品）、寒舍（自己的家）、敝姓（自己的姓）、犬子（自己的儿子）、内人（妻子）。","dynasty":"","cat":"称谓避讳","source":"文学常识补充（教材通行说法）","theme":"称谓避讳"},{"id":"wh067","item":"敬辞：称对方用敬辞。令尊（对方父亲）、令堂（对方母亲）、令郎（对方儿子）、令爱（对方女儿）、贤弟、高见、赐教、惠存、垂询、拜读。","dynasty":"","cat":"称谓避讳","source":"文学常识补充（教材通行说法）","theme":"称谓避讳"},{"id":"wh111","item":"死亡称谓：天子死曰崩，诸侯曰薨，大夫曰卒，士曰不禄，庶人曰死；僧人曰圆寂、涅盘，道士曰羽化、登仙。","dynasty":"","cat":"称谓避讳","source":"文学常识补充（教材通行说法）","theme":"称谓避讳"},{"id":"wh155","item":"帝王自称：朕（秦始皇始为天子专称）、孤、寡人、不穀。臣下自称：臣、仆、愚、窃、卑职、下官。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh191","item":"避讳三法：改字（避李世民讳\"民\"改\"人\"）、缺笔（避孔子讳\"丘\"缺笔）、空字（留空或书\"某\"）。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh194","item":"古代谦敬辞辨析：\"忝\"（辱没，忝列门墙）、\"猥\"（谦称自己，猥以微贱）、\"伏惟\"（伏地想，表敬）、\"谨\"（恭敬地）、\"幸\"（希望）。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh195","item":"古代书信格式：上款（受信人称呼）、正文、下款（自称+署名+敬辞+日期）。常用敬辞有\"顿首\"\"再拜\"\"谨启\"\"敬上\"。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh196","item":"古代称谓\"先\"与\"亡\"：先父、先母、先祖指已故尊长；亡妻、亡友指已故平辈或配偶。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh198","item":"古代职业称谓：士农工商为四民；医称杏林、悬壶；教师称西席、夫子；戏剧界称梨园。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh200","item":"桃李与高足：桃李喻学生，高足喻优秀弟子，门生、及门亦指学生。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh212","item":"古代称谓\"陛下/殿下/阁下/足下/膝下\"：陛下称帝王，殿下称太子亲王，阁下称显贵，足下称同辈，膝下称父母。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh213","item":"古代自称\"不才/不佞/不肖/鄙人/愚/蒙/窃\"：皆为谦称，表自己才能低下或地位卑微。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh214","item":"古代尊称\"子/夫子/先生/公/君/卿/大人\"：子为对男子的尊称或师长，夫子为对老师的尊称。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh215","item":"古代谥法：美谥（文、武、明、昭、宣）、平谥（哀、悼、殇）、恶谥（厉、灵、炀、幽）。如隋炀帝之\"炀\"为恶谥。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh216","item":"古代庙号与谥号之别：庙号是帝王在太庙祭祀的名号（太祖、太宗），谥号是评价性称号（文、武、炀）；唐以前多称谥号，唐以后多称庙号。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh217","item":"古代帝王年号：汉武帝首创\"建元\"，此后新君即位或遇大事常改元。明清皇帝一般一帝一号，故常以年号代称皇帝。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh219","item":"古代年龄别称补充：始龀（七八岁换牙）、幼学（十岁）、金钗之年（女子十二）、碧玉年华（女子十六）、桃李年华（女子二十）、花信年华（女子二十四）。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh221","item":"古代称谓\"丈人\"：古义指对老年男子的尊称，非今之岳父；\"爪牙\"古义指得力助手，非今之贬义。","dynasty":"","cat":"称谓避讳","source":"考纲文化常识扩展","theme":"称谓避讳"},{"id":"wh031","item":"垂髫：指三四岁至七岁（女）、八岁（男）的幼年，因儿童不束发、头发下垂。","dynasty":"","cat":"年龄称谓","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"年龄称谓"},{"id":"wh032","item":"总角：古代儿童把头发分成左右两半、扎成发髻，借指童年。","dynasty":"","cat":"年龄称谓","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"年龄称谓"},{"id":"wh033","item":"豆蔻年华：指女子十三四岁，语出杜牧诗“豆蔻梢头二月初”。","dynasty":"","cat":"年龄称谓","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"年龄称谓"},{"id":"wh034","item":"及笄：指女子十五岁，行笄礼表示成年，可以出嫁。","dynasty":"","cat":"年龄称谓","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"年龄称谓"},{"id":"wh035","item":"弱冠：指男子二十岁，行冠礼表示成年，因还未壮故称“弱”。","dynasty":"","cat":"年龄称谓","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"年龄称谓"},{"id":"wh036","item":"而立之年：指三十岁，语出《论语》“三十而立”。","dynasty":"","cat":"年龄称谓","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"年龄称谓"},{"id":"wh037","item":"不惑之年：指四十岁，语出《论语》“四十而不惑”。","dynasty":"","cat":"年龄称谓","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"年龄称谓"},{"id":"wh038","item":"知天命（知命、半百）：指五十岁，语出《论语》“五十而知天命”。","dynasty":"","cat":"年龄称谓","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"年龄称谓"},{"id":"wh040","item":"古稀之年：指七十岁，语出杜甫诗“人生七十古来稀”。","dynasty":"","cat":"年龄称谓","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"年龄称谓"},{"id":"wh041","item":"耄耋之年：指八九十岁，泛指高龄老人。","dynasty":"","cat":"年龄称谓","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"年龄称谓"},{"id":"wh042","item":"期颐之年：指一百岁，语出《礼记》“百年曰期，颐”。","dynasty":"","cat":"年龄称谓","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"年龄称谓"},{"id":"wh109","item":"年龄称谓补充：襁褓（未满周岁）、孩提（2—3岁）、总角（幼年）、豆蔻（女子十三四岁）、及笄（女子十五）、弱冠（男子二十）、而立（三十）、不惑（四十）、知天命（五十）、花甲（六十）、古稀（七十）、耄耋（八九十）。","dynasty":"","cat":"年龄称谓","source":"文学常识补充（教材通行说法）","theme":"年龄称谓"},{"id":"wh220","item":"古代寿称：喜寿（七十七，草书喜字似七十七）、米寿（八十八，米字拆为八十八）、白寿（九十九，百少一）、茶寿（一百零八，茶字拆为廿加八十八）。","dynasty":"","cat":"年龄称谓","source":"考纲文化常识扩展","theme":"年龄称谓"},{"id":"wh018","item":"童子试（童试）：取得生员（秀才）资格的入学考试，分县试、府试、院试三级。","dynasty":"","cat":"科举官制","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"科举官制"},{"id":"wh019","item":"乡试：明清每三年在省城举行的考试，因在秋天举行又称“秋闱”，考中者称举人，第一名称解元。","dynasty":"","cat":"科举官制","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"科举官制"},{"id":"wh020","item":"会试：乡试次年春天在京城礼部举行，又称“春闱”“礼闱”，考中者称贡士，第一名称会元。","dynasty":"","cat":"科举官制","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"科举官制"},{"id":"wh021","item":"殿试：会试后由皇帝亲自主持的最高一级考试，考中者统称进士；分三甲，一甲三名赐进士及第，依次为状元、榜眼、探花。","dynasty":"","cat":"科举官制","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"科举官制"},{"id":"wh022","item":"连中三元：在乡试、会试、殿试中接连考取第一名（解元、会元、状元），称“连中三元”；乡试、会试、殿试均取第一名（解元、会元、状元），称『连中三元』。","dynasty":"","cat":"科举官制","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"科举官制"},{"id":"wh023","item":"太学与国子监：古代最高学府，汉代称太学，晋以后设国子监。","dynasty":"","cat":"科举官制","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"科举官制"},{"id":"wh024","item":"庠序：古代地方学校的通称，商代称序，周代称庠，后泛指学校。","dynasty":"","cat":"科举官制","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"科举官制"},{"id":"wh103","item":"科举四级：院试（中者为秀才/生员）、乡试（三年一次于省城，中者为举人，第一名称解元）、会试（次年春于京城，中者为贡士，第一名称会元）、殿试（皇帝主持，中者为进士，分三甲，一甲三名依次为状元、榜眼、探花）。","dynasty":"","cat":"科举官制","source":"文学常识补充（教材通行说法）","theme":"科举官制"},{"id":"wh128","item":"四大书院：白鹿洞书院（江西庐山）、岳麓书院（湖南长沙）、嵩阳书院（河南登封）、应天府书院（河南商丘）。","dynasty":"","cat":"科举官制","source":"考纲文化常识扩展","theme":"科举官制"},{"id":"wh129","item":"私塾与蒙学：古代民间教育机构。蒙学读物有《三字经》《百家姓》《千字文》《弟子规》，合称\"三百千\"。","dynasty":"","cat":"科举官制","source":"考纲文化常识扩展","theme":"科举官制"},{"id":"wh130","item":"八股文：明清科举考试规定的文体，由破题、承题、起讲、入手、起股、中股、后股、束股八部分组成，内容须代圣贤立言，格式僵化。","dynasty":"","cat":"科举官制","source":"考纲文化常识扩展","theme":"科举官制"},{"id":"wh176","item":"四书五经与十三经的关系：四书五经为科举核心教材；十三经为儒家经典总汇，含五经及《周礼》《仪礼》《左传》《公羊传》《谷梁传》《论语》《孝经》《尔雅》《孟子》。","dynasty":"","cat":"科举官制","source":"考纲文化常识扩展","theme":"科举官制"},{"id":"wh025","item":"拜、除：拜为授予官职，除为任命、授职。","dynasty":"","cat":"职官制度","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"职官制度"},{"id":"wh026","item":"擢、迁：擢为提拔升官；迁一般指调动或升职，“左迁”则指降职贬官。","dynasty":"","cat":"职官制度","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"职官制度"},{"id":"wh027","item":"谪、贬、黜、罢：谪、贬指因罪被降职外放；黜、罢指罢免官职。","dynasty":"","cat":"职官制度","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"职官制度"},{"id":"wh028","item":"乞骸骨：古代官员自请退职、请求还乡，意为使骸骨归葬故乡。","dynasty":"","cat":"职官制度","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"职官制度"},{"id":"wh029","item":"致仕：古代官员交还官职、即退休。","dynasty":"","cat":"职官制度","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"职官制度"},{"id":"wh030","item":"三省六部：隋唐中央官制，三省指中书省、门下省、尚书省，尚书省下统吏、户、礼、兵、刑、工六部；隋唐中央官制。三省为中书省（决策）、门下省（审议）、尚书省（执行）；尚书省下辖吏、户、礼、兵、刑、工六部。","dynasty":"","cat":"职官制度","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"职官制度"},{"id":"wh105","item":"官职变迁词：拜（授官）、除（任命）、擢（提拔）、迁（调动，左迁为降职）、谪（因罪降职外放）、黜（罢免）、罢（免官）、乞骸骨（官员自请退休）、致仕（交还官职即退休）。","dynasty":"","cat":"职官制度","source":"文学常识补充（教材通行说法）","theme":"职官制度"},{"id":"wh001","item":"古人姓、氏、名、字、号有别：男子二十岁行冠礼取字，女子十五岁行笄礼取字；“号”为自取或别人所起的美称、别号，如苏轼号东坡居士。","dynasty":"","cat":"礼制婚丧","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"礼制婚丧"},{"id":"wh056","item":"顿首、稽首：古代九拜礼节，稽首为屈膝跪地、叩头至地最恭敬之礼；顿首为叩头即起，常用于书信首尾表敬。","dynasty":"","cat":"礼制婚丧","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"礼制婚丧"},{"id":"wh057","item":"社稷：社为土神，稷为谷神，古代帝王诸侯所祭，后用作国家的代称。","dynasty":"","cat":"礼制婚丧","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"礼制婚丧"},{"id":"wh064","item":"太牢、少牢：古代祭祀所用牺牲，牛、羊、猪三牲全备称太牢，只用羊、猪称少牢。","dynasty":"","cat":"礼制婚丧","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"礼制婚丧"},{"id":"wh112","item":"婚嫁六礼：纳采、问名、纳吉、纳征、请期、亲迎，古代婚姻成立的六道程序。","dynasty":"","cat":"礼制婚丧","source":"文学常识补充（教材通行说法）","theme":"礼制婚丧"},{"id":"wh150","item":"五服：古代丧服按亲疏分斩衰、齐衰、大功、小功、缌麻五等，服制越重表示亲属关系越近。","dynasty":"","cat":"礼制婚丧","source":"考纲文化常识扩展","theme":"礼制婚丧"},{"id":"wh151","item":"七出三不去：古代休妻的七种理由（不顺父母、无子、淫、妒、有恶疾、口多言、窃盗）；三种情况不得休妻（有所取无所归、与更三年丧、前贫贱后富贵）。","dynasty":"","cat":"礼制婚丧","source":"考纲文化常识扩展","theme":"礼制婚丧"},{"id":"wh172","item":"五礼：古代礼制的五类——吉礼（祭祀）、凶礼（丧葬）、军礼（征伐）、宾礼（朝聘）、嘉礼（婚冠宴饮）。","dynasty":"","cat":"礼制婚丧","source":"考纲文化常识扩展","theme":"礼制婚丧"},{"id":"wh173","item":"九拜：古代九种跪拜礼，以稽首（叩头至地）最重，顿首（叩头即起）次之，空首、振动、吉拜、凶拜、奇拜、褒拜、肃拜各有等差。","dynasty":"","cat":"礼制婚丧","source":"考纲文化常识扩展","theme":"礼制婚丧"},{"id":"wh174","item":"冠礼与笄礼：男子二十行冠礼（三加冠），女子十五行笄礼（结发加笄），表示成年。","dynasty":"","cat":"礼制婚丧","source":"考纲文化常识扩展","theme":"礼制婚丧"},{"id":"wh197","item":"古代婚姻称谓：结发（原配）、糟糠（共患难的妻子）、续弦（再娶）、填房、侧室、如夫人。","dynasty":"","cat":"礼制婚丧","source":"考纲文化常识扩展","theme":"礼制婚丧"},{"id":"wh043","item":"三纲五常：汉代董仲舒提出的封建伦理，三纲指君为臣纲、父为子纲、夫为妻纲；五常指仁、义、礼、智、信。","dynasty":"","cat":"宗法家族","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"宗法家族"},{"id":"wh044","item":"六亲九族：泛指亲属；九族通常指高祖、曾祖、祖、父、己身、子、孙、曾孙、玄孙九代。","dynasty":"","cat":"宗法家族","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"宗法家族"},{"id":"wh152","item":"宗法制：以血缘关系为纽带的嫡长子继承制，核心是嫡长子继承、别子分封、昭穆有序、大宗小宗相统。","dynasty":"","cat":"宗法家族","source":"考纲文化常识扩展","theme":"宗法家族"},{"id":"wh153","item":"昭穆：古代宗庙次序，始祖居中，以下父为昭、子为穆，左昭右穆，用以区别辈分。","dynasty":"","cat":"宗法家族","source":"考纲文化常识扩展","theme":"宗法家族"},{"id":"wh154","item":"姓氏来源：姓起源于母系氏族（姬、姜、姒、嬴皆有女旁），氏为姓的分支，秦汉后姓氏合一。","dynasty":"","cat":"宗法家族","source":"考纲文化常识扩展","theme":"宗法家族"},{"id":"wh045","item":"阴阳：古代哲学概念，指事物相互对立消长的两个方面；又地名中水北山南为阳，水南山北为阴，如“华阴”“衡阳”。","dynasty":"","cat":"地理方位","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"地理方位"},{"id":"wh050","item":"五岳：五大名山的总称——东岳泰山、西岳华山、南岳衡山、北岳恒山、中岳嵩山。","dynasty":"","cat":"地理方位","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"地理方位"},{"id":"wh051","item":"九州：古代中国的行政区划，后为中国的代称，一般指冀、兖、青、徐、扬、荆、豫、梁、雍九州。","dynasty":"","cat":"地理方位","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"地理方位"},{"id":"wh053","item":"山高水北为阳：古地名中，山的南面、水的北岸为“阳”，山的北面、水的南岸为“阴”（如洛阳在洛水之北，江阴在长江之南）。","dynasty":"","cat":"地理方位","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"地理方位"},{"id":"wh054","item":"江东（江表）：古地区名，指长江下游以南的江南地区，又称江左。","dynasty":"","cat":"地理方位","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"地理方位"},{"id":"wh055","item":"关中：古地区名，指函谷关（一说潼关）以西的今陕西渭河流域一带。","dynasty":"","cat":"地理方位","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"地理方位"},{"id":"wh107","item":"地理方位：山南水北为阳，山北水南为阴（如洛阳在洛水之北，江阴在长江之南，华阴在华山之北）。","dynasty":"","cat":"地理方位","source":"文学常识补充（教材通行说法）","theme":"地理方位"},{"id":"wh108","item":"古地名：江左（江东，长江下游以南）、江表（长江以南）、关中（函谷关以西）、山东（崤山以东）、江南、中原、塞北、西域。","dynasty":"","cat":"地理方位","source":"文学常识补充（教材通行说法）","theme":"地理方位"},{"id":"wh209","item":"古代地理方位别称：东为左、西为右（\"江左\"即江东）；南为阳、北为阴；山南水北为阳。","dynasty":"","cat":"地理方位","source":"考纲文化常识扩展","theme":"地理方位"},{"id":"wh210","item":"古代行政区划：秦行郡县制，汉为州郡县，唐为道州县，宋为路州县，元为行省，明清为省府县。","dynasty":"","cat":"地理方位","source":"考纲文化常识扩展","theme":"地理方位"},{"id":"wh048","item":"四书五经：儒家经典。“四书”指《大学》《中庸》《论语》《孟子》；“五经”指《诗》《书》《礼》《易》《春秋》《论语》《大学》《孟子》《中庸》；《诗》《书》《礼》《易》《春秋》","dynasty":"","cat":"经史子集","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"经史子集"},{"id":"wh049","item":"三教九流：“三教”指儒、释（佛）、道；“九流”原指先秦九个学术流派，后泛指江湖各种行业人物。","dynasty":"","cat":"经史子集","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"经史子集"},{"id":"wh094","item":"四书：《大学》《中庸》《论语》《孟子》。五经：《诗》《书》《礼》《易》《春秋》。","dynasty":"","cat":"经史子集","source":"文学常识补充（教材通行说法）","theme":"经史子集"},{"id":"wh131","item":"十三经：儒家十三部经典——《周易》《尚书》《诗经》《周礼》《仪礼》《礼记》《春秋左传》《春秋公羊传》《春秋谷梁传》《论语》《孝经》《尔雅》《孟子》。","dynasty":"","cat":"经史子集","source":"考纲文化常识扩展","theme":"经史子集"},{"id":"wh132","item":"十三经注疏：十三经的权威注本，由汉代至宋代学者注疏汇编而成，是研读经书的门径。","dynasty":"","cat":"经史子集","source":"考纲文化常识扩展","theme":"经史子集"},{"id":"wh133","item":"经史子集：古代图书四部分类法。经为儒家经典，史为史书，子为诸子百家及科技著作，集为诗文别集总集。","dynasty":"","cat":"经史子集","source":"考纲文化常识扩展","theme":"经史子集"},{"id":"wh134","item":"《四库全书》：清代乾隆年间编纂的最大丛书，分经史子集四部，纪昀（纪晓岚）任总纂官。","dynasty":"","cat":"经史子集","source":"考纲文化常识扩展","theme":"经史子集"},{"id":"wh135","item":"类书：按类辑录资料的书籍，如《太平御览》《永乐大典》（明解缙等编，古代最大类书）《古今图书集成》。","dynasty":"","cat":"经史子集","source":"考纲文化常识扩展","theme":"经史子集"},{"id":"wh136","item":"丛书：汇刻多种书籍的出版物，如《四库全书》《四部丛刊》《知不足斋丛书》。","dynasty":"","cat":"经史子集","source":"考纲文化常识扩展","theme":"经史子集"},{"id":"wh175","item":"六艺：古代教育内容——礼、乐、射、御、书、数。","dynasty":"","cat":"经史子集","source":"考纲文化常识扩展","theme":"经史子集"},{"id":"wh070","item":"平仄：平声为『平』，上、去、入三声为『仄』。近体诗讲究平仄相间与相对，形成格律。","dynasty":"","cat":"文体知识","source":"文学常识补充（教材通行说法）","theme":"文体知识"},{"id":"wh074","item":"曲：元代兴起，分散曲（小令、套数）与杂剧。元杂剧一般一本四折，可加楔子，由曲词、宾白、科介组成，一角主唱。","dynasty":"","cat":"文体知识","source":"文学常识补充（教材通行说法）","theme":"文体知识"},{"id":"wh082","item":"王孟与高岑：王维、孟浩然为盛唐山水田园诗派代表；高适、岑参为盛唐边塞诗派代表。","dynasty":"","cat":"文体知识","source":"文学常识补充（教材通行说法）","theme":"文体知识"},{"id":"wh084","item":"苏辛与婉约：苏轼、辛弃疾为豪放词代表，并称『苏辛』；柳永、李清照为婉约词代表。","dynasty":"","cat":"文体知识","source":"文学常识补充（教材通行说法）","theme":"文体知识"},{"id":"wh086","item":"四大名著：《三国演义》（罗贯中）《水浒传》（施耐庵）《西游记》（吴承恩）《红楼梦》（曹雪芹）。","dynasty":"","cat":"文体知识","source":"文学常识补充（教材通行说法）","theme":"文体知识"},{"id":"wh089","item":"临川四梦（玉茗堂四梦）：汤显祖《牡丹亭》《紫钗记》《南柯记》《邯郸记》，因汤显祖为江西临川人得名。","dynasty":"","cat":"文体知识","source":"文学常识补充（教材通行说法）","theme":"文体知识"},{"id":"wh090","item":"四大奇书：《三国演义》《水浒传》《西游记》《金瓶梅》，明代四大长篇小说；《水浒传》是一部怒书，《西游记》是一部悟书，《金瓶梅》是一部哀书。","dynasty":"","cat":"文体知识","source":"文学常识补充（教材通行说法）","theme":"文体知识"},{"id":"wh091","item":"前四史：司马迁《史记》、班固《汉书》、范晔《后汉书》、陈寿《三国志》。","dynasty":"","cat":"文体知识","source":"文学常识补充（教材通行说法）","theme":"文体知识"},{"id":"wh092","item":"春秋三传：《左传》《公羊传》《谷梁传》，均为阐释《春秋》之作。","dynasty":"","cat":"文体知识","source":"文学常识补充（教材通行说法）","theme":"文体知识"},{"id":"wh093","item":"诗经六义：风、雅、颂（内容分类）与赋、比、兴（表现手法）。","dynasty":"","cat":"文体知识","source":"文学常识补充（教材通行说法）","theme":"文体知识"},{"id":"wh095","item":"文体辨识：记（记事写景，如《岳阳楼记》）、序（赠序或书序，如《送东阳马生序》）、说（议论说明，如《师说》）、论（议论，如《六国论》）、表（臣下向君陈情，如《出师表》）、疏（分条陈事，如《谏逐客书》）、书（书信，如《报任安书》）、铭（刻石记功或自警，如《陋室铭》）、祭文（祭奠亲友）。","dynasty":"","cat":"文体知识","source":"文学常识补充（教材通行说法）","theme":"文体知识"},{"id":"wh098","item":"书法名家：王羲之（书圣，《兰亭序》为『天下第一行书』）、王献之、欧阳询、颜真卿、柳公权（楷书四大家：欧颜柳赵）、张旭与怀素（草书）、苏轼、黄庭坚、米芾、蔡襄（宋四家）。","dynasty":"","cat":"文体知识","source":"文学常识补充（教材通行说法）","theme":"文体知识"},{"id":"wh137","item":"简牍帛书：纸普及前的书写材料。竹片为简，木片为牍，丝织品为帛书。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh138","item":"雕版印刷与活字印刷：雕版始于唐代，现存最早印刷品为唐咸通九年《金刚经》；北宋毕昇发明活字印刷。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh140","item":"《周髀算经》：我国现存最早的数学著作，记载勾股定理。祖冲之将圆周率精确到小数点后七位。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh141","item":"中医四大经典：《黄帝内经》（最早的医学理论著作）《难经》《伤寒杂病论》（张仲景）《神农本草经》。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh146","item":"《梦溪笔谈》：北宋沈括著，记载科技成就的笔记体著作，被誉为\"中国科学史上的坐标\"。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh147","item":"《徐霞客游记》：明代徐弘祖著，我国古代地理学名著，兼有文学价值。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh157","item":"古代文体之\"铭\"：刻在器物或石碑上用以称功德或自警的文体，如刘禹锡《陋室铭》。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh158","item":"古代文体之\"说\"：用以陈述对某问题的见解，属议论文，如韩愈《马说》《师说》、周敦颐《爱莲说》。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh159","item":"古代文体之\"记\"：以记叙为主，兼及议论抒情，多记亭台楼阁、山水景物，如《岳阳楼记》《醉翁亭记》《小石潭记》。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh160","item":"古代文体之\"序\"：一为书序（写在著作前），一为赠序（临别赠言），如《送东阳马生序》为赠序。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh161","item":"古代文体之\"疏\"：臣下向君主分条陈述意见的奏章，如贾谊《论积贮疏》、魏征《谏太宗十思疏》。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh162","item":"古代文体之\"表\"：臣下向君主陈述请求、陈情言事的文书，如诸葛亮《出师表》、李密《陈情表》。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh163","item":"古代文体之\"赋\"：讲究铺陈排比、辞采华美的文体，介于诗文之间。有骚赋、大赋、小赋、骈赋、律赋、文赋之别。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh164","item":"古代文体之\"论\"：以议论说理为主的文体，如贾谊《过秦论》、苏洵《六国论》、柳宗元《封建论》。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh165","item":"古代文体之\"传\"：记述人物生平事迹的文体，如《史记》列传、《张中丞传后叙》。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh166","item":"古代文体之\"祭文\"：祭奠死者时诵读的文章，如韩愈《祭十二郎文》、袁枚《祭妹文》。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh167","item":"古代文体之\"诔\"与\"哀辞\"：诔为叙死者德行以示哀悼，哀辞多为哀悼幼丧或不幸早亡者。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh168","item":"古代文体之\"箴\"与\"规\"：箴为劝诫规谏之文，规为规劝之文，皆用于警诫。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh169","item":"古代文体之\"檄\"：古代官府用以征召、晓谕或声讨的文书，如骆宾王《讨武曌檄》。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh170","item":"古代文体之\"诏令\"：帝王下达的文书，包括诏、制、诰、敕、谕、旨等。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh171","item":"古代文体之\"碑志\"：碑文刻于石上记功述德；墓志铭埋于墓中，记死者姓名家世生平，如韩愈《柳子厚墓志铭》。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh178","item":"佛教中国化：佛教西汉末传入，唐代形成天台宗、华严宗、禅宗等中国化宗派，禅宗六祖为慧能。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh179","item":"三教合一：儒、释、道三家在长期发展中相互吸收融合，是中国传统文化的基本格局。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh189","item":"古代法律：《法经》（李悝，我国第一部较系统的成文法典）《秦律》《唐律疏议》（现存最早最完整的封建法典）《大明律》《大清律例》。","dynasty":"","cat":"文体知识","source":"考纲文化常识扩展","theme":"文体知识"},{"id":"wh078","item":"唐宋八大家：唐代韩愈、柳宗元，宋代欧阳修、苏洵、苏轼、苏辙、王安石、曾巩八位散文家；唐代韩愈、柳宗元，宋代欧阳修、苏洵、苏轼、苏辙、王安石、曾巩八位散文家的合称；唐代；韩愈、柳宗元；宋代；欧阳修、苏洵、苏轼、苏辙、王安石、曾巩；唐宋八大家之首（韩愈）；宋代之首：欧阳修；临川文学代表人物（王安石，曾巩）","dynasty":"宋","cat":"文学流派","source":"文学常识补充（教材通行说法）","theme":"文学流派"},{"id":"wh083","item":"李杜与小李杜：李白（诗仙）、杜甫（诗圣）并称『李杜』；李商隐、杜牧并称『小李杜』。","dynasty":"","cat":"文学流派","source":"文学常识补充（教材通行说法）","theme":"文学流派"},{"id":"wh085","item":"元曲四大家：关汉卿、马致远、郑光祖、白朴。元杂剧四大悲剧：《窦娥冤》《汉宫秋》《梧桐雨》《赵氏孤儿》元代关汉卿、白朴、马致远、郑光祖四位杂剧作家的并称；元曲四大家：关马郑白","dynasty":"元","cat":"文学流派","source":"文学常识补充（教材通行说法）","theme":"文学流派"},{"id":"wh088","item":"三言二拍：冯梦龙编《喻世明言》《警世通言》《醒世恒言》合称『三言』；凌濛初著《初刻拍案惊奇》《二刻拍案惊奇》合称『二拍』。","dynasty":"","cat":"文学流派","source":"文学常识补充（教材通行说法）","theme":"文学流派"},{"id":"wh100","item":"扬州八怪：清代乾隆年间扬州画派，金农、郑燮（板桥）、黄慎、李鱓、李方膺、汪士慎、高翔、罗聘，画风不拘一格。","dynasty":"","cat":"文学流派","source":"文学常识补充（教材通行说法）","theme":"文学流派"},{"id":"wh177","item":"道家与道教之别：道家是先秦哲学流派（老子、庄子），道教是东汉形成的宗教（张道陵五斗米道）。","dynasty":"","cat":"文学流派","source":"考纲文化常识扩展","theme":"文学流派"},{"id":"wh061","item":"文房四宝：对笔、墨、纸、砚四种文具的统称。","dynasty":"","cat":"书画艺术","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"书画艺术"},{"id":"wh062","item":"花中四君子：对梅、兰、竹、菊四种花木的美称，常喻高洁品格。","dynasty":"","cat":"书画艺术","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"书画艺术"},{"id":"wh063","item":"岁寒三友：指松、竹、梅，经冬不凋，象征坚贞品格。","dynasty":"","cat":"书画艺术","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"书画艺术"},{"id":"wh102","item":"三大石窟：敦煌莫高窟（甘肃）、云冈石窟（山西大同）、龙门石窟（河南洛阳）。","dynasty":"","cat":"书画艺术","source":"文学常识补充（教材通行说法）","theme":"书画艺术"},{"id":"wh180","item":"四大名楼：黄鹤楼（武汉）、岳阳楼（岳阳）、滕王阁（南昌）、鹳雀楼（永济）。","dynasty":"","cat":"书画艺术","source":"考纲文化常识扩展","theme":"书画艺术"},{"id":"wh181","item":"四大名亭：醉翁亭（滁州）、陶然亭（北京）、爱晚亭（长沙）、湖心亭（杭州）。","dynasty":"","cat":"书画艺术","source":"考纲文化常识扩展","theme":"书画艺术"},{"id":"wh182","item":"江南三大名楼：黄鹤楼、岳阳楼、滕王阁；滕王阁、岳阳楼、黄鹤楼","dynasty":"","cat":"书画艺术","source":"考纲文化常识扩展","theme":"书画艺术"},{"id":"wh183","item":"古代建筑构件：斗拱（承重装饰）、飞檐、藻井、影壁、月洞门、须弥座。","dynasty":"","cat":"书画艺术","source":"考纲文化常识扩展","theme":"书画艺术"},{"id":"wh184","item":"古代服饰：冕（帝王礼帽）、冠（贵族男子首服）、帻（平民头巾）、深衣（上下连体）、袍、襦裙、履、屐。","dynasty":"","cat":"书画艺术","source":"考纲文化常识扩展","theme":"书画艺术"},{"id":"wh185","item":"衣冠禽兽本义：明代文官绣禽、武官绣兽于补服，本指官员服饰，后转贬义。","dynasty":"","cat":"书画艺术","source":"考纲文化常识扩展","theme":"书画艺术"},{"id":"wh059","item":"五谷：古代对粮食作物的统称，通常指稻、黍、稷、麦、菽。","dynasty":"","cat":"音乐名物","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"音乐名物"},{"id":"wh060","item":"五音：中国五声音阶，即宫、商、角、徵、羽。","dynasty":"","cat":"音乐名物","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"音乐名物"},{"id":"wh114","item":"四大发明：造纸术（蔡伦改进）、印刷术（毕昇活字）、火药、指南针，中国古代对世界文明的重大贡献。","dynasty":"","cat":"音乐名物","source":"文学常识补充（教材通行说法）","theme":"音乐名物"},{"id":"wh115","item":"古代名物：鼎（三足两耳，国之重器，『问鼎』喻图谋王位）、钟（编钟，礼乐器）、簋（食器）、戈矛戟（兵器）、圭臬（测日影器，喻准则）。","dynasty":"","cat":"音乐名物","source":"文学常识补充（教材通行说法）","theme":"音乐名物"},{"id":"wh126","item":"十二律吕：古代音乐十二个半音，分六律（阳律：黄钟、太簇、姑洗、蕤宾、夷则、无射）与六吕（阴律），合称十二律。","dynasty":"","cat":"音乐名物","source":"考纲文化常识扩展","theme":"音乐名物"},{"id":"wh127","item":"八音：古代按材质分乐器为八类——金（钟）、石（磬）、丝（琴瑟）、竹（箫笛）、匏（笙）、土（埙）、革（鼓）、木（柷敔）。","dynasty":"","cat":"音乐名物","source":"考纲文化常识扩展","theme":"音乐名物"},{"id":"wh148","item":"度量衡：度指长度，量指容积，衡指重量。古代长度单位有寸、尺、丈、仞、寻；容量有合、升、斗、斛；重量有铢、两、斤、钧、石。","dynasty":"","cat":"音乐名物","source":"考纲文化常识扩展","theme":"音乐名物"},{"id":"wh149","item":"古代货币：先秦有布币、刀币、圜钱、蚁鼻钱；秦统一为半两钱；汉有五铢钱；唐以后通宝钱；宋出现纸币\"交子\"。","dynasty":"","cat":"音乐名物","source":"考纲文化常识扩展","theme":"音乐名物"},{"id":"wh186","item":"古代车马：一车四马为一乘，车厢为舆，车前横木为轼，御者居中。天子万乘、诸侯千乘。","dynasty":"","cat":"音乐名物","source":"考纲文化常识扩展","theme":"音乐名物"},{"id":"wh218","item":"古代度量\"里\"：一里约合今415米（周制300步为一里），\"千里\"常为夸张之辞。","dynasty":"","cat":"音乐名物","source":"考纲文化常识扩展","theme":"音乐名物"},{"id":"wh096","item":"二十八宿：古人沿黄道赤道附近划分的二十八个星区，分东南西北四象——东方苍龙、西方白虎、南方朱雀、北方玄武，各七宿。","dynasty":"","cat":"科技典籍","source":"文学常识补充（教材通行说法）","theme":"科技典籍"},{"id":"wh097","item":"四象：青龙（东）、白虎（西）、朱雀（南）、玄武（北），源于二十八宿的方位划分。","dynasty":"","cat":"科技典籍","source":"文学常识补充（教材通行说法）","theme":"科技典籍"},{"id":"wh139","item":"《九章算术》：中国古代数学名著，系统总结了先秦至汉代的数学成就，标志中国古代数学体系形成。","dynasty":"","cat":"科技典籍","source":"考纲文化常识扩展","theme":"科技典籍"},{"id":"wh142","item":"古代名医：扁鹊（战国，脉学奠基）、华佗（东汉，麻沸散、五禽戏）、张仲景（医圣）、孙思邈（药王，《千金方》）、李时珍（《本草纲目》）。","dynasty":"","cat":"科技典籍","source":"考纲文化常识扩展","theme":"科技典籍"},{"id":"wh143","item":"《水经注》：北魏郦道元著，我国古代最系统的综合性地理著作，兼具文学价值。","dynasty":"","cat":"科技典籍","source":"考纲文化常识扩展","theme":"科技典籍"},{"id":"wh144","item":"《天工开物》：明代宋应星著，总结农业与手工业技术的百科全书式著作。","dynasty":"","cat":"科技典籍","source":"考纲文化常识扩展","theme":"科技典籍"},{"id":"wh145","item":"《齐民要术》：北魏贾思勰著，我国现存最早的完整农书。","dynasty":"","cat":"科技典籍","source":"考纲文化常识扩展","theme":"科技典籍"},{"id":"wh187","item":"古代兵书：《孙子兵法》（孙武，十三篇，现存最早兵书）《孙膑兵法》《吴子》《六韬》《尉缭子》《司马法》《三略》《唐太宗李卫公问对》，合称武经七书。","dynasty":"","cat":"科技典籍","source":"考纲文化常识扩展","theme":"科技典籍"},{"id":"wh188","item":"三十六计：古代兵家谋略总结，分胜战计、敌战计、攻战计、混战计、并战计、败战计六套。","dynasty":"","cat":"科技典籍","source":"考纲文化常识扩展","theme":"科技典籍"},{"id":"wh190","item":"五刑：古代五种刑罚。早期为墨（刺面）、劓（割鼻）、剕（断足）、宫、大辟（死刑）；隋唐后为笞、杖、徒、流、死。","dynasty":"","cat":"科技典籍","source":"考纲文化常识扩展","theme":"科技典籍"},{"id":"wh201","item":"古代科学著作《墨经》：墨子及后学所著，含光学（小孔成像）、力学、几何学内容，是中国古代科学的重要文献。","dynasty":"","cat":"科技典籍","source":"考纲文化常识扩展","theme":"科技典籍"},{"id":"wh202","item":"《营造法式》：北宋李诫编，我国古代最完整的建筑技术典籍。","dynasty":"","cat":"科技典籍","source":"考纲文化常识扩展","theme":"科技典籍"},{"id":"wh203","item":"《本草纲目》：明代李时珍著，收药1892种，被誉为\"东方药物巨典\"。","dynasty":"","cat":"科技典籍","source":"考纲文化常识扩展","theme":"科技典籍"},{"id":"wh204","item":"《农政全书》：明代徐光启著，集古代农学之大成。","dynasty":"","cat":"科技典籍","source":"考纲文化常识扩展","theme":"科技典籍"},{"id":"wh205","item":"《海国图志》：清代魏源编，提出\"师夷长技以制夷\"，开近代向西方学习之风。","dynasty":"","cat":"科技典籍","source":"考纲文化常识扩展","theme":"科技典籍"},{"id":"wh046","item":"五行：古代指金、木、水、火、土五种物质，认为它们相生相克，构成世界。","dynasty":"","cat":"宗教哲学","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"宗教哲学"},{"id":"wh047","item":"八卦：《周易》中的八种基本符号，即乾、坤、震、巽、坎、离、艮、兑，分别象征天、地、雷、风、水、火、山、泽。","dynasty":"","cat":"宗教哲学","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"宗教哲学"},{"id":"wh192","item":"古代称谓\"令\"族：令尊、令堂、令郎、令爱、令兄、令弟，皆为敬称对方亲属。","dynasty":"","cat":"谦敬辞令","source":"考纲文化常识扩展","theme":"谦敬辞令"},{"id":"wh193","item":"\"家\"族与\"舍\"族：家父、家母、家兄为谦称自家长辈或同辈年长者；舍弟、舍妹为谦称自家弟妹。","dynasty":"","cat":"谦敬辞令","source":"考纲文化常识扩展","theme":"谦敬辞令"},{"id":"wh199","item":"杏林与杏坛之别：杏林指医界（董奉治病不取钱、令人种杏），杏坛指教育界（孔子讲学处）。","dynasty":"","cat":"谦敬辞令","source":"考纲文化常识扩展","theme":"谦敬辞令"},{"id":"wh058","item":"布衣、黔首：古代平民的代称。“布衣”指平民穿麻葛之衣；“黔首”指秦代百姓，因以黑巾裹头。","dynasty":"","cat":"其他","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"其他"},{"id":"wh065","item":"敕、诏、诰：古代帝王的文书命令，皇帝发布的命令文告称诏、敕、诰。","dynasty":"","cat":"其他","source":"http://ling.cass.cn/ziyuan/ywtd/ywmt/202511/t20251121_5950889.html","theme":"其他"},{"id":"wh068","item":"六书：汉字造字与用字的六种方法——象形、指事、会意、形声、转注、假借。前四种为造字法，后两种为用字法。","dynasty":"","cat":"其他","source":"文学常识补充（教材通行说法）","theme":"其他"},{"id":"wh069","item":"四声：古汉语平、上、去、入四种声调。现代普通话为阴平、阳平、上声、去声，入声已消失，分别派入四声。","dynasty":"","cat":"其他","source":"文学常识补充（教材通行说法）","theme":"其他"},{"id":"wh101","item":"四大佛教名山：五台山（文殊，山西）、峨眉山（普贤，四川）、普陀山（观音，浙江）、九华山（地藏，安徽）。道教四大名山：武当山、龙虎山、齐云山、青城山。","dynasty":"","cat":"其他","source":"文学常识补充（教材通行说法）","theme":"其他"},{"id":"wh125","item":"干支与生肖：子鼠、丑牛、寅虎、卯兔、辰龙、巳蛇、午马、未羊、申猴、酉鸡、戌狗、亥猪。","dynasty":"","cat":"其他","source":"考纲文化常识扩展","theme":"其他"},{"id":"wh156","item":"八拜之交：指管鲍之交、知音之交（伯牙子期）、刎颈之交（廉颇蔺相如）、舍命之交（羊角哀左伯桃）、胶漆之交（陈重雷义）、鸡黍之交（范式张劭）、忘年之交（孔融祢衡）、生死之交（刘备关羽张飞）。","dynasty":"","cat":"其他","source":"考纲文化常识扩展","theme":"其他"},{"id":"wh211","item":"古代军事编制：五人为伍，五伍为两，四两为卒，五卒为旅，五旅为师，五师为军（周制）。","dynasty":"","cat":"其他","source":"考纲文化常识扩展","theme":"其他"},{"id":"wh222","item":"大学","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh224","item":"中庸","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh225","item":"《梁惠王》：《齐桓晋文之事章》；本文选自《孟子·梁惠王上》；这是孟子晚年第二次到齐国任客卿时，劝说齐宣王弃霸图王的一篇谈话记录，比较全面具体地阐述了他的“仁政”学说。","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh226","item":"《公孙丑》","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh227","item":"《滕文公》","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh228","item":"《离娄》","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh229","item":"《万章》","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh230","item":"《告子》","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh231","item":"《尽心》","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh233","item":"文学价值：论辩艺术；善用比喻和寓言；精练简约、深入浅出的语言风格","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh234","item":"风——160：十五国风即指十五个地区的地方土乐。：即音乐曲调","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh235","item":"农事诗：《七月》；是风诗中最长的一篇，其最伟大的价值是史料价值，研究古代农业发展状况、古代气候的学者都必须参考。艺术上，也受到很多的称誉；清代崔述：“读《七月》，如入桃源之中，衣冠朴古，天真烂漫，熙熙乎太古也”。","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh236","item":"怨刺诗：《魏风·硕鼠》；《邶风·新台》","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh237","item":"婚恋诗：朱熹不喜欢；“《郑》、《卫》之乐，皆为淫声”，而“《郑》声之淫，有甚于《卫》。”——《诗集传》卷四；最能反映社会问题的是弃妇诗；《卫风·氓》","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh238","item":"雅——105：指朝廷正乐：大雅；国君；小雅；贵族","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh239","item":"战争徭役诗：这类诗大概有30首；《小雅·采薇》","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh240","item":"燕飨诗：《小雅·鹿鸣》","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh241","item":"颂——40：周颂；《生民》；《公刘》；《绵》；《皇矣》；《大明》；鲁颂；商颂","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh242","item":"写作手法：普遍采用“赋”、“比”、“兴”的艺术手法；“诗经六义”：“风”、“雅”、“颂”“赋”、“比”、“兴”。","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh243","item":"体裁：《诗经》以四言诗为主，间有杂言；重章叠句的章法特征；语言特色：朴素简洁，精练准确，绘声绘色","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh245","item":"采诗：班固《汉书·食货志》；何休《春秋公羊传解诂》","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh246","item":"献诗：《国语·召公谏弭谤》；我们学过的课文啊....；“故天子听政，使公卿至于列士献诗，瞽献曲，史献书，师箴，瞍赋，矇诵”","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh247","item":"删诗：《史记·孔子世家》（不考了....）；“古者《诗》三千余篇，及至孔子，去其重，取可施于礼义……三百五篇，孔子皆弦歌之，以求合韶武雅颂之音”。","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh248","item":"四家诗：《诗经》以其口耳相传、易于记诵的特点，得以保存，在汉代流传甚广，出现了今文的鲁、齐、韩三家诗；三家诗在西汉被立为博士，成为官学；鲁诗出自鲁人申培，齐诗出自齐人辕固，韩诗出自燕人韩婴，三家诗兴盛一时；鲁人毛亨和赵人毛苌的古文“毛诗”晚出，在西汉虽未被立为学官，但在民间广泛传授，并最终压倒了三家诗，盛行于世；后来三家诗先后亡佚，今本《诗经》，就是“毛诗”。","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh249","item":"自汉以下，主要用于经学","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh250","item":"汉学重“美、刺”：诗经是汉、唐经学研究的主流；典型著作；《诗大序》总论《诗经》，认为诗歌反映政治；“治世之音安以乐，其政和；乱世之音怨以怒，其政乖；亡国之音哀以思，其民困。”；《毛诗序》；《毛诗郑笺》；《毛诗正义》","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh251","item":"宋学重“义理”：是宋、元、明经学研究的主流；宋学不满汉学只讲美刺；集中批判《毛诗序》；代表性的是朱熹的《诗集传》；宋学以理说《诗》，主性情、主义理；“凡诗之言，善者可以感发人之善心，恶者可以惩创人之逸志，其用归于使人得其性情之正而已。”（《四书集注》）；宋学的功劳；指出了《诗经》中存在着大量的与“美刺”无关的民间歌谣。","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh252","item":"清代“朴学”重“考据”：宗汉攻宋；发扬汉代“汉学”重视考据的朴实学风，认真地做音韵、文字和词义的工作；清代朴学的贡献；专心的考据，对于《诗经》训诂，贡献良多；弊端；只敢拿《诗经》做往古的学问；不敢拿《诗经》作当世的鞭策；背离了复兴“汉学”“引古筹今”，用之于“国家治乱之原，生民根本之计”的初衷。（顾炎武）","dynasty":"清","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh254","item":"《春秋》是我国现存的第一部编年体断代简史：是后世编年体史书之祖；是继《尚书》之后以记事为主的一部史书；发生在鲁国和王朝及其他诸侯中的重大历史事件；•“春秋”本是周王朝和各诸侯国史书的通称；其所以名为“春秋”，是取春秋代序为一年的意思，后来就成为纪年史的专名。","dynasty":"春秋","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh255","item":"遗失一经-乐","dynasty":"","cat":"四书五经","source":"幕布笔记整理","theme":"四书五经"},{"id":"wh256","item":"祖籍--宋国栗邑","dynasty":"春秋","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh257","item":"修六经：《诗》《书》《礼》《易》《春秋》；春秋扩展；春秋三传；公阳传；谷梁传；左传；对春秋进行解释的编年体史书；第一部最富文采标志我國古代叙事散文成熟","dynasty":"春秋","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh258","item":"弟子三千，贤人七十二","dynasty":"春秋","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh259","item":"五十岁担任鲁国司寇","dynasty":"春秋","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh260","item":"孔子-春秋：代表作：论语-语录体散文；季氏將伐顓臾-以驳论为主；驳斥论点","dynasty":"春秋","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh261","item":"孟子-战国：成就：亚圣-元朝","dynasty":"战国","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh262","item":"理念：民贵君轻，宣扬仁政","dynasty":"战国","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh263","item":"《孟子》七篇：主要记录了孟子的谈话","dynasty":"战国","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh264","item":"孟子和其弟子共同所著","dynasty":"战国","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh265","item":"七篇：每篇又各分上、下；《梁惠王》；《公孙丑》；《滕文公》；《离娄》；《万章》；《告子》；《尽心》","dynasty":"战国","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh266","item":"荀子-战国末期：性恶论","dynasty":"战国","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh267","item":"朱熹-北宋：编纂四书；大学；中庸；论语；孟子","dynasty":"北宋","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh269","item":"老子的社会政治观集中体现为-无为而治：提出“小国寡民”的主张","dynasty":"","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh270","item":"《老子韩非列传》：司马迁《史记》卷六十三","dynasty":"","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh274","item":"《史记·老子韩非列传》：汪洋恣肆，奇诡谲怪，自由洒脱的语言风格。","dynasty":"","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh275","item":"法家：代表人物；商鞅；商君书；韩非子-战国末期；《韩非子》；李斯；《谏逐客书》战国以韩非为集大成者的学派，主张以法治国、建立中央集权","dynasty":"战国","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh276","item":"墨家：代表人物：墨子；“当子思之时，出孔子后。”；《后汉书·张衡传》；《墨子》；不是墨翟个人的作品，而是墨家学派的总集；《墨子》有71篇；今本《墨子》存53篇；兼爱非攻；推崇节约；战国墨子创立的学派，主张“兼爱”“非攻”“尚贤”","dynasty":"战国","cat":"思想学派","source":"幕布笔记整理","theme":"思想学派"},{"id":"wh277","item":"春秋-最早的编年体：是后世编年体史书之祖。：是继《尚书》之后以记事为主的一部史书；发生在鲁国和王朝及其他诸侯中的重大历史事件；其所以名为“春秋”，是取春秋代序为一年的意思，后来就成为纪年史的专名。","dynasty":"春秋","cat":"史书","source":"幕布笔记整理","theme":"史书"},{"id":"wh278","item":"公羊传：公叔羊","dynasty":"春秋","cat":"史书","source":"幕布笔记整理","theme":"史书"},{"id":"wh279","item":"谷梁传：谷阳赤","dynasty":"春秋","cat":"史书","source":"幕布笔记整理","theme":"史书"},{"id":"wh280","item":"左传-第一部叙事详尽的编年体史书：左丘明；《烛之武退秦师》；特点；《左传》最突出的成就是：长于叙事；《左传》的另一突出成就是：善于写人；《左传》的又一突出成就是：工于记言","dynasty":"","cat":"史书","source":"幕布笔记整理","theme":"史书"},{"id":"wh281","item":"资治通鉴—最早的编年体通史","dynasty":"","cat":"史书","source":"幕布笔记整理","theme":"史书"},{"id":"wh284","item":"太史公","dynasty":"","cat":"史书","source":"幕布笔记整理","theme":"史书"},{"id":"wh286","item":"两汉时期散文文学最高峰","dynasty":"","cat":"史书","source":"幕布笔记整理","theme":"史书"},{"id":"wh289","item":"（前）汉书：内容；纪十二篇；表八篇；志十篇；传七十篇","dynasty":"","cat":"史书","source":"幕布笔记整理","theme":"史书"},{"id":"wh292","item":"六义：诗；书；乐；射；御；数","dynasty":"","cat":"六义","source":"幕布笔记整理","theme":"六义"},{"id":"wh293","item":"小说：先秦寓言，史书及一些杂家著作（如《山海经》、《吕氏春秋》、《晏子春秋》）中的片断描写可看作是最早的微型小说。","dynasty":"先秦","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh294","item":"班固《汉书•艺文志》","dynasty":"汉代","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh295","item":"刘勰《文心雕龙》：创作个性；才；学；气；习","dynasty":"魏晋","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh299","item":"宋元话本：话本的出现，是中国“小说史上的一大变迁”；鲁迅——《中国小说史略》","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh300","item":"三国演义：文不甚深，言不甚俗；《三国演义》的尊刘反曹观念里，有很深的民族情绪在里面；诸葛亮——智绝；关云长——义绝；曹操——奸绝","dynasty":"三国","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh301","item":"回本；120回本","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh302","item":"英雄传奇代表作：毛泽东；《水浒》这部书，好就好在投降。做反面教材，使人民都知道投降派","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh303","item":"四大名著之一：四大奇书之一","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh304","item":"梁山三位“女英雄”：孙二娘、顾大嫂、扈三娘","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh305","item":"水浒传：是四个淫妇：二潘、阎婆惜以及卢俊义的贾氏夫人","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh306","item":"西游记：神魔小说代表作；四大名著之一；四大奇书之一","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh307","item":"白话长篇小说发展的里程碑","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh308","item":"“世情小说”代表作","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh309","item":"金瓶梅：是第一部文人独创的长篇：有鲜明的晚明时代特征；鲁迅《中国小说史略》；“著此一家，即骂尽诸色”。《金瓶梅》实是从西门“一家”，写及“天下国家”。","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh310","item":"世情小说到清代形成多元化格局：才子佳人小说，有《玉娇梨》、《平山冷燕》和《好逑传》等；世态小说，《红楼梦》、《醒世姻缘传》、《林兰香》和《歧路灯》等；艳情小说，如《桃花影》、《灯月缘》、《梧桐影》、《杏花天》等","dynasty":"清","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh311","item":"“三言”：《喻世明言》；《三言》第一篇，是《喻世明言》中的《蒋兴哥重会珍珠衫》；三观炸裂；《警世通言》；《醒世恒言》；每集40篇，共120篇；冯梦龙；“三言”的出现，标志着古代白话短篇小说的整理和创作高潮的到来。","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh312","item":"“二拍”：《初刻拍案惊奇》；《二刻拍案惊奇》；凌濛初","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh313","item":"《今古奇观》：选“三言”、“二拍”佳作40篇，民间流传较广；明末“姑苏抱瓮老人”编","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh314","item":"《三刻拍案惊奇》：作者陆人龙","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"},{"id":"wh315","item":"文言短篇小说","dynasty":"","cat":"小说","source":"幕布笔记整理","theme":"小说"}],"n":284},{"key":"C","name":"外国文学","desc":"古希腊 → 意西 → 英 → 法 → 俄苏 → 美 → 德奥 → 其他 → 流派","count":70,"items":[{"id":"wg001","item":"荷马史诗：古希腊两部史诗《伊利亚特》《奥德赛》的合称，相传为盲诗人荷马所作。《伊利亚特》写特洛伊战争第十年的故事，《奥德赛》写奥德修斯战后十年漂泊返乡；《奥德赛》&amp;《伊利亚特》","dynasty":"古希腊","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg002","item":"埃斯库罗斯：古希腊三大悲剧作家之一，被称为『悲剧之父』，代表作《被缚的普罗米修斯》《俄瑞斯忒亚》三联剧。","dynasty":"古希腊","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg003","item":"索福克勒斯：古希腊三大悲剧作家之一，代表作《俄狄浦斯王》，被亚里士多德誉为最完美的悲剧。","dynasty":"古希腊","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg004","item":"欧里庇得斯：古希腊三大悲剧作家之一，代表作《美狄亚》，擅长刻画女性心理。","dynasty":"古希腊","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg005","item":"《伊索寓言》：古希腊寓言集，相传为奴隶伊索所作，名篇有《狼和小羊》《农夫和蛇》《龟兔赛跑》。","dynasty":"古希腊","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg010","item":"但丁：意大利诗人，文艺复兴先驱，代表作《神曲》（《地狱》《炼狱》《天堂》三部分），恩格斯称他『是中世纪的最后一位诗人，同时又是新时代的最初一位诗人』；现代意大利语的奠基者，欧洲文艺复兴时代的开拓者；恩格斯评论：“他是中世纪的最后一位诗人，同时也是新时代的最初一位诗人。”；《神曲》（天堂、地狱、炼狱）","dynasty":"意大利","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg011","item":"薄伽丘：意大利作家，文艺复兴代表，代表作《十日谈》，是欧洲文学史上第一部现实主义短篇小说集；《十日谈》；短篇小说形式；是欧洲文学史上第一部现实主义巨著；桑克提斯把《十日谈》与《神曲》相提并论，称之为“人曲”；意大利文艺复兴运动代表，人文主义作家，诗人；《十日谈》；薄伽丘与但丁、彼特拉克并称为佛罗伦萨文学“三杰”","dynasty":"意大利","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg012","item":"文艺复兴『三杰』：指意大利的但丁、彼特拉克、薄伽丘。（注意：美术三杰为达·芬奇、米开朗琪罗、拉斐尔）","dynasty":"意大利","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg013","item":"彼特拉克：意大利诗人，人文主义奠基者，代表作《歌集》，被称为『人文主义之父』。","dynasty":"意大利","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg014","item":"《堂吉诃德》：西班牙作家塞万提斯的长篇小说，主人公堂吉诃德沉溺于骑士小说幻想、脱离实际，是世界文学史上著名的喜剧（悲喜剧）形象；塞万提斯；与其说多才，不如说多灾；塞万提斯被狄更斯、福楼拜和陀斯妥耶夫斯基等人誉为现代小说之父；堂吉诃德；喜剧特征+悲剧色彩","dynasty":"西班牙","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg105","item":"塞万提斯：西班牙作家，代表作《堂吉诃德》，被誉为西班牙文学最高峰；西班牙小说家、剧作家、诗人；《堂吉诃德》（长篇小说）；主人公：堂吉诃德（原名阿隆索·吉哈诺）沉迷骑士小说；评论：“是西方文学史上的第一部现代主义长篇小说，也是世界文学的瑰宝之一","dynasty":"西班牙","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg020","item":"莎士比亚：英国文艺复兴时期剧作家、诗人，马克思称其为『人类最伟大的戏剧天才』。四大悲剧《哈姆雷特》《奥赛罗》《李尔王》《麦克白》；四大喜剧《威尼斯商人》《仲夏夜之梦》《皆大欢喜》《第十二夜》。","dynasty":"英国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg021","item":"《哈姆雷特》：莎士比亚悲剧代表作，主人公丹麦王子哈姆雷特是人文主义者的典型，著名独白『生存还是毁灭，这是一个值得考虑的问题』。","dynasty":"英国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg022","item":"笛福：英国小说家，代表作《鲁滨孙漂流记》，塑造了资产阶级上升时期的冒险者形象鲁滨孙；《鲁滨逊漂流记》(长篇小说)；《辛格顿船长》《摩尔·弗兰德斯》","dynasty":"英国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg023","item":"斯威夫特：英国作家，代表作《格列佛游记》，以讽刺手法批判英国社会。","dynasty":"英国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg024","item":"拜伦：英国浪漫主义诗人，代表作长诗《恰尔德·哈洛尔德游记》《唐璜》，创造『拜伦式英雄』形象。","dynasty":"英国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg025","item":"雪莱：英国浪漫主义诗人，代表作《西风颂》（名句『冬天来了，春天还会远吗』）、《解放了的普罗米修斯》。","dynasty":"英国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg026","item":"狄更斯：英国批判现实主义作家，代表作《大卫·科波菲尔》《雾都孤儿》《双城记》《艰难时世》；年他完成了第一部长篇小说《匹克威克外传》，是第一部现实主义小说创作；1837年他完成了第一部长篇小说《匹克威克外传》，是第一部现实主义小说创作","dynasty":"英国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg027","item":"夏洛蒂·勃朗特：英国女作家，代表作《简·爱》，塑造了追求独立平等的新型女性形象简·爱；《简·爱》（长篇小说）；主人公：简爱、罗切斯特","dynasty":"英国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg028","item":"艾米莉·勃朗特：英国女作家，代表作《呼啸山庄》；《呼啸山庄》；吉卜赛弃儿希斯克利夫被山庄老主人收养后，因受辱和恋爱不遂，外出致富。回来后，对与其女友凯瑟琳结婚的地主林顿及其子女进行报复的故事。","dynasty":"英国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg029","item":"哈代：英国作家，代表作《德伯家的苔丝》，属批判现实主义。","dynasty":"英国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg030","item":"萧伯纳：爱尔兰剧作家，1925年获诺贝尔文学奖，代表作《华伦夫人的职业》《圣女贞德》。《伪君子》是法国莫里哀的作品，非萧伯纳。","dynasty":"爱尔兰","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg031","item":"乔伊斯：爱尔兰作家，代表作《尤利西斯》，意识流小说代表作。","dynasty":"爱尔兰","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg040","item":"莫里哀：法国古典主义喜剧作家，代表作《伪君子》（达尔杜弗）、《吝啬鬼》（阿巴贡）、《唐璜》；《伪君子》；主人公：达尔杜弗（宗教骗子）、奥尔贡（富商）；《吝啬鬼》又名《悭吝人》；内容：塑造了资产者贪婪吝啬，嗜钱如命的丑恶本质；主人公：阿巴贡；《吝啬鬼》（阿巴贡)与《欧也妮葛朗台》(葛朗台)、《死魂灵》(泼留希金)、《威尼斯商人》（夏洛克）中的主角同为世界上最著名的四大吝啬鬼形象。","dynasty":"法国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg041","item":"雨果：法国浪漫主义文学领袖，代表作《巴黎圣母院》（体现『美丑对照原则』）、《悲惨世界》《九三年》；浪漫主义运动的领袖者，前半生是浪漫主义代表，后半生是批判现实主义代表，一生的主导思想是——人道主义","dynasty":"法国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg042","item":"巴尔扎克：法国批判现实主义大师，创作总集《人间喜剧》（90余部），代表作《高老头》（塑造吝啬鬼葛朗台的是《欧也妮·葛朗台》）、《欧也妮·葛朗台》。","dynasty":"法国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg043","item":"司汤达：法国批判现实主义作家，代表作《红与黑》，主人公于连是个人奋斗者的典型。","dynasty":"法国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg044","item":"福楼拜：法国作家，代表作《包法利夫人》，被视为现实主义典范。","dynasty":"法国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg045","item":"莫泊桑：法国短篇小说巨匠，被称为『短篇小说之王』，代表作《羊脂球》《项链》《我的叔叔于勒》；代表作品有《项链》《漂亮朋友》《羊脂球》（成名作）《我的叔叔于勒》等","dynasty":"法国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg046","item":"大仲马：法国作家，代表作《基督山伯爵》《三个火枪手》；世界通俗小说的典范；《基督山伯爵》(长篇小说)复仇故事；主人公：爱德蒙·唐泰斯、法利亚神甫；《三个火枪手》(长篇小说)；故事主角为达达尼昂，三个火枪手分别是阿多斯，波尔多斯，和阿拉密斯","dynasty":"法国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg047","item":"小仲马：法国作家，大仲马之子，代表作《茶花女》；《茶花女》；女主：玛格丽特；在法国文学史上，这是第一次把妓女作为主角的作品。","dynasty":"法国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg048","item":"凡尔纳：法国作家，被誉为『科学幻想小说之父』，代表作《海底两万里》《八十天环游地球》。（非『魔幻现实主义之父』）；《地心游记》《海底两万里》《格兰格船长的女儿》","dynasty":"法国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg049","item":"普鲁斯特：法国作家，代表作《追忆似水年华》，意识流小说开山之作。","dynasty":"法国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg050","item":"萨特：法国存在主义哲学家、作家，代表作《恶心》《存在与虚无》，1964年拒领诺贝尔文学奖。","dynasty":"法国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg051","item":"加缪：法国作家，代表作《局外人》《鼠疫》，1957年获诺贝尔文学奖。","dynasty":"法国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg060","item":"普希金：俄国诗人，被誉为『俄罗斯文学之父』，代表作诗体小说《叶甫盖尼·奥涅金》（塑造『多余人』奥涅金）、小说《上尉的女儿》；被高尔基称为“一代的诗宗”“俄罗斯诗歌的太阳”；诗歌：《欢乐颂》《乡村》；长诗：《鲁斯兰和柳德米拉》《青铜骑士》；短诗：《假如生活欺骗了你》；诗体小说：《叶甫盖尼·奥涅金》；小说：《上尉的女儿》","dynasty":"俄国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg061","item":"果戈理：俄国作家，代表作《死魂灵》（塑造守财奴泼留希金）、《钦差大臣》。","dynasty":"俄国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg062","item":"屠格涅夫：俄国作家，代表作《父与子》，塑造『多余人』与『新人』形象；《猎人笔记》（成名作，随笔集）；体现对农奴制度的无言控诉；《初恋》《贵族之家》《父与子》《散文诗集》（是最后一部作品）","dynasty":"俄国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg063","item":"陀思妥耶夫斯基：俄国作家，代表作《罪与罚》《卡拉马佐夫兄弟》；《穷人》的发表“小人物”主题，被誉为“新的果戈里”；《罪与罚》；拉斯克尔尼科夫","dynasty":"俄国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg064","item":"列夫·托尔斯泰：俄国批判现实主义文学最高峰，代表作《战争与和平》《安娜·卡列尼娜》《复活》。出身大贵族，晚年力求过简朴平民生活。","dynasty":"俄国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg065","item":"契诃夫：俄国短篇小说大师、戏剧家，代表作《变色龙》《套中人》（别里科夫）《樱桃园》；世界三大短篇小说巨匠；《哀伤》《苦恼》《小公务员之死》；《变色龙》；主人公：奥楚蔑洛夫；《套中人》；主人公：别里科夫（害怕新事物，维护旧事物，反对变革，阻碍社会发展的人的代名词）；戏剧：《海鸥》","dynasty":"俄国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg068","item":"『多余人』形象：19世纪俄国文学中的贵族知识分子典型，有才华却脱离实际、无所作为。代表：奥涅金（普希金《叶甫盖尼·奥涅金》）、毕巧林（莱蒙托夫《当代英雄》）、罗亭（屠格涅夫《罗亭》）、奥勃洛摩夫（冈察洛夫）。","dynasty":"俄国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg069","item":"『小人物』主题：俄国文学重要主题，写底层小人物的悲惨命运。代表：普希金《驿站长》、果戈理《外套》、陀思妥耶夫斯基《穷人》、契诃夫《小公务员之死》。","dynasty":"俄国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg066","item":"高尔基：苏联作家，社会主义现实主义奠基人，代表作《母亲》、自传体三部曲《童年》《在人间》《我的大学》、散文诗《海燕》；《海燕》——散文诗；《母亲》——长篇小说（在世界文学史上开辟了无产阶级文学的新纪元)；第一部现实主义的典范作品；主人公：尼洛夫娜；自传三部曲；《童年》《在人间》《我的大学》；主人公：阿廖沙","dynasty":"苏联","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg067","item":"奥斯特洛夫斯基：苏联作家，代表作《钢铁是怎样炼成的》，塑造无产阶级英雄保尔·柯察金。","dynasty":"苏联","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg080","item":"马克·吐温：美国作家，代表作《哈克贝利·费恩历险记》《汤姆·索亚历险记》，被誉为『美国文学中的林肯』。","dynasty":"美国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg081","item":"海明威：美国作家，1954年获诺贝尔文学奖，代表作《老人与海》（名句『一个人并不是生来要给打败的，你尽可以把他消灭掉，可就是打不败他』）、《永别了，武器》。","dynasty":"美国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg082","item":"惠特曼：美国诗人，代表作诗集《草叶集》，开创自由体诗；《草叶集》；创立了自由诗体、开一代诗风","dynasty":"美国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg083","item":"欧·亨利：美国短篇小说家，以『欧·亨利式结尾』（出乎意料又在情理之中）著称，代表作《麦琪的礼物》《警察与赞美诗》；世界三大短篇小说巨匠；美国生活幽默的百科全书；短篇小说：《麦琪的礼物》《警察与赞美诗》《最后一片藤叶》《黄雀在后》《我们选择的道路》；长篇小说：《白菜与皇帝》（唯一的一部长篇小说）；独特的艺术风格：“含泪的微笑”；结尾：“意料之外，情理之中”","dynasty":"美国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg090","item":"歌德：德国作家，代表作诗剧《浮士德》（浮士德与魔鬼梅菲斯特打赌）、小说《少年维特之烦恼》；书信体《少年维特之烦恼》（爱情悲剧）；主人公：维特、绿蒂；诗剧《浮士德》；以天帝、天使和魔鬼靡菲斯特关于人的争论，赌赛为开端引出作为赌赛对象是浮士德博士，进而引发了浮士德与魔鬼的赌赛","dynasty":"德国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg091","item":"席勒：德国诗人、剧作家，代表作《阴谋与爱情》《欢乐颂》。","dynasty":"德国","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg092","item":"卡夫卡：奥地利作家（德语写作），现代主义奠基人，代表作《变形记》《城堡》《审判》；现代主义文学奠基者之一；《审判》《城堡》（长篇小说）；《变形记》（中篇小说）；主人公：格里高尔·萨姆沙","dynasty":"奥地利","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg100","item":"泰戈尔：印度诗人，1913年获诺贝尔文学奖（亚洲第一人），代表作《吉檀迦利》《飞鸟集》（『生如夏花之绚烂，死如秋叶之静美』）《新月集》；近代印度著名诗人；诗集：《吉檀伽利》（诺贝尔文学奖）《飞鸟集》；长篇小说《沉船》","dynasty":"印度","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg101","item":"川端康成：日本作家，1968年获诺贝尔文学奖，代表作《雪国》《伊豆的舞女》《古都》。","dynasty":"日本","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg102","item":"大江健三郎：日本作家，1994年获诺贝尔文学奖，是继川端康成之后第二位获该奖的日本作家，代表作《个人的体验》。","dynasty":"日本","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg103","item":"《一千零一夜》：又名《天方夜谭》，是阿拉伯民间故事集（非古希腊），名篇有《阿拉丁神灯》《阿里巴巴和四十大盗》。","dynasty":"阿拉伯","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg106","item":"易卜生：挪威剧作家，『现代戏剧之父』，代表作《玩偶之家》（主人公娜拉出走）；是欧洲近代现实主义戏剧的杰出代表，被誉为“现代戏剧之父”；《玩偶之家》；主人公：娜拉；一部典型的社会问题剧","dynasty":"挪威","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg107","item":"安徒生：丹麦童话作家，代表作《海的女儿》《丑小鸭》《卖火柴的小女孩》。","dynasty":"丹麦","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg104","item":"马尔克斯：哥伦比亚作家，魔幻现实主义代表，1982年获诺贝尔文学奖，代表作《百年孤独》；拉丁美洲魔幻现实主义主义；《霍乱时期的爱情》（长篇小说）；《百年孤独》魔幻现实主义文学的代表作，被称为当代的《堂吉诃德》；布恩迪亚家族七代人的传奇故事","dynasty":"哥伦比亚","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg108","item":"世界四大吝啬鬼：夏洛克（莎士比亚《威尼斯商人》）、阿巴贡（莫里哀《悭吝人》）、葛朗台（巴尔扎克《欧也妮·葛朗台》）、泼留希金（果戈理《死魂灵》）。","dynasty":"","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg109","item":"外国文学三大短篇小说巨匠：莫泊桑（法国）、契诃夫（俄国）、欧·亨利（美国）。","dynasty":"","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg110","item":"意识流小说代表：普鲁斯特《追忆似水年华》（法）、乔伊斯《尤利西斯》（爱尔兰）、伍尔夫《达洛维夫人》（英）、福克纳《喧哗与骚动》（美）。","dynasty":"","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg120","item":"文艺复兴：14—17世纪欧洲思想文化解放运动，核心是人文主义，反封建反教会。发源于意大利，代表人物有但丁、彼特拉克、薄伽丘、达·芬奇、莎士比亚、塞万提斯、拉伯雷。","dynasty":"","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg121","item":"人文主义：文艺复兴的核心思想，主张以人为中心而不是以神为中心，肯定人的价值和尊严，反对禁欲主义和来世观念。","dynasty":"","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg122","item":"古典主义：17世纪法国主导的文学思潮，崇尚理性、模仿古希腊罗马，遵守『三一律』。代表：高乃依《熙德》、莫里哀、拉辛。","dynasty":"","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg123","item":"浪漫主义：18世纪末至19世纪上半叶欧洲文学思潮，强调主观情感、想象、自由，反抗古典主义束缚。代表：雨果（法）、拜伦、雪莱（英）、普希金（俄）、惠特曼（美）。","dynasty":"","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg124","item":"批判现实主义：19世纪中后期欧洲文学主潮，真实再现社会现实、批判社会弊病。代表：巴尔扎克、司汤达、福楼拜（法）、狄更斯（英）、托尔斯泰、契诃夫（俄）、马克·吐温（美）。","dynasty":"","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg125","item":"魔幻现实主义：20世纪拉美文学流派，用魔幻手法反映现实。代表：马尔克斯《百年孤独》（哥伦比亚）、阿斯图里亚斯（危地马拉）。","dynasty":"","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg126","item":"存在主义文学：20世纪法国文学流派，关注荒诞与自由选择。代表：萨特《恶心》、加缪《局外人》。","dynasty":"","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg127","item":"诺贝尔文学奖：1901年设立，依据诺贝尔遗嘱颁发给『在文学方面创作出具有理想倾向的最佳作品的人』。亚洲首位获奖者为印度泰戈尔（1913）。","dynasty":"","cat":"外国文学","source":"外国文学常识（教材通行说法）"},{"id":"wg128","item":"韩非子（法家）：战国末期韩国公子，荀子的学生；思想主张：富国强兵、以法治国；《韩非子》（善用譬喻和寓言故事，如守株待兔、郑人买履、滥竽充数...）","dynasty":"","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg129","item":"古希腊三大悲剧家：埃斯库罗斯；《被俘的普罗米修斯》；索福克勒斯；《俄狄浦斯王》；欧里庇得斯；《美狄亚》","dynasty":"古希腊","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg133","item":"拉伯雷（法国）：《巨人传》；父子两代巨人卡冈都亚；讴歌人性、高扬人性的人文主义伟大杰作；平民倾向；法国讽刺文学的一代宗师；代表作是《巨人传》；讽刺小说；人的形象首次顶天立地屹立在神的面前的一次成功的尝试","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg136","item":"与汤显祖都在1616年去世","dynasty":"英国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg137","item":"四大喜剧：《仲夏夜之梦》；《威尼斯商人》；《第十二夜》；《皆大欢喜》","dynasty":"英国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg138","item":"四大悲剧：《哈姆雷特》（王子复仇记）；主人公：丹麦王子哈姆雷特、叔叔克劳狄斯、恋人奥菲利亚；《奥赛罗》；《李尔王》；《麦克白》","dynasty":"英国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg139","item":"《罗密欧与朱丽叶》《辛白林》","dynasty":"英国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg142","item":"卢梭(法国)：法国启蒙运动成就最高；书信体《新爱洛伊丝》青年爱情悲剧；主人公：圣普乐（平民知识分子）、朱丽（贵族小姐）；《论人类不平等的起源和基础》《社会契约论》","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg145","item":"《悲惨世界》(长篇小说)：主人公:冉·阿让（化名马德兰）、妓女芳汀、私生女珂赛特、共和派青年马利尤斯","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg146","item":"《巴黎圣母院》(长篇小说)：对比手法描写；主人公：埃斯梅拉达（吉普赛姑娘）、克洛德（圣母院副主教）、伽西莫多（圣母院敲钟人）、弗比斯、居第尔","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg147","item":"剧本《克伦威尔序言》：提出美丑对照原则","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg148","item":"剧本《欧那尼》","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg149","item":"《海上劳工》《笑面人》《九三年》","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg151","item":"格林兄弟（德国）：《格林童话》","dynasty":"德国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg155","item":"巴尔扎克（法国）批判现实：《人间喜剧》使现实主义从理论到创作都趋于完善，代表了西欧现实主义的最高成就；资本主义的百科全书；三大类：风俗研究（最重要、作品最多），哲学研究，分析研究；《欧也妮·葛朗台》《高老头》（《人间喜剧》里）","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg156","item":"司汤达（法国）批判现实：法国批判现实主义文学奠基人之一，“近代小说之父”“现实主义大师”；《红与黑》（长篇小说）现实主义奠基之作；主人公：于连","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg157","item":"福楼拜（法国）批判现实：《包法利夫人》；受过贵族化教育的农家女爱玛，乡镇医生的丈夫包法利，梦想传奇式爱情，却因偷情失败而成为高利贷者盘剥的对象，最后服毒自尽。","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg159","item":"具有强烈的人道主义思想","dynasty":"英国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg161","item":"《双城记》（长篇小说）：以法国大革命为背景；书名中的“双城”指的是巴黎与伦敦；主人公：马内特医生、查尔斯达内、露西","dynasty":"英国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg162","item":"《雾都孤儿》（长篇小说）：主人公奥利弗","dynasty":"英国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg163","item":"《大卫·科波菲尔》","dynasty":"英国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg167","item":"果戈里（俄国批判主义作家）：讽刺喜剧《钦差大臣》；《死魂灵》（长篇小说）“俄国文学史上无与伦比的作品”；主人公：乞乞科夫（收购死农奴）、泼留希金；俄国批判现实主义文学发展的基石，也是果戈理的现实主义创作发展的顶峰。","dynasty":"俄国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg168","item":"后期文学：与俄国契诃夫和美国欧·亨利并称为“世界三大短篇小说巨匠”；幽默、讽刺而闻名，被誉为“社会批评家”；《百万英镑》《哈克贝利·费恩历险记》《汤姆·索亚历险记》《王子与贫儿》《破坏了赫德莱堡的人》《镀金时代》《竞选州长》","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg169","item":"现代文学中的“世界短篇小说之王”","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg170","item":"《米龙老爹》：讲述了普法战争中法国诺曼底地区一个普通农民为报家仇而孤胆杀敌的故事，成功塑造了一个机智勇敢、敢于反抗侵略者的农民英雄形象，表现出法国下层社会劳动人民为保护民族和个人利益不畏强权、英勇抗击侵略者的英雄主义和爱国精神；采用倒叙的叙事方式（设置悬念，为下文作铺垫）；通过肖像描写和细节描写来刻画人物性格；语言简洁，并富有个性化；小说在叙事方式上的另一个特点是第一人称和第三人称的交互作用","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg172","item":"列夫托尔斯泰（俄国批判现实）：是世界公认的最伟大的小说家之一，被列宁称是“俄国革命的镜子”；《战争与和平》；男主人公：安德烈（心里装着祖国和人民）；《安娜·卡列尼娜》；主人公：安娜、卡列宁、沃伦斯基；《复活》（灵魂救赎）；主人公：聂赫留朵夫、玛丝洛娃","dynasty":"俄国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg176","item":"罗曼·罗兰（法国，批判现实主义）：法国第一位诺贝尔文学奖获得者；长篇巨著《约翰·克利斯朵夫》（音乐家约翰·克利斯朵夫在德国的一生，以贝多芬为原型，奠定文学地位）；《名人传》；《贝多芬传》《米开朗琪罗传》《列夫·托尔斯泰传》","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg177","item":"菲次杰拉德（美国）：长篇小说：《人间天堂》；《夜色温柔》《末代大亨的情缘》；《了不起的盖茨比》揭露了“美国梦”的虚假实质；主人公：盖茨比、黛西","dynasty":"美国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg178","item":"米勒·海明威（美国）：《老人与海》——诺贝尔文学奖（中篇小说）；泰然自若地接受失败，沉着勇敢地面对死亡，体现“硬汉形象”，根据当时的时代背景，让人看到光明和曙光；主人公：圣地亚哥（老渔夫），马诺林（小孩）；《太阳照样升起》《永别了，武器》","dynasty":"美国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg179","item":"玛格丽特·米切尔（美国）：因长篇小说《飘》（《乱世佳人》）一生唯一的作品；梗概：美国南北战争时，斯嘉丽、瑞德、艾希礼、梅兰妮四人的爱情纠葛","dynasty":"美国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg180","item":"帕斯捷尔纳克（苏联）：《日瓦戈医生》——诺贝尔文学奖；十月革命胜利前后日瓦尔一生的生活变动及人生宿命","dynasty":"苏联","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg182","item":"肖洛霍夫（苏联）：《静静的顿河》（长篇小说）——获得诺贝尔文学奖；主人公：葛利高里（哥萨克的重大事件）","dynasty":"苏联","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg184","item":"马塞尔·普鲁斯特（法国）：意识流文学的先驱与大师；长篇小说：《追忆逝水年华》（意识流小说的开山之作）；主人公：马塞尔","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg185","item":"约瑟夫·海勒（美国）：长篇小说《第二十二条军规》（成名作）——被视为“黑色幽默”的经典名著；驻扎在意大利皮亚诺扎岛上美国空军的混乱生活；主人公：尤索林","dynasty":"美国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg188","item":"西方文学三大不朽典型形象：堂吉诃德；哈姆雷特；浮士德","dynasty":"","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg189","item":"荷马：《荷马史诗》；《奥德赛》&《伊利亚特》","dynasty":"古希腊","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg190","item":"柏拉图：柏拉图和老师苏格拉底，学生亚里士多德并称为希腊三贤；《理想国》","dynasty":"古希腊","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg191","item":"亚里士多德：恩格斯称他是“古代的黑格尔”；《诗学》","dynasty":"古希腊","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg193","item":"三大悲剧诗人：埃斯库罗斯——悲剧之父；《俄瑞斯忒亚》三部曲；《阿伽门农》《奠酒人》《报仇神》；“戏剧艺术中的荷马”；索福克勒斯；舞台上的哲学家；欧里庇得斯","dynasty":"古希腊","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg194","item":"喜剧（旧喜剧）：主要取材于现实生活，多为政治讽刺剧和社会讽刺剧。表现形式轻松而意图是严肃的；三大喜剧诗人；克拉提诺斯；欧波利斯；阿里斯托芬；喜剧诗人；代表作有《鸟》、《阿卡奈人》等；作品触及了雅典奴隶主民主制度危机时期的许多重大政治问题、社会问题，恩格斯：“强烈倾向的诗人”。","dynasty":"古希腊","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg195","item":"新喜剧（前323-前263）：始于亚历山大，止于新喜剧诗人菲勒蒙","dynasty":"古希腊","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg196","item":"古罗马：古罗马文学是古希腊文学与近代欧洲文学的桥梁：古罗马文化主要是继承古希腊文化而逐步发展而来的","dynasty":"古罗马","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg197","item":"贺拉斯：《诗简》诗体书信集；即《诗艺》","dynasty":"古罗马","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg198","item":"奥维德：神话诗《变形记》；有“神话词典”之称","dynasty":"古罗马","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg199","item":"阿普列尤斯——公认的“小说之父”：《金驴记》又称《变形记》是欧洲最早的长篇小说。","dynasty":"古罗马","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg200","item":"宗教文学","dynasty":"","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg201","item":"史诗与谣曲：盎格鲁·撒克逊人的《贝奥武甫》是流传至今保存最完整的中世纪史诗；法国《罗兰之歌》；西班牙《熙德之歌》","dynasty":"","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg202","item":"骑士文学","dynasty":"","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg203","item":"城市文学（又称市民文学）","dynasty":"","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg204","item":"意大利人：意大利第一个民族诗人；他是中世纪的最后一位诗人，同时又是新时代的最初一位诗人。”——恩格斯","dynasty":"意大利","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg205","item":"属于“温柔的新体”诗派：《新生》；31首诗，散文连缀；抒发对贝娅特丽丝纯真的爱；《神曲》；采用中世纪特有的幻游形式，叙述了诗人梦游三界的情形。充满了寓意和象征；分《地狱》、《炼狱》、《天堂》三部；每部33篇，加上《序曲》共100篇。","dynasty":"","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg206","item":"彼特拉克——人文主义之父：被誉为“诗圣”；代表作《歌集》；他的十四行诗为近代欧洲抒情诗的发展开辟了道路","dynasty":"意大利","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg207","item":"七星诗社：贵族倾向","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg209","item":"蒙田：欧洲近代散文的创始人；《随笔集》","dynasty":"法国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg210","item":"《小癞子》：16世纪最著名的流浪汉小说；开创了“流浪汉小说”叙事结构","dynasty":"西班牙","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg211","item":"洛贝·德·维伽：“西班牙戏剧之父”；代表作《羊泉村》","dynasty":"西班牙","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg212","item":"乔叟：“英国诗歌之父”；《坎特伯雷故事集》","dynasty":"英国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg213","item":"托马斯.莫尔：《乌托邦》：对话体幻想小说","dynasty":"英国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg214","item":"英国：埃德蒙。斯宾塞：长诗《仙后》","dynasty":"英国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg215","item":"大学才子派：托马斯·基德；《哈姆雷特》，对莎士比亚的同名剧有影响","dynasty":"英国","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg216","item":"流浪汉小说：笛福《摩尔·弗兰德斯》《鲁滨逊漂流记》；伏尔泰《老实人》；斯威夫特《格列佛游记》；夏洛蒂·勃朗特《简·爱》","dynasty":"","cat":"外国文学","source":"幕布笔记整理"},{"id":"wg217","item":"荷马“第一个悲剧诗人”：荷马史诗；《伊利亚特》（特洛伊战争，因女人而引发的战争）；《奥德赛》（航海小说鼻祖）","dynasty":"古希腊","cat":"外国文学","source":"幕布笔记整理"}],"n":132},{"key":"D","name":"中国文学·现代","desc":"现代文学（1919—1949）与当代文学（1949—）","count":178,"items":[{"id":"lp050","item":"创造社：1921年成立于日本东京，成员有郭沫若、郁达夫、成仿吾、张资平、田汉等，以《创造》季刊为阵地，倾向浪漫主义，主张“为艺术而艺术”郭沫若、张资平、郁达夫、成仿吾、⽥汉、穆⽊天、张凤举、徐祖正、陶晶孙、何畏等⼈；为艺术⽽艺术","dynasty":"现代","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp051","item":"新月派：20世纪20年代以徐志摩、闻一多为代表的新诗流派，讲究诗歌的音乐美、绘画美、建筑美。","dynasty":"现代","cat":"文学流派","source":"https://m.baike.com/"},{"id":"lp052","item":"左翼作家联盟（左联）：1930年在上海成立的革命文学团体，鲁迅为旗手。","dynasty":"现代","cat":"文学流派","source":"https://m.baike.com/"},{"id":"zj089","item":"鲁迅：原名周树人，字豫才，现代文学奠基人。1918年发表我国现代文学史上第一篇白话小说《狂人日记》，小说集《呐喊》《彷徨》，散文集《朝花夕拾》；原名：周树人，字豫才，“民族魂”，中国现代文学的开拓者和奠基人，中国现代杂文的开创者","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj090","item":"郭沫若：现代诗人、剧作家，新诗奠基人之一，代表作诗集《女神》，历史剧《屈原》《虎符》；新诗的奠基人，是继鲁迅之后革命文化界公认的领袖；原名开贞，与郁达夫等人在东京组织创造社；诗集：《星空》《恢复》《女神》（是中国现代新诗的奠基之作，其中有《炉中煤》）；历史剧：《王昭君》《棠棣之花》《屈原》《虎符》；历史剧《蔡文姬》——“继鲁迅之后。文化战线上又一面光辉的旗帜”诗集；女神；历史剧；屈原；虎符；蔡文姬；武则天；王昭君","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj091","item":"茅盾：原名沈德鸿，字雁冰，现代作家、文学评论家，文学研究会重要成员，代表作《子夜》《林家铺子》，“蚀”三部曲；长篇小说：《子夜》（主人公：吴荪甫）《腐蚀》；蚀·三部曲：《幻灭》（第一部长篇小说）《动摇》《追求》；农村三部曲：《春蚕》（《林家铺子》）《秋收》《残冬》","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj092","item":"叶圣陶：原名叶绍钧，现代作家、教育家，文学研究会成员，代表作《倪焕之》《多收了三五斗》长篇小说；倪焕之","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj093","item":"朱自清：字佩弦，现代散文家、学者，代表作《背影》《荷塘月色》《匆匆》；诗歌和散文合集：《踪迹》；长诗：《毁灭》；散文集：《背影》《欧游杂记》《松堂游记》；散文短篇：《春》《背影》《绿》中国最为杰出的抒情诗人；鲁迅","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj095","item":"冰心：原名谢婉莹，现代女作家，倡导“爱的哲学”，代表作《繁星》《春水》《寄小读者》；原名：谢婉莹；散文语言典雅飘逸。清丽淡远，被誉为“冰心体”；诗集：《繁星》（第一部诗集）《春水》；问题小说代表作：《两个家庭》《斯人独憔悴》《秋风秋雨愁煞人》；《寄小读者》；《往事》；是一篇托物言志的写景散文，写作上采用欲扬先抑的表现手法和拟人的修辞手法；作者用大海象征心目中的理想人格；谢婉莹；繁星体；以爱的哲学为主题；繁星；春水","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj096","item":"巴金：原名李尧棠，字芾甘，现代作家，代表作“激流三部曲”《家》《春》《秋》；全文以灯光为线索；故居大门象征封建旧家族的衰亡和崩溃；爱尔克的灯光象征封建旧家庭里的青年渴求幸福的希望破灭；心灵的灯象征着作者心中新的希望、光明和理想；照壁上的“长宜子孙”四个字象征着封建家庭制度对于青年人的禁锢和迫害；被誉为“二十世纪中国文学的良心”创作《随想录》","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj097","item":"戴望舒：现代诗人，现代派代表，代表作《雨巷》，被称为“雨巷诗人”；“雨巷诗人”现代派象征主义；诗歌名篇：《雨巷》《断指》《我用我残损的手掌》；诗集：《我的记忆》","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj098","item":"曹禺：原名万家宝，现代剧作家，中国现代话剧奠基人，代表作《雷雨》《日出》《原野》；中国现代戏剧的泰斗，中国现代话剧史上成就最高的剧作家；话剧：《日出》《白露》《原野》《北京人》；《雷雨》；主人公：周朴园、侍萍、鲁大海、周萍、周冲、繁漪、鲁贵、四凤","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj099","item":"沈从文：现代作家，京派小说代表，代表作《边城》；原名：沈岳焕，乡土小说，京派小说代表人物；小说：《边城》（艺术创作高峰，茶峒小镇）《月下小景》《三三》《长河》；散文集：《湘行散记》《湘西》；游记散文：《箱子岩》（出自《湘行散记》）边城；少女翠翠；天保、傩送","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj100","item":"钱锺书：字默存，现代作家、学者，代表作长篇小说《围城》字默存，号槐聚","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj113","item":"郁达夫：现代作家，创造社成员，代表作《沉沦》《春风沉醉的晚上》；浪漫主义，自述手法；短篇小说集：《沉沦》中国现代文学史第一部白话短篇小说集；短篇小说：《沉沦》《南迁》《银灰色的死》、《春风沉醉的晚上》《薄奠》《迟桂花》；散文集：《闲书》《屐痕处》《日记九种》；散文：《一个人在途上》《钓台的春昼》中国的现代小说之父；沉沦；中国现代文学史上第一部白话小说集；故都的秋","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj114","item":"徐志摩：新月派代表诗人，代表作《再别康桥》《沙扬娜拉》；《再别康桥》（选自诗集《猛虎集》）《志摩的诗》《翡冷翠的一夜》《云游》","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj115","item":"闻一多：新月派诗人、学者，提出诗歌“三美”主张，代表作《死水》；《发现》（选自诗集《死水》）；新诗集《红烛》《死水》；大力提倡新格律诗的三美（音乐美，绘画美，建筑美），因而被称为“格律派”；“格律派”“自由派”“象征派”——中国新诗发展史上三大重要诗派；五四时期的唯一爱国诗人；诗三美；音乐美；建筑美；绘画美","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"zj116","item":"艾青：现代诗人，代表作《大堰河——我的保姆》《我爱这土地》；被胡风称为“吹芦笛的诗人”；现代诗人的代表诗人，积极向上的革命精神；《北方》（《我爱这土地》）；《大堰河——我的保姆》成名作，第一部；《向太阳》《大堰河》《黎明的通知》","dynasty":"现代","cat":"作家作品","source":"https://www.gushiwen.cn/"},{"id":"xd001","item":"语丝社：1924年成立于北京，因《语丝》周刊得名，成员有鲁迅、周作人、林语堂、钱玄同、孙伏园等。多写杂感随笔，任意而谈、讽刺幽默，形成『语丝体』；有周作⼈、钱⽞同、林语堂、刘半农、孙伏园、冯⽂炳、俞平伯；宇宙风；以自我为中心，以闲适为格调；倡导社会批评","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd002","item":"莽原社与未名社：1925年由鲁迅发起和支持，《莽原》《未名》半月刊为阵地，成员有韦素园、台静农、李霁野等，多写乡土文学，揭露旧社会黑暗。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd003","item":"湖畔诗社：1922年成立于杭州，成员汪静之、冯雪峰、潘漠华、应修人，出版《湖畔》《春的歌集》，以抒写青年爱情与自然著称。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd004","item":"象征诗派：1925年李金发《微雨》出版标志其诞生，代表还有王独清、穆木天、冯乃超，多用象征、暗示、通感，诗风晦涩。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd005","item":"现代诗派：以1932年《现代》杂志为中心，代表戴望舒、施蛰存、何其芳、卞之琳、李广田，主张『纯诗』，追求意象与音乐性。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd006","item":"七月诗派：以胡风主编的《七月》《希望》为阵地，代表艾青、田间、绿原、牛汉、阿垅、曾卓，贯穿抗战与解放战争，主现实主义、自由体。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd007","item":"九叶诗派（中国新诗派）：抗战后期及解放战争时期，成员辛笛、陈敬容、唐湜、唐祈、穆旦、郑敏、杜运燮、袁可嘉、杭约赫九人，1981年结集《九叶集》得名，具现代主义倾向。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd008","item":"新感觉派：20世纪30年代上海，代表刘呐鸥《都市风景线》、施蛰存《梅雨之夕》、穆时英《上海的狐步舞》，借鉴日本新感觉派，写都市光怪陆离，重心理分析；中国第一个也是唯一一个现代主义小说流派","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd009","item":"京派：20世纪30年代活跃于北方（北平、天津），代表沈从文、废名、萧乾、芦焚、汪曾祺，主张远离政治、表现乡村人性美与纯正文学趣味。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd010","item":"海派：20世纪30—40年代上海都市文学，代表张爱玲、苏青、徐訏、无名氏，写都市世俗人生与洋场男女，笔调苍凉。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd011","item":"东北作家群：九一八事变后流亡关内的一批东北作家，代表萧军《八月的乡村》、萧红《生死场》、端木蕻良《科尔沁旗草原》、骆宾基，作品充满抗日救亡色彩。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd012","item":"乡土文学：20世纪20年代由鲁迅开创，王鲁彦、台静农、彭家煌、蹇先艾等以《故乡》式笔法写农村凋敝与农民苦难，是五四现实主义的重要一支。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd013","item":"左联五烈士：1931年被国民党杀害的柔石、殷夫、胡也频、冯铿、李伟森（李求实），鲁迅作《为了忘却的记念》悼念。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd014","item":"新月诗派『三美』：闻一多在《诗的格律》中提出音乐美（音节）、绘画美（辞藻）、建筑美（节的匀称和句的均齐）。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd020","item":"胡适：字适之，学者、诗人，1917年发表《文学改良刍议》倡导白话文，1920年出版《尝试集》，是中国现代文学史上第一部白话新诗集；《尝试集》（中国文学史上第一部白话诗集）文学改良刍议；是倡导文学革命的第一篇文章","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd021","item":"周作人：鲁迅二弟，散文家，五四时期提倡『人的文学』『平民文学』，散文集《自己的园地》《雨天的书》《泽泻集》，提倡冲淡平和的『美文』。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd022","item":"张爱玲：原名张煐，现代女作家，代表作《倾城之恋》《金锁记》《红玫瑰与白玫瑰》《半生缘》，散文集《流言》，笔调苍凉、工于意象，海派代表；京派小说；短篇小说：《沉香屑·第一炉香》《倾城之恋》（范柳原、白流苏）《红玫瑰与白玫瑰》《金锁记》《连环套》《琉璃瓦》；散文：《迟暮》《天才梦》","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd023","item":"萧红：现代女作家，东北作家群代表，代表作《生死场》《呼兰河传》《小城三月》，被鲁迅誉为『中国最有前途的女作家』；中篇小说：《生死场》《马伯乐》；长篇小说：《呼兰河传》30年代文学洛神","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd024","item":"丁玲：现代女作家，代表作《莎菲女士的日记》（早期）、《太阳照在桑干河上》（获1951年斯大林文学奖），长篇小说《母亲》。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd025","item":"许地山：笔名落华生，现代作家、学者，代表作散文《落花生》、小说《春桃》《缀网劳蛛》，作品带宗教哲思与异域色彩。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd026","item":"废名：原名冯文炳，京派小说家，代表作《竹林的故事》《桥》《莫须有先生传》，笔调冲淡、散文化。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd027","item":"施蛰存：新感觉派代表，代表作《梅雨之夕》《将军底头》，善用心理分析。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd028","item":"穆时英：新感觉派代表，人称『新感觉派圣手』，代表作《上海的狐步舞》《南北极》。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd029","item":"柔石：左联五烈士之一，代表作《二月》《为奴隶的母亲》。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd030","item":"叶紫：现代作家，代表作《丰收》《火》，写湖南农村斗争。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd031","item":"沙汀：现代作家，代表作《在其香居茶馆里》《淘金记》，写四川乡镇黑暗。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd032","item":"张天翼：现代作家，代表作《华威先生》《包氏父子》，以讽刺见长。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd033","item":"艾芜：现代作家，代表作《南行记》，写滇缅边地流浪者。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd034","item":"吴组缃：现代作家，代表作《箓竹山房》《一千八百担》，写皖南农村。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd035","item":"田汉：现代戏剧家，中国现代话剧奠基人之一，代表作《名优之死》《回春之曲》《关汉卿》，是《义勇军进行曲》词作者；中国话剧三大奠基者之一；关汉卿","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd036","item":"夏衍：现代剧作家，代表作报告文学《包身工》、话剧《上海屋檐下》《法西斯细菌》剧本；春蚕；祝福；林家铺子；报告文学；包身工","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd037","item":"洪深：现代戏剧家，代表作《赵阎王》，中国现代话剧开拓者之一。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd038","item":"丁西林：现代剧作家、物理学家，代表作独幕喜剧《一只马蜂》《压迫》，以机智幽默著称。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd039","item":"冯至：现代诗人、学者，代表作《十四行集》，鲁迅称他为『中国最为杰出的抒情诗人』。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd040","item":"卞之琳：现代诗人，代表作《断章》（『你站在桥上看风景，看风景的人在楼上看你』）《鱼目集》，现代诗派代表。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd041","item":"何其芳：现代诗人、散文家，代表作诗集《预言》、散文集《画梦录》。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd042","item":"李金发：象征诗派开创者，诗集《微雨》《为幸福而歌》《食客与凶年》，诗风晦涩。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd043","item":"臧克家：现代诗人，代表作《烙印》《老马》《有的人》（纪念鲁迅）《有的⼈》","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd044","item":"田间：现代诗人，人称『擂鼓诗人』，代表作《给战斗者》《赶车传》，诗行短促有力。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd045","item":"穆旦：九叶诗派代表，原名查良铮，代表作《赞美》《诗八首》，兼为翻译家。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd046","item":"梁实秋：现代散文家、学者，代表作《雅舍小品》，文风幽默隽永；独力译完《莎士比亚全集》；名治华；与胡适、徐志摩、闻一多等人创办新月书店，次年又创办《新月》月刊——“新月社”；《雅舍小品》(奠定作者在中国现代散文史上地位的一部作品）《槐园梦忆》《英国文学史》；《谈时间》（选自《雅舍小品》）；议论性随笔；主张文学无阶级；莎士比亚全集；英国文学史","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd047","item":"林语堂：现代作家、学者，提倡幽默、闲适、性灵，代表作《生活的艺术》《吾国与吾民》，用英文写作。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd048","item":"丰子恺：现代散文家、画家，代表作《缘缘堂随笔》，文画皆具童真禅意。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd049","item":"李大钊：革命家、学者，代表作《青春》《庶民的胜利》《布尔什维主义的胜利》，中国最早传播马克思主义者之一。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd050","item":"陈独秀：五四新文化运动领袖，1915年创办《青年杂志》（后改《新青年》），发表《文学革命论》。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd060","item":"《狂人日记》：鲁迅1918年发表于《新青年》，中国现代文学史上第一篇白话小说，以『吃人』揭示封建礼教本质。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd061","item":"《阿Q正传》：鲁迅1921年发表，塑造阿Q这一『精神胜利法』典型，是中国现代文学史上不朽的国民性批判之作。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd062","item":"鲁迅三部小说集：《呐喊》（1923，含《狂人日记》《阿Q正传》《故乡》《孔乙己》《药》）、《彷徨》（1926，含《祝福》《伤逝》《在酒楼上》）、《故事新编》（1936，历史小说）。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd063","item":"《野草》：鲁迅唯一一部散文诗集（1927），多用象征手法，含《秋夜》《过客》《这样的战士》。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd064","item":"《朝花夕拾》：鲁迅回忆性散文集（1928），含《从百草园到三味书屋》《藤野先生》《范爱农》《父亲的病》。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd065","item":"《女神》：郭沫若1921年出版，中国现代文学史上第一部真正的新诗集，含《凤凰涅槃》《天狗》《炉中煤》，风格狂飙突进。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd066","item":"《子夜》：茅盾1933年长篇小说，以民族资本家吴荪甫为中心，展现20世纪30年代上海社会全貌，是社会分析小说典范。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd067","item":"《激流三部曲》：《家》《春》《秋》，巴金代表作，写高家封建大家庭的崩溃与青年觉醒；家；春；秋","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd068","item":"《骆驼祥子》：老舍1936年长篇小说，写人力车夫祥子三起三落的悲剧，京味语言典范。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd069","item":"《茶馆》：老舍1957年话剧，三幕写清末、民初、抗战后三个时代，以裕泰茶馆兴衰折射社会变迁。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd070","item":"《边城》：沈从文1934年中篇小说，写湘西茶峒少女翠翠的爱情悲剧，表现人性之美。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd071","item":"《围城》：钱锺书1947年长篇小说，主人公方鸿渐，以『城外的人想冲进去，城里的人想逃出来』喻人生困境，被誉为『新儒林外史』。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd072","item":"《沉沦》：郁达夫1921年短篇小说集，中国现代文学史上第一部短篇小说集，写留日学生的性苦闷与弱国子民悲哀。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd073","item":"《雷雨》：曹禺1934年话剧，写周朴园、繁漪、侍萍、四凤等八个人物一天之内的悲剧，是中国现代话剧的里程碑。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd074","item":"《日出》：曹禺1936年话剧，以交际花陈白露为中心，写『损不足以奉有余』的社会。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd075","item":"《北京人》：曹禺1940年话剧，写曾皓一家的衰败，以『北京人』作原始生命力的象征。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd076","item":"《原野》：曹禺1937年话剧，写仇虎复仇故事，带表现主义色彩。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd077","item":"《雨巷》：戴望舒1928年诗作，写『丁香一样地结着愁怨的姑娘』，音节优美，因此被称为『雨巷诗人』。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd078","item":"《大堰河——我的保姆》：艾青1933年诗作，写劳动妇女大堰河的悲苦一生，感情深沉。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd079","item":"《白毛女》：延安鲁艺集体创作，贺敬之、丁毅执笔，中国新歌剧奠基之作，写喜儿的遭遇。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd080","item":"《王贵与李香香》：李季1946年长篇叙事诗，采用陕北民歌『信天游』形式，写农村青年爱情与革命。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd081","item":"《华威先生》：张天翼1938年短篇小说，塑造『华威先生』这一抗战中空谈误事的官僚典型。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd082","item":"《包身工》：夏衍1936年报告文学，揭露日本纱厂包身工制度的残酷，是中国报告文学奠基之作。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd083","item":"《小二黑结婚》：赵树理1943年短篇小说，写农村青年争取婚姻自主，语言通俗，是解放区文学代表作。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd084","item":"《荷花淀》：孙犁1945年短篇小说，写白洋淀妇女送夫参军，诗情画意，开创『荷花淀派』。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd085","item":"《太阳照在桑干河上》：丁玲1948年长篇小说，写土改斗争，获1951年斯大林文学奖。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd086","item":"《暴风骤雨》：周立波1948年长篇小说，写东北元茂屯土改，获斯大林文学奖。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd087","item":"《围城》之外，钱锺书还著有学术著作《谈艺录》《管锥编》《宋诗选注》。","dynasty":"现代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd001","item":"伤痕文学：1977—1979年出现的文学潮流，因卢新华短篇小说《伤痕》得名，代表作刘心武《班主任》、卢新华《伤痕》、冯骥才《啊！》，写文革给人们造成的心灵创伤；《班主任》；刘心武；《伤痕》；卢新华","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd002","item":"反思文学：1979年后继伤痕文学而起，不止揭露创伤，更从政治、历史层面追问根源。代表茹志鹃《剪辑错了的故事》、高晓声《李顺大造屋》、王蒙《蝴蝶》、张贤亮《绿化树》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd003","item":"改革文学：1979年后写经济体制改革中的矛盾与新人。代表蒋子龙《乔厂长上任记》（开山之作）、柯云路《新星》、张洁《沉重的翅膀》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd004","item":"寻根文学：1985年前后兴起，主张挖掘民族文化心理与地域文化之『根』。代表韩少功《爸爸爸》、阿城《棋王》、王安忆《小鲍庄》、郑义《老井》、贾平凹商州系列；贾平凹；鬼才；《天狗》；《秦腔》","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd005","item":"先锋文学：20世纪80年代中后期，重叙事实验与形式探索，打破传统情节。代表马原《拉萨河女神》《冈底斯的诱惑》、余华《十八岁出门远行》、苏童《1934年的逃亡》、格非《褐色鸟群》、孙甘露。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd006","item":"新写实小说：20世纪80年代末兴起，写凡人琐事、零度情感、还原生活本相。代表池莉《烦恼人生》、方方《风景》、刘震云《一地鸡毛》、刘恒《狗日的粮食》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd007","item":"朦胧诗派：1970年代末兴起，意象朦胧、重视主体意识，代表北岛《回答》、顾城《一代人》、舒婷《致橡树》、江河、杨炼；顾城，舒婷，北岛","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd008","item":"山药蛋派：以赵树理为代表，马烽、西戎、束为、孙谦等山西作家群，写农村生活，语言通俗幽默，有乡土气息。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd009","item":"荷花淀派：以孙犁为代表，刘绍棠、从维熙、韩映山等，写冀中水乡，笔调清新诗化。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd010","item":"白洋淀诗群：1960年代末—1970年代，食指、芒克、多多等在北京周边插队青年的地下诗歌，是朦胧诗的前身。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd011","item":"女性文学：20世纪80—90年代女性作家群崛起，代表王安忆、铁凝、张洁、张抗抗、陈染、林白、徐坤，关注女性经验与性别意识。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd012","item":"新历史小说：20世纪80年代末—90年代，以个人视角重写历史。代表苏童《妻妾成群》《米》、莫言《红高粱》、叶兆言《夜泊秦淮》、刘震云《故乡天下黄花》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd020","item":"赵树理：山药蛋派创始人，代表作《小二黑结婚》《李有才板话》《李家庄的变迁》，语言通俗、富于幽默，被称为『农民作家』；开创了山药蛋派；写农村的铁笔圣手；《小二黑结婚》","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd021","item":"孙犁：荷花淀派创始人，代表作《荷花淀》《芦花荡》，小说散文合集《白洋淀纪事》，风格清新诗化；短篇小说《荷花淀》“荷花派”；《荷花淀》《芦花荡》——短篇小说；《风云初记》——长篇小说；《铁木前传》——中篇小说；荷花淀派创始人；《荷花淀》；白洋淀纪事","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd023","item":"柳青：代表作《创业史》，塑造梁生宝、梁三老汉等农民形象；《创业史》；梁宝生、改霞","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd024","item":"梁斌：代表作《红旗谱》，塑造朱老忠这一农民英雄形象；《红旗谱》；描绘农民革命斗争的壮丽史诗","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd026","item":"曲波：代表作《林海雪原》，塑造孤胆英雄杨子荣。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd027","item":"吴强：代表作《红日》，写孟良崮战役。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd028","item":"罗广斌、杨益言：合著《红岩》，塑造江姐、许云峰、成岗等革命者形象。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd029","item":"王蒙：代表作《组织部来了个年轻人》（1956，反官僚主义）、《活动变人形》《春之声》，曾任文化部部长；《组织上来了个年轻人》；短片小说","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd030","item":"刘心武：代表作《班主任》（1977，伤痕文学发端之作）、《钟鼓楼》（获茅盾文学奖）。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd031","item":"高晓声：代表作《陈奂生上城》《李顺大造屋》，塑造农民陈奂生形象，写『漏斗户』的辛酸与自尊。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd032","item":"汪曾祺：京派余韵，代表作《受戒》《大淖记事》《岁寒三友》，文风冲淡隽永，善写民俗与吃食；中国最后一个纯粹的文人，《高邮鸭蛋》，拜沈从文为老师；中国最后一个士大夫；受戒；逝水","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd033","item":"贾平凹：代表作《废都》《秦腔》（获茅盾文学奖）《浮躁》《高兴》，写商州与西安的世情；长篇小说：《秦腔》《废都》；短篇小说：《山地笔记》《腊月·正月》《天狗》","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd034","item":"路遥：代表作《人生》（高加林）、《平凡的世界》（孙少安、孙少平，获茅盾文学奖），写陕北城乡青年的奋斗；中篇小说：《人生》；长篇小说：《平凡的世界》《平凡的世界》；孙少安；孙少平","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd035","item":"陈忠实：代表作《白鹿原》（获茅盾文学奖），以白嘉轩、鹿子霖两大家族写关中五十年变迁；长篇小说：《白鹿原》；“陕军东征的三驾马车”：陈忠实《白鹿原》、贾平凹《废都》、高建群《最后一个匈奴》","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd036","item":"莫言：2012年诺贝尔文学奖得主，代表作《红高粱家族》《丰乳肥臀》《檀香刑》《生死疲劳》《蛙》（获茅盾文学奖），以『高密东北乡』为文学故乡，风格魔幻现实主义；“寻根文学”，其作品深受魔幻现实主义影响；中篇小说：《透明的胡萝卜》；长篇小说：《檀香刑》；《红高粱》；主人公：余占鳌和戴凤莲；《蛙》（娃）中国由计划生育到试管婴儿","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd037","item":"余华：代表作《活着》（福贵）、《许三观卖血记》《在细雨中呼喊》《兄弟》《第七天》，写苦难与生存；长篇小说：《活着》《在细雨中呼喊》《许三观卖血记》《兄弟》；短篇小说：《世事如烟》《我胆小如鼠》","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd038","item":"苏童：代表作《妻妾成群》（后改编为电影《大红灯笼高高挂》）《米》《河岸》《黄雀记》（获茅盾文学奖）。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd039","item":"格非：先锋小说代表，代表作《褐色鸟群》《人面桃花》（江南三部曲，获茅盾文学奖）。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd040","item":"马原：先锋小说开拓者，代表作《拉萨河女神》《冈底斯的诱惑》，被称为『叙事圈套』的制造者。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd041","item":"王朔：代表作《动物凶猛》（后改编为《阳光灿烂的日子》）《顽主》《看上去很美》，语言调侃，人称『痞子文学』。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd042","item":"王小波：代表作《黄金时代》《白银时代》《青铜时代》《一只特立独行的猪》，以黑色幽默与自由主义精神著称；时代三部曲；《青铜时代》；《黄金时代》；《白银时代》","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd043","item":"刘震云：代表作《一地鸡毛》《单位》《手机》《一句顶一万句》（获茅盾文学奖）《我不是潘金莲》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd044","item":"阿城：代表作《棋王》《树王》《孩子王》，『三王』系列写知青生活，笔调淡远。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd045","item":"韩少功：寻根文学倡导者，代表作《爸爸爸》（丙崽）《马桥词典》《女女女》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd046","item":"张承志：代表作《黑骏马》《北方的河》《心灵史》，写草原与回族哲合忍耶。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd047","item":"张炜：代表作《古船》《九月寓言》《你在高原》（获茅盾文学奖）。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd048","item":"王安忆：代表作《长恨歌》（王琦瑶，获茅盾文学奖）《小鲍庄》《本次列车终点》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd049","item":"铁凝：代表作《哦，香雪》《玫瑰门》《大浴女》《笨花》，短篇《长街短梦》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd050","item":"迟子建：代表作《额尔古纳河右岸》（获茅盾文学奖）《白雪乌鸦》《世界上所有的夜晚》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd051","item":"毕飞宇：代表作《青衣》《玉米》《平原》《推拿》（获茅盾文学奖），写盲人推拿师。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd052","item":"麦家：谍战小说代表，代表作《解密》《暗算》《风声》，『谍战之父』。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd053","item":"刘慈欣：科幻作家，代表作《三体》三部曲（2015年获雨果奖最佳长篇）《流浪地球》《球状闪电》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd054","item":"郝景芳：科幻作家，代表作《北京折叠》，2016年获雨果奖最佳短中篇。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd055","item":"梁晓声：代表作《今夜有暴风雪》《雪城》《人世间》（获茅盾文学奖，改编同名电视剧）。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd056","item":"史铁生：代表作《我与地坛》《务虚笔记》《病隙碎笔》，写残疾与生命哲思；《我的遥远的清平湾》《插队的故事》《夏日玫瑰》《合欢树》；散文：《我与地坛》《自言自语》","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd057","item":"舒婷：朦胧诗派代表，代表作《致橡树》《神女峰》《双桅船》《祖国啊，我亲爱的祖国》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd058","item":"顾城：朦胧诗派代表，代表作《一代人》（『黑夜给了我黑色的眼睛，我却用它寻找光明』）《远和近》《我是一个任性的孩子》童话诗人；一代人","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd059","item":"北岛：朦胧诗派代表，代表作《回答》（『卑鄙是卑鄙者的通行证，高尚是高尚者的墓志铭』）《一切》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd060","item":"海子：当代诗人，代表作《面朝大海，春暖花开》《亚洲铜》《春天，十个海子》查海生；《面朝大海，春暖花开》","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd061","item":"余光中：台湾诗人、散文家，代表作《乡愁》（邮票、船票、坟墓、海峡四个意象）《乡愁四韵》《听听那冷雨》“乡愁诗人”；《听听那冷雨》","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd062","item":"席慕蓉：台湾女诗人、画家，代表作《七里香》《无怨的青春》《一棵开花的树》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd063","item":"三毛：台湾女作家，代表作《撒哈拉的故事》《雨季不再来》《梦里花落知多少》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd064","item":"白先勇：台湾作家，代表作《台北人》《孽子》《游园惊梦》，写迁台大陆人的乡愁与没落。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd065","item":"金庸：新派武侠小说宗师，代表作《射雕英雄传》《神雕侠侣》《倚天屠龙记》《天龙八部》《笑傲江湖》《鹿鼎记》，『飞雪连天射白鹿，笑书神侠倚碧鸳』。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd066","item":"琼瑶：台湾言情小说家，代表作《窗外》《几度夕阳红》《还珠格格》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd067","item":"食指：原名郭路生，代表作《相信未来》《这是四点零八分的北京》，是朦胧诗的先驱。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd068","item":"汪国真：当代诗人，代表作《热爱生命》《年轻的潮》，诗风浅白励志。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd069","item":"杨绛：作家、翻译家，代表作散文《干校六记》《我们仨》、小说《洗澡》，译有《堂吉诃德》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd070","item":"张洁：代表作《沉重的翅膀》（获茅盾文学奖）《爱，是不能忘记的》《无字》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd071","item":"张贤亮：代表作《灵与肉》（改编为《牧马人》）《绿化树》《男人的一半是女人》。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd072","item":"冯骥才：代表作《啊！》《神鞭》《三寸金莲》，津味小说代表，亦为民间文化保护者。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd080","item":"《班主任》：刘心武1977年发表，塑造谢惠敏、宋宝琦，被视为伤痕文学发端之作。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd081","item":"《伤痕》：卢新华1978年发表，写王晓华与母亲，『伤痕文学』即由此得名。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd082","item":"《乔厂长上任记》：蒋子龙1979年发表，塑造改革者乔光朴，开改革文学先河。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd083","item":"《陈奂生上城》：高晓声1980年发表，写农民陈奂生进城住招待所的窘态与自得，含泪的幽默。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd084","item":"《棋王》：阿城1984年发表，写知青王一生痴迷象棋，『何以解忧，唯有象棋』。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd085","item":"《爸爸爸》：韩少功1985年发表，写畸形儿丙崽与鸡头寨，是寻根文学代表作。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd086","item":"《红高粱》：莫言1986年发表，写『我爷爷』余占鳌与『我奶奶』戴凤莲，1987年张艺谋改编为电影。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd087","item":"《活着》：余华1992年长篇小说，写福贵一生的苦难与承受，『人是为活着本身而活着的』。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd088","item":"《白鹿原》：陈忠实1993年长篇小说，1997年获茅盾文学奖，写白嘉轩、鹿子霖两家恩怨。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd089","item":"《平凡的世界》：路遥1988年完成，1991年获茅盾文学奖，写孙少安、孙少平兄弟在改革年代的奋斗。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd090","item":"《长恨歌》：王安忆1995年长篇小说，2000年获茅盾文学奖，写上海女子王琦瑶一生。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd091","item":"《我与地坛》：史铁生1991年散文，写作者与地坛、与母亲，探讨生死与苦难意义。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd092","item":"《乡愁》：余光中1972年诗作，用『邮票』『船票』『坟墓』『海峡』四个意象写乡愁。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd093","item":"《面朝大海，春暖花开》：海子1989年诗作，写对尘世幸福的祝福。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd094","item":"《致橡树》：舒婷1977年诗作，以木棉与橡树喻平等独立的爱情。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd095","item":"《一代人》：顾城1979年两行诗——『黑夜给了我黑色的眼睛，我却用它寻找光明』。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd096","item":"《回答》：北岛1976年诗作，『卑鄙是卑鄙者的通行证，高尚是高尚者的墓志铭』。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd097","item":"《三体》：刘慈欣科幻三部曲（《三体》《黑暗森林》《死神永生》），2015年获雨果奖最佳长篇小说，亚洲首次。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd098","item":"《一只特立独行的猪》：王小波杂文，以一只拒绝被安排的猪喻独立自由的人格。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"dd099","item":"《安居》：梁晓声《人世间》写周秉昆等平民子弟五十年人生，2019年获茅盾文学奖。","dynasty":"当代","cat":"补充","source":"文学常识补充（教材通行说法）"},{"id":"xd118","item":"小说集：《呐喊》中国现代小说的伟大开端：《风波》；中心线索：“辫子事件”；七斤嫂、七斤、九斤老太（“一代不如一代”）；《狂人日记》（第一篇白话文小说）；《明天》《阿Q正传》《孔乙己》《一件小事》《药》《故乡》；《彷徨》；《祝福》《伤逝》（主人公：子君、涓生）《在酒楼上》《幸福家庭》；《故事新编》；激流三部曲：《家》（成就最高，奠定巴金在中国文学史地位的作品小说，主人公：觉民、觉慧、觉新（长兄））《春》《秋》；爱情三部曲：《雾》《雨》《电》","dynasty":"现代","cat":"作家作品","source":"幕布笔记整理"},{"id":"xd119","item":"散文集：《朝花夕拾》（《五猖会》）；《香市》一篇记事散文；巧用今昔对比手法和铺垫反衬；通过革命前后香市的变化，写农村萧条；文中多象征手法；“桃园”象征着革命前没有帝国主义侵略、没有军阀势力时的美好社会；“公安分局”象征着军阀势力已深入农村；“蚕种改良所”象征着帝国主义经济侵略；文章情理结合，议论与具象互相融合，手法上以小见大；随想录","dynasty":"当代","cat":"作家作品","source":"幕布笔记整理"},{"id":"xd120","item":"诗集：《野草》","dynasty":"当代","cat":"作家作品","source":"幕布笔记整理"},{"id":"xd121","item":"杂文集：《华盖集》《南腔北调》：《坟》；《灯下漫笔》；针对当时复古思潮的一篇文艺性政论文；“想做奴隶而不得的时代”和“暂时坐稳了奴隶的时代”的交替循环；把帝国主义在中国的特殊享受和权利，比作统治者用子女玉帛做成的“人肉筵席”；把中国几千年的“中国固有的文明”比喻成为给洋人享用的“人肉筵席”；把旧中国比作安排这一筵席的厨房；“太平的盛世”、“皇恩浩荡”、“我们极容易变成奴隶，而且变了之后，万分很喜欢”运用的修辞手法是反语","dynasty":"当代","cat":"作家作品","source":"幕布笔记整理"},{"id":"xd122","item":"原名：沈德鸿，字雁冰；原名：舒庆春，中国第一位获得“人民艺术家”称号，写市井生活和城市小市民命运而著称的作家；原名：吴尧棠，字芾甘","dynasty":"当代","cat":"作家作品","source":"幕布笔记整理"},{"id":"xd126","item":"中长篇小说：《月牙儿》：《断魂枪》；运用衬托和对比手法塑造人物；王三胜：争强好胜、爱脸面、鲁莽气盛、意气用事；孙老者：武艺精深、性格直爽、执着认真、武艺高超；沙子龙：深藏不露、固执保守、冷傲、悲凉、自我叹息；中长篇小说：《灭亡》（处女作）","dynasty":"当代","cat":"作家作品","source":"幕布笔记整理"},{"id":"xd128","item":"钱钟书的温度计作品几乎都是以讽刺为基调","dynasty":"当代","cat":"作家作品","source":"幕布笔记整理"},{"id":"xd129","item":"诗论：《谈艺录》","dynasty":"当代","cat":"作家作品","source":"幕布笔记整理"},{"id":"xd130","item":"古文笔记体著作：《管锥编》","dynasty":"当代","cat":"作家作品","source":"幕布笔记整理"},{"id":"xd131","item":"钱钟书：《围城》是钱钟书唯一一本长篇讽刺小说——被誉为“新儒林外史”：主人公：方渐鸿、唐晓芙、苏文执、赵辛楣、孙柔嘉、鲍小姐","dynasty":"当代","cat":"作家作品","source":"幕布笔记整理"},{"id":"xd132","item":"《论快乐》：选自散文集《写在人生边上》；是一篇有关于人生哲理方面的随笔；“一切快乐的享受都属于精神的”和“快乐由精神来决定”","dynasty":"当代","cat":"作家作品","source":"幕布笔记整理"},{"id":"xd133","item":"《人·兽·鬼》（短篇小说）","dynasty":"当代","cat":"作家作品","source":"幕布笔记整理"},{"id":"xd140","item":"中国现代话剧奠基人","dynasty":"现代","cat":"作家作品","source":"幕布笔记整理"}],"n":187}];
